def _write_sans_trial_crash(context, exc):
    """Salva erros Python da Julgamento Sans sem depender do console do Android."""
    try:
        base=os.path.dirname(os.path.abspath(__file__))
        path=os.path.join(base,"sans_trial_crash.log")
        with open(path,"a",encoding="utf-8") as f:
            f.write("\n=== SANS TRIAL | "+str(context)+" ===\n")
            f.write("Erro: "+repr(exc)+"\n")
            f.write(traceback.format_exc()+"\n")
        return path
    except Exception:
        return None

