def _load_optional_image(candidates):
    for path in candidates:
        try:
            if os.path.exists(path):
                img = pygame.image.load(path).convert_alpha()
                # Android/Pydroid: os PNGs da Lira sao grandes. Mantemos uma copia-base
                # reduzida para evitar smoothscale pesado no PRIMEIRO uso durante a luta.
                ow, oh = img.get_size()
                longest = max(ow, oh)
                if longest > 640:
                    scale = 640.0 / longest
                    img = pygame.transform.smoothscale(img, (max(8,int(ow*scale)), max(8,int(oh*scale))))
                return img
        except Exception:
            pass
    return None

