def _scaled_image(image, cache, size):
    if image is None:
        return None
    # Quantiza tamanhos para reduzir a quantidade de superficies diferentes no cache.
    size=max(8,int(round(float(size)/8.0)*8))
    if size not in cache:
        try:
            ow,oh=image.get_size(); ratio=oh/max(1,ow)
            # scale normal e muito mais barato que smoothscale por frame/tamanho no Android.
            cache[size]=pygame.transform.scale(image,(size,max(6,int(size*ratio))))
        except Exception:
            return None
    return cache.get(size)

