def _load_png_asset_exact(filename, max_base=None):
    """Carrega um PNG especifico sem fallback cruzado entre os ossos do Sans."""
    base = os.path.dirname(os.path.abspath(__file__))
    for folder in (os.path.join(base, "assets"), base):
        p = os.path.join(folder, filename)
        if not os.path.isfile(p):
            continue
        try:
            img = pygame.image.load(p).convert_alpha()
            if max_base:
                ow, oh = img.get_size()
                longest = max(ow, oh)
                if longest > max_base:
                    scale = max_base / float(longest)
                    img = pygame.transform.smoothscale(img, (max(8, int(ow*scale)), max(8, int(oh*scale))))
            return img
        except Exception as exc:
            print("Falha ao carregar asset do Sans:", p, exc)
    return None


def _ensure_sans_bone_images():
    """Carrega cada PNG de osso explicitamente; nenhum tipo usa o asset do outro."""
