def character_unlock_text(name):
    if name=="Kayk": return "Derrote o boss Pai do Kayk em uma run real."
    if name=="Pai do Kayk": return "Derrote o Pai do Kayk com Ana, Kevyn, Ycaro, Kayk, Pedro e Ruan."
    if name==HANK_KEY: return "Derrote A Sentinela com Ana, Kevyn, Ycaro, Kayk, Pedro e Ruan."
    if name=="Strikada Egoísta": return "Alcance a Wave 30 no PADRAO em dificuldade NORMAL ou superior."
    if name=="Glonk 100% Power": return f"Morra 100 vezes usando Glonk em runs reais. Progresso: {int(SAVE.get('glonk_deaths',0) if 'SAVE' in globals() else 0)}/100."
    if name==MAHORAGA_MODULE_KEY: return "Vença a PROVAÇÃO do Mahoraga no NORMAL ou superior e resgate a recompensa única."
    if name=="Sans": return "Venca o JULGAMENTO do Sans no NORMAL ou superior."
    if name==RIP_INDRA_KEY:
        if 'SAVE' not in globals(): return "Complete 50% das conquistas."
        normals=[a[0] for a in ACHIEVEMENTS if a[0]!="meta_all"]; done=sum(1 for k in normals if k in set(SAVE.get("unlocked_achievements",[])))
        return f"Complete 50% das conquistas. Progresso: {done}/{len(normals)}."
    if name==KIRA_KEY: return "Venca uma wave do BOSS RUSH no NORMAL ou superior sem receber dano."
    if name==HISOKA_KEY:
        n=len(set(SAVE.get("hisoka_impossible_wave30_chars",[]))) if 'SAVE' in globals() else 0
        return f"Wave 30 no IMPOSSIVEL com 3 personagens normais nao-principais. Beta nao conta. Progresso: {n}/3."
    if name in BETA_CHARACTER_ORDER: return "Disponivel para TESTE BETA. Beta nao concede recompensas/progresso permanente."
    return "Disponivel desde o inicio."

# Requisitos de compatibilidade para cartas universais antigas e novas.
# O primeiro mapa exige TODAS as tags; o segundo aceita QUALQUER uma delas.
UPGRADE_TAG_REQUIREMENTS = {
    "pierce": {"PROJECTILE"},
    "profane_ricochet": {"PROJECTILE"},
    "ghost_dash": {"DASH"},
    "domain_evolution": {"DOMAIN"},
    "devil_pact": {"DOMAIN"},
    "explosive_parry": {"PARRY"},
    "blade_vampire": {"MELEE"},
    "chaotic_ammo": {"PROJECTILE"},
    "supreme_command": {"SUMMON"},
    "inertia": {"DASH"},
    "overpressure": {"AOE"},
    "resonant_domain": {"DOMAIN"},
    "auto_loader": {"TURRET"},
}
UPGRADE_TAG_ANY = {
    "kinetic_rebound": {"BALL", "BOOMERANG"},
}

def upgrade_compatible(card, character):
    key = card[3]
    tags = CHARACTER_TAGS.get(character, set())
    required = UPGRADE_TAG_REQUIREMENTS.get(key, set())
    any_required = UPGRADE_TAG_ANY.get(key, set())
    if required and not required.issubset(tags):
        return False
    if any_required and not (tags & any_required):
        return False
    return True

