def chromatic_color(offset=0.0):
    h=((pygame.time.get_ticks()/2600.0)+float(offset))%1.0
    r,g,b=colorsys.hsv_to_rgb(h,0.78,1.0)
    return (int(r*255),int(g*255),int(b*255))

def title_catalog_entry_by_value(value):
    val=str(value or "")
    for key,info in SHOP_COSMETICS.items():
        if info.get("kind")=="title" and str(info.get("value",""))==val:
            return key,info
    for key,info in ROTATING_TITLE_CATALOG.items():
        if str(info.get("value",""))==val:
            return key,info
    return None,None

def profile_title_description(value):
    _,info=title_catalog_entry_by_value(value)
    if info: return str(info.get("desc","") or "")
    achievement={
        "O SOBREVIVENTE":"Sobreviveu longe o bastante para deixar de parecer sorte.",
        "YOU WON'T PASS":"Venceu um Clash de Domínios.",
        "CAÇADOR DE GLONK":"Encontrou o problema verde e decidiu que ele era a caça.",
        "EU ME ADAPTEI":"Venceu a Provação do Mahoraga.",
        "O GORDO CAIU":"A queda que justificou o nome do jogo.",
        "ARQUIVISTA DO FIM":"Completou o Bestiário e registrou tudo que tentou matar você.",
    }
    return achievement.get(str(value or ""),"Título equipado no Registro do Jogador.")

def title_display_color(value, fallback=CYAN):
    _,info=title_catalog_entry_by_value(value)
    if info:
        if info.get("chromatic"): return chromatic_color()
        return info.get("color",fallback)
    return fallback

