PERMANENT_UPGRADE_CAP = 60

def permanent_effective_level(key_or_level):
    """Retorno decrescente: LV1-20 = 100%, 21-40 = 50%, 41-60 = 25%."""
    if isinstance(key_or_level, str):
        lvl=max(0,min(PERMANENT_UPGRADE_CAP,int(SAVE.get(key_or_level,0) or 0))) if 'SAVE' in globals() else 0
    else:
        lvl=max(0,min(PERMANENT_UPGRADE_CAP,int(key_or_level or 0)))
    return min(lvl,20) + max(0,min(lvl-20,20))*0.50 + max(0,min(lvl-40,20))*0.25

def permanent_upgrade_cost(base, level):
    # Curva progressiva: +14% por nivel. Com ~400K moedas, da para montar uma boa conta
    # (cerca de LV25 medio na loja inteira), mas maximizar LV60 continua sendo projeto de longo prazo.
    return max(int(base), int(round(float(base) * (1.14 ** max(0,int(level))))))

def format_big_money(value):
    value=int(value)
    for div,suf in ((10**15,'Q'),(10**12,'T'),(10**9,'B'),(10**6,'M'),(10**3,'K')):
        if value>=div:
            return f"{value/div:.1f}{suf}"
    return str(value)

