def _passive(key, rarity, name, en, desc, family=None, rollable=True, characters=None):
    return {"key":key,"rarity":rarity,"name":name,"en":en,"desc":desc,"family":family,"rollable":rollable,"characters":tuple(characters) if characters else ()}

def passive_allowed_for_character(item, character):
    allowed=tuple(item.get("characters",()) or ())
    return (not allowed) or character in allowed

