def usable_item_amount(key):
    if SAVE.get("cheat_items_infinite", False):
        return 9999
    inv=SAVE.get("usable_items",{})
    return max(0,int(inv.get(key,0))) if isinstance(inv,dict) else 0

def consumable_remaining(key):
    active=SAVE.get("active_consumables",{})
    if not isinstance(active,dict): return 0.0
    try: return max(0.0,float(active.get(key,0.0))-time.time())
    except Exception: return 0.0

def consumable_active(key):
    return consumable_remaining(key)>0.0

def activate_consumable(key):
    info=CONSUMABLES.get(key)
    if not info: return False
    if usable_item_amount(key)<=0 and not SAVE.get("cheat_items_infinite",False): return False
    inv=SAVE.setdefault("usable_items",{})
    if not SAVE.get("cheat_items_infinite",False):
        inv[key]=max(0,int(inv.get(key,0))-1)
    active=SAVE.setdefault("active_consumables",{})
    now=time.time(); current=max(now,float(active.get(key,0.0) or 0.0))
    active[key]=current+float(info.get("duration",600))
    save_data(SAVE)
    return True

SHOP_GLOBAL_PRICE_MULT = 1.15
SHOP_DISCOUNT_MIN = 0.001
SHOP_DISCOUNT_MAX = 0.40

def _shop_weapon_price(recipe):
    if not recipe: return 999999
    return int(SHOP_WEAPON_PRICES.get(recipe.get("rarity"),12000) + max(0,int(recipe.get("coins",0)))*2)

def _shop_discount(value, low=0.12, high=0.28):
    # Loja V16.3: qualquer oferta pode ser desde a sacanagem de 0,1% ate 40%.
    pct=random.uniform(SHOP_DISCOUNT_MIN,SHOP_DISCOUNT_MAX)
    price=max(1,int(round(value*(1.0-pct)/50.0))*50)
    return price, round(pct*100.0,1)

def _shop_make_material(key, qty, discount=(0.08,0.22), badge="OFERTA DE FORJA"):
    original=int(SHOP_MATERIAL_PRICES.get(key,500)*qty)
    price,pct=_shop_discount(original,*discount)
    return {"type":"material","key":key,"qty":int(qty),"price":price,"original":original,"discount":pct,"badge":badge}

def _shop_make_consumable(key, qty=1, discount=(0.10,0.25), badge="BOOST 10 MIN"):
    base=int(CONSUMABLES[key]["price"]); original=base*qty
    price,pct=_shop_discount(original,*discount)
    return {"type":"consumable","key":key,"qty":int(qty),"price":price,"original":original,"discount":pct,"badge":badge}

def _shop_make_weapon(key, discount=(0.10,0.25), badge="DESTAQUE DO DIA"):
    recipe=FORGE_WEAPON_BY_KEY[key]; original=_shop_weapon_price(recipe)
    price,pct=_shop_discount(original,*discount)
    return {"type":"weapon","key":key,"qty":1,"price":price,"original":original,"discount":pct,"badge":badge}

def _shop_make_rotating_title(force_ultra=None):
    owned=set(SAVE.get("cosmetics_owned",[]))
    ultra=[(k,v) for k,v in ROTATING_TITLE_CATALOG.items() if v.get("category")=="ultra" and k not in owned]
    normal=[(k,v) for k,v in ROTATING_TITLE_CATALOG.items() if v.get("category")!="ultra" and k not in owned]
    if force_ultra is True:
        pool=ultra or normal
    elif force_ultra is False:
        pool=normal or ultra
    else:
        pool=(ultra if ultra and random.random()<0.08 else normal) or ultra
    if not pool:
        pool=list(ROTATING_TITLE_CATALOG.items())
    key,info=random.choice(pool)
    out={"type":"cosmetic","key":key,"kind":"title","name":"TITULO: "+str(info.get("name",info.get("value","TITULO"))),
         "value":info.get("value",""),"price":int(info.get("price",30000)),"original":int(info.get("price",30000)),
         "discount":0.0,"color":info.get("color",PURPLE),"badge":info.get("badge","TITULO ROTATIVO"),
         "desc":info.get("desc",""),"chromatic":bool(info.get("chromatic",False)),"category":info.get("category","aura")}
    return out

def generate_daily_shop():
    crafted=set(SAVE.get("crafted_weapons",[]))
    weapons=[w for w in FORGE_WEAPONS if not w.get("preview",False) and w.get("rarity")!="divine" and w.get("key") not in crafted]
    if len(weapons)<6:
        weapons=[w for w in FORGE_WEAPONS if not w.get("preview",False) and w.get("rarity")!="divine"]
    random.shuffle(weapons)
    weapon_keys=[w["key"] for w in weapons[:6]]
    while len(weapon_keys)<6 and weapons:
        weapon_keys.append(random.choice(weapons)["key"])
    cons=list(CONSUMABLES); random.shuffle(cons)
    sins=list(SIN_FRAGMENTS); random.shuffle(sins)
    offers=[]
    # Pagina 1: vitrine de entrada.
    offers.append(_shop_make_weapon(weapon_keys[0],(0.20,0.32),"OFERTA PRINCIPAL"))
    offers.append(_shop_make_material("scrap",random.randint(10,16),(0.10,0.22),"PACOTE DE FORJA"))
    offers.append(_shop_make_material("essence",random.randint(5,9),(0.12,0.24),"PACOTE DE FORJA"))
    offers.append(_shop_make_consumable(cons[0],1,(0.15,0.30),"POCAO EM PROMOCAO"))
    k=cons[1]; base=int(CONSUMABLES[k]["price"]); pack_original=base*2; pack_price=max(1,int(round(pack_original*(1.0-SHOP_DISCOUNT_MAX)/50.0))*50); offers.append({"type":"consumable","key":k,"qty":2,"price":pack_price,"original":pack_original,"discount":40.0,"badge":"PACOTE DUPLO"})
    # Pagina 2: materiais raros + outra arma.
    offers.append(_shop_make_weapon(weapon_keys[1],(0.12,0.24),"ARSENAL ROTATIVO"))
    offers.append(_shop_make_material("core",random.randint(3,5),(0.10,0.20),"NUCLEOS"))
    offers.append(_shop_make_material("domain_crystal",random.randint(2,4),(0.08,0.18),"CRISTAIS"))
    offers.append(_shop_make_consumable(cons[2],1,(0.10,0.22),"BOOST 10 MIN"))
    offers.append(_shop_make_material(sins[0],1,(0.05,0.12),"FRAGMENTO DO PECADO"))
    # Pagina 3: itens de fim de jogo + ESCOLHA UM.
    offers.append(_shop_make_weapon(weapon_keys[2],(0.08,0.18),"ARMA DE ALTO NIVEL"))
    offers.append(_shop_make_material("boss_heart",random.randint(1,2),(0.08,0.16),"CORACAO DO REI"))
    offers.append(_shop_make_material(sins[1] if len(sins)>1 else sins[0],1,(0.04,0.10),"FRAGMENTO RARO"))
    offers.append(_shop_make_consumable(cons[3],1,(0.12,0.24),"ULTIMO BOOST"))
    choices=weapon_keys[3:6]
    choose_price=max(_shop_weapon_price(FORGE_WEAPON_BY_KEY[k]) for k in choices) if choices else 25000
    choose_price=int(round(choose_price*1.10/50.0))*50
    offers.append({"type":"choose_weapon","choices":choices,"qty":1,"price":choose_price,"original":choose_price,"discount":0,"badge":"ESCOLHA 1 ARMA"})
    # Dois espaços da vitrine diária viram títulos rotativos. Ultra raro tem 8% de chance por slot.
    if len(offers)>8: offers[8]=_shop_make_rotating_title()
    if len(offers)>13: offers[13]=_shop_make_rotating_title()
    SAVE["daily_shop_offers"]=offers
    SAVE["daily_shop_purchased"]=[]
    SAVE["daily_shop_reset_at"]=time.time()+DAILY_SHOP_SECONDS
    save_data(SAVE)
    return offers

def ensure_daily_shop():
    offers=SAVE.get("daily_shop_offers",[])
    try: reset=float(SAVE.get("daily_shop_reset_at",0) or 0)
    except Exception: reset=0
    invalid_discount = isinstance(offers,list) and any(float(o.get("discount",0) or 0)>SHOP_DISCOUNT_MAX*100.0+0.001 for o in offers if isinstance(o,dict))
    missing_title_rotation = isinstance(offers,list) and not any(isinstance(o,dict) and o.get("type")=="cosmetic" and o.get("kind")=="title" and str(o.get("key","")).startswith("rot_title_") for o in offers)
    if not isinstance(offers,list) or len(offers)<15 or time.time()>=reset or invalid_discount or missing_title_rotation:
        return generate_daily_shop()
    return offers

