def generate_seuze_shop():
    offers=[]
    # O antigo Mercado Misterioso vive permanentemente no estoque do Seu Ze.
    for src in MYSTERY_MARKET_POOL:
        o=dict(src)
        o["type"]="seuze_special"
        o["original"]=int(o.get("price",0) or 0)
        o["badge"]="SEU ZE • "+str(o.get("badge","RARIDADE")).upper()
        offers.append(o)

    # Mais 8 mercadorias reais e aleatorias a cada renovacao: boosts, materiais,
    # reliquias e uma arma. Nenhum placeholder TESTE permanece na loja.
    consumable_keys=list(CONSUMABLES.keys()); random.shuffle(consumable_keys)
    for key in consumable_keys:
        qty=2 if random.random()<0.22 else 1
        offers.append(_shop_make_consumable(key,qty,(SHOP_DISCOUNT_MIN,SHOP_DISCOUNT_MAX),"BOOST DO SEU ZE"))

    material_keys=[k for k in SHOP_MATERIAL_PRICES.keys() if k not in SIN_FRAGMENTS]
    random.shuffle(material_keys)
    for key in material_keys[:2]:
        qty=random.randint(2,6) if key not in ("scrap","essence") else random.randint(6,14)
        offers.append(_shop_make_material(key,qty,(SHOP_DISCOUNT_MIN,SHOP_DISCOUNT_MAX),"MERCADORIA DE FORJA"))

    if SHOP_RELICS:
        rk=random.choice(list(SHOP_RELICS.keys())); info=dict(SHOP_RELICS[rk])
        original=max(1,int(info.get("price",12000) or 12000)); price,pct=_shop_discount(original,SHOP_DISCOUNT_MIN,SHOP_DISCOUNT_MAX)
        offers.append({"type":"relic","key":rk,"name":info.get("name",rk.upper()),"price":price,"original":original,"discount":pct,"color":info.get("color",PURPLE),"badge":"RELIQUIA DO BALCAO","desc":info.get("desc","")})

    candidates=[w for w in FORGE_WEAPONS if not w.get("preview",False) and w.get("rarity")!="divine"]
    if candidates:
        w=random.choice(candidates); offers.append(_shop_make_weapon(w["key"],(SHOP_DISCOUNT_MIN,SHOP_DISCOUNT_MAX),"ARSENAL DO SEU ZE"))

    # Mantem exatamente 16 cards para preservar o layout vertical atual.
    while len(offers)<16:
        key=random.choice(consumable_keys)
        offers.append(_shop_make_consumable(key,1,(SHOP_DISCOUNT_MIN,SHOP_DISCOUNT_MAX),"BOOST EXTRA"))
    offers=offers[:16]
    SAVE["seuze_shop_offers"]=offers
    SAVE["seuze_shop_purchased"]=[]
    SAVE["seuze_shop_reset_at"]=time.time()+DAILY_SHOP_SECONDS
    save_data(SAVE)
    return offers

