    offers=SAVE.get("seuze_shop_offers",[])
    try: reset=float(SAVE.get("seuze_shop_reset_at",0) or 0)
    except Exception: reset=0.0
    has_special=isinstance(offers,list) and any(isinstance(o,dict) and o.get("type")=="seuze_special" for o in offers)
    has_test=isinstance(offers,list) and any(isinstance(o,dict) and o.get("type")=="seuze_test" for o in offers)
