class Enemy:
    NEXT_ID = 1

    def __init__(self, pos, kind, wave, elite=None):
        self.id = Enemy.NEXT_ID
        Enemy.NEXT_ID += 1
        self.pos = pygame.Vector2(pos)
        self.kind = kind
        self.elite = elite
        self.radius = S(28)
        self.flash = 0
        self.shoot_cd = random.uniform(0.4, 1.4)
        self.touch_cd = 0
        self.dead = False
        self.marked = False
        self.blood_marked = False
        self.forge_slow_timer = 0.0
        self.powerup_damage_down_timer = 0.0
        self.coin_value = 2
        self.lira_censor = {"strength":0.0,"speed":0.0,"resistance":0.0,"intelligence":0.0}
        self.lira_domain_stats = set()
        self.lira_fully_censored = False
        self.lira_fully_censored_timer = 0.0

        combat_wave = effective_combat_wave(wave)
        self.combat_wave = combat_wave
        hp_scale, damage_scale, speed_scale = high_wave_scaling(wave)
        self.high_wave_hp_scale = hp_scale
        self.high_wave_damage_scale = damage_scale
        self.high_wave_speed_scale = speed_scale
        base_hp = (26 + combat_wave * 7) * hp_scale
        # V14 WIP 05: velocidade usa a WAVE REAL, nao a wave de combate 7x.
        # Wave 1 -> ~108 base; wave 100 -> ~116; teto total da curva = +12%.
        base_speed = S(108) * enemy_wave_speed_mult(wave)
        self.contact_damage = (7 + combat_wave * 0.7) * damage_scale

        if kind == "chaser":
            self.max_hp = base_hp * 1.15
            self.speed = base_speed * 1.15
            self.color = RED
        elif kind == "shooter":
            self.max_hp = base_hp
            self.speed = base_speed * 0.72
            self.color = ORANGE
        elif kind == "kiter":
            self.max_hp = base_hp * 0.85
            self.speed = base_speed * 1.05
            self.color = YELLOW
        else:  # tank
            self.max_hp = base_hp * 2.4
            self.speed = base_speed * 0.58
            self.radius = S(38)
            self.contact_damage *= 1.45
            self.color = PURPLE
            self.coin_value = 4

        if elite == "frenzy":
            self.speed *= 1.55
            self.color = PINK
            self.coin_value += 2
        elif elite == "giant":
            self.max_hp *= 2.1
            self.radius = int(self.radius * 1.35)
            self.contact_damage *= 1.3
            self.coin_value += 3
        elif elite == "armored":
            self.max_hp *= 1.65
            self.color = (150, 160, 175)
            self.coin_value += 3
        elif elite == "explosive":
            self.color = CYAN
            self.coin_value += 2

        self.hp = self.max_hp

    def lira_stat_level(self, stat, game=None):
        normal=clamp(float(getattr(self,"lira_censor",{}).get(stat,0.0)),0.0,1.0)
        if game is not None and getattr(game,"domain_active",False) and getattr(game.player,"character",None)==LIRA_KEY:
            if stat in getattr(self,"lira_domain_stats",set()):
                normal=max(normal,{"strength":0.70,"speed":0.50,"resistance":1.0,"intelligence":1.0}.get(stat,0.0))
        return normal

    def lira_outgoing_mult(self, game):
        return max(0.10,1.0-self.lira_stat_level("strength",game))

    def apply_lira_censor(self, stat, amount, game):
        if isinstance(self,Boss) or stat not in self.lira_censor:
            return False
        old=self.lira_censor[stat]
        self.lira_censor[stat]=min(0.60,old+max(0.0,amount))
        fully=all(v>0.0 for v in self.lira_censor.values())
        label={"strength":"FORCA","speed":"VELOCIDADE","resistance":"RESISTENCIA","intelligence":"INTELIGENCIA"}[stat]
        if self.lira_censor[stat]>old:
            game.damage_texts.append(DamageText(f"{label} -{int((self.lira_censor[stat]-old)*100)}%",pygame.Vector2(self.pos),LIRA_ACCENT,0.65))
        if fully:
            first_time = self.lira_fully_censored_timer <= 0.0
            self.lira_fully_censored = True
            self.lira_fully_censored_timer = 5.0
            if first_time:
                game.damage_texts.append(DamageText("TOTALMENTE C#NSUR#DO",pygame.Vector2(self.pos),WHITE,0.8))
        return True

    def damage(self, amount, game, source_pos=None, minimal_fx=False):
        if self.dead:
            return
        # POWER UPS 2.0: modificadores que dependem do alvo/fonte entram antes do HP.
        pwr_player = getattr(game, "player", None)
        pwr_source = getattr(game, "current_damage_kind", None) or ""
        if pwr_player is not None:
            projectile_sources = {"projectile","shotgun","dual_pistol","soul_shot","pineapple","pineapple_explosion","vasco_bet","lira_censor","hank_shell","hank_shell_explosion","sukuna_slash","vinicius_bolt","vinicius_turret","vinicius_ballistic","strikada_ball","sans_bone","kevyn_divine_slash","rip_wave","hisoka_card","hisoka_charged_card","hisoka_spider_card","hisoka_domain_card"}
            if getattr(pwr_player, "hybrid_chaotic_ammo", False) and pwr_source in projectile_sources and random.random() < 0.18:
                amount *= 1.60
                if not minimal_fx: game.damage_texts.append(DamageText("CAOS!", pygame.Vector2(self.pos), PURPLE, 0.45))
            if getattr(pwr_player, "lira_torn_page", False) and getattr(self, "lira_fully_censored", False):
                amount *= 1.50
            if getattr(pwr_player, "sukuna_adaptive_cut", False) and pwr_source == "sukuna_slash":
                last = getattr(pwr_player, "sukuna_adaptive_target", None)
                if last == self.id:
                    pwr_player.sukuna_adaptive_hits = min(6, getattr(pwr_player, "sukuna_adaptive_hits", 0) + 1)
                else:
                    pwr_player.sukuna_adaptive_target = self.id; pwr_player.sukuna_adaptive_hits = 0
                amount *= 1.0 + 0.10 * getattr(pwr_player, "sukuna_adaptive_hits", 0)
            if getattr(pwr_player, "strikada_protagonist", False) and pwr_source == "strikada_ball":
                # A contagem e guardada no projetil no loop de colisao; fallback neutro aqui.
                amount *= 1.0 + 0.12 * min(6, getattr(game, "strikada_current_bounces", 0))
        resist_censor=self.lira_stat_level("resistance",game)
        if self.elite=="armored" and resist_censor<0.999:
            amount*=0.72+0.28*resist_censor
        if resist_censor<0.999:
            amount*=1.0+0.25*resist_censor
        amount=max(0.0,float(amount))
        if amount>0 and getattr(game,"mode","")=="arena" and getattr(game,"player",None) is not None and not is_beta_character(game.player.character):
            SAVE["profile_max_hit"]=max(float(SAVE.get("profile_max_hit",0) or 0),float(amount))
        self.hp -= amount
        # V15 BALANCE: so ataques principais explicitamente marcados recarregam Dominio.
        # O valor bruto depende do tipo de ataque e passa pelo divisor global de 5x (~25 ataques).
        domain_raw = getattr(game, "current_domain_charge_raw_override", None)
        game.current_domain_charge_raw_override = None
        if amount > 0.0 and domain_raw is not None and domain_raw > 0.0:
            game.add_domain_charge(domain_raw)
        if hasattr(game, "record_clash_damage"):
            game.record_clash_damage(amount)
        if hasattr(game, "handle_powerup_hit") and amount > 0.0:
            game.handle_powerup_hit(self, amount, source_pos)
        self.flash = 0.08 if minimal_fx else 0.12
        if not minimal_fx:
            game.damage_texts.append(DamageText(str(int(amount)), pygame.Vector2(self.pos), WHITE))
            AUDIO.play("hit", 0.30, 38)
            game.spawn_particles(self.pos, self.color, 7)
            if source_pos is not None:
                knock = self.pos - source_pos
                if knock.length_squared() > 0:
                    self.pos += knock.normalize() * S(10)
        self.marked = self.hp <= self.max_hp * 0.18 and self.hp > 0
        if self.hp <= 0:
            self.die(game)

    def die(self, game):
        if self.dead:
            return
        self.dead = True
        game.kills += 1
        game.combo = min(50, game.combo + 1)
        game.combo_timer = 3.0
        if game.combo >= 50:
            game.unlock_achievement("combo_50")
        reward_mult = difficulty_cfg(getattr(game, "difficulty", "easy"))["reward"] if game.mode == "arena" else 1.0
        reward = int(self.coin_value * game.coin_multiplier * getattr(game,"meta_coin_multiplier",1.0) * reward_mult * (1.0 + 0.02 * permanent_effective_level("coin_level")) * max(0.10,1.0+getattr(game.player,"passive_coin_bonus",0.0)))
        if consumable_active("midas_potion") and random.random() < 0.35:
            reward *= 2
        game.run_coins += reward
        game.score += int(100 * (1 + game.combo * 0.08))
        AUDIO.play("enemy_die", 0.38, 45)
        game.spawn_particles(self.pos, self.color, 16)
        game.shake = max(game.shake, S(7))
        game.on_enemy_killed(self)

        if self.elite == "explosive":
            for i in range(8):
                v = vec_from_angle(i * math.tau / 8) * S(260)
                game.projectiles.append(Projectile(self.pos, v, 6, "enemy", S(9), CYAN))

        # Chuva de Orbes garante uma orb principal em elite. No EXTINCAO nunca nasce cura.
        extinction = getattr(game,"game_mode","normal") == "extinction"
        guaranteed = self.elite and game.player.orb_rain
        if guaranteed:
            game.drops.append(Drop(self.pos, "stamina" if extinction else random.choice(["heal", "stamina"])))

        bonus_each = game.player.drop_bonus * 0.5
        gift_mult = 1.75 if consumable_active("christmas_gift") else 1.0
        heal_chance = 0.0 if extinction else min(0.45, (0.14 + bonus_each) * gift_mult)
        stamina_chance = min(0.48 if extinction else 0.45, (0.18 + bonus_each if extinction else 0.14 + bonus_each) * gift_mult)
        shield_chance=0.05*gift_mult; haste_chance=0.05*gift_mult; coin_drop_chance=0.15*gift_mult
        roll = random.random()
        if roll < heal_chance:
            game.drops.append(Drop(self.pos, "heal"))
        elif roll < heal_chance + stamina_chance:
            game.drops.append(Drop(self.pos, "stamina"))
        elif roll < heal_chance + stamina_chance + shield_chance:
            game.drops.append(Drop(self.pos, "shield"))
        elif roll < heal_chance + stamina_chance + shield_chance + haste_chance:
            game.drops.append(Drop(self.pos, "haste"))
        elif roll < heal_chance + stamina_chance + shield_chance + haste_chance + coin_drop_chance:
            game.drops.append(Drop(self.pos, "coin"))

        # Materiais da Forja sao progresso persistente; Beta nao gera loot persistente.
        if hasattr(game, "roll_forge_drop"):
            game.roll_forge_drop(self)

    def update(self, dt, game):
        if self.dead:
            return
        self.flash = max(0, self.flash - dt)
        self.hisoka_stun_timer=max(0.0,getattr(self,"hisoka_stun_timer",0.0)-dt)
        if self.hisoka_stun_timer>0.0:
            return
        self.forge_slow_timer = max(0.0, getattr(self, "forge_slow_timer", 0.0) - dt)
        self.powerup_damage_down_timer = max(0.0, getattr(self, "powerup_damage_down_timer", 0.0)-dt)
        self.lira_fully_censored_timer = max(0.0, getattr(self, "lira_fully_censored_timer", 0.0) - dt)
        self.lira_fully_censored = self.lira_fully_censored_timer > 0.0
        lira_speed=self.lira_stat_level("speed",game)
        move_speed=self.speed*(0.55 if self.forge_slow_timer>0 else 1.0)*max(0.20,1.0-lira_speed)
        lira_intel=self.lira_stat_level("intelligence",game)
        lira_power=self.lira_outgoing_mult(game) * (0.65 if self.powerup_damage_down_timer>0 else 1.0)
        self.shoot_cd -= dt
        self.touch_cd -= dt

        target_entity = game.get_enemy_target(self.pos)
        to_player = target_entity.pos - self.pos
        dist = max(1, to_player.length())
        direction=to_player/dist
        # Atlas: inimigos comuns muito proximos entram em orbita e nao conseguem tocar nele. Bosses ignoram esta passiva.
        if game.player.character=="Atlas" and target_entity is game.player and not isinstance(self,Boss):
            orbit_r=game.player.radius+self.radius+S(58)
            if dist<orbit_r:
                ang=math.atan2(self.pos.y-game.player.pos.y,self.pos.x-game.player.pos.x)+dt*1.35
                self.pos=game.player.pos+vec_from_angle(ang)*orbit_r
                self.touch_cd=max(self.touch_cd,0.20)
                to_player=game.player.pos-self.pos; dist=max(1,to_player.length()); direction=to_player/dist
        atlas_domain_lock=(game.player.character=="Atlas" and game.domain_active and game.domain_name=="REFUTA ISSO NEWTON!!!" and game.is_in_domain(self.pos))
        if atlas_domain_lock:
            self.touch_cd=max(self.touch_cd,0.25); self.shoot_cd=max(self.shoot_cd,0.25)
        if lira_intel>=0.999:
            away=self.pos-game.player.pos
            direction=away.normalize() if away.length_squared()>0 else vec_from_angle(random.random()*math.tau)
        elif lira_intel>0 and random.random()<lira_intel:
            direction=vec_from_angle(random.random()*math.tau)

        hank_trapped = getattr(game, "hank_domain_active", False) and self.id in getattr(game, "hank_domain_trapped_ids", set())
        if hank_trapped:
            away = self.pos - game.player.pos
            if away.length_squared() <= 0:
                away = vec_from_angle(random.random()*math.tau)
            direction = away.normalize()

        if atlas_domain_lock:
            pass
        elif self.kind == "chaser" or self.kind == "tank":
            self.pos += direction * move_speed * dt
        elif self.kind == "shooter":
            if dist > S(470):
                self.pos += direction * move_speed * dt
            elif dist < S(300):
                self.pos -= direction * move_speed * dt
            if self.shoot_cd <= 0 and self.lira_fully_censored_timer <= 0.0:
                dcfg = difficulty_cfg(getattr(game, "difficulty", "easy")) if game.mode == "arena" else DIFFICULTIES["easy"]
                cw = effective_combat_wave(game.wave)
                speed = S(300 + cw * 5) * min(1.45, 1.0 + (dcfg["ai"]-1.0)*0.28)
                game.projectiles.append(Projectile(self.pos, direction * speed, (7 + cw * 0.55) * self.high_wave_damage_scale * dcfg["damage"] * lira_power, "enemy"))
                self.shoot_cd = max(0.22, (max(0.38, 1.45 - cw * 0.02)) / dcfg["ai"])
        elif self.kind == "kiter":
            tangent = pygame.Vector2(-direction.y, direction.x)
            if dist < S(360):
                move = -direction * 0.8 + tangent * 0.65
            else:
                move = direction * 0.35 + tangent * 0.8
            if move.length_squared() > 0:
                self.pos += move.normalize() * move_speed * dt
            if self.shoot_cd <= 0 and self.lira_fully_censored_timer <= 0.0:
                for off in (-0.12, 0.12):
                    a = math.atan2(direction.y, direction.x) + off
                    dcfg = difficulty_cfg(getattr(game, "difficulty", "easy")) if game.mode == "arena" else DIFFICULTIES["easy"]
                    shot_speed = S(330) * min(1.45, 1.0 + (dcfg["ai"]-1.0)*0.28)
                    cw = effective_combat_wave(game.wave)
                    game.projectiles.append(Projectile(self.pos, vec_from_angle(a) * shot_speed, (5 + cw * 0.45) * self.high_wave_damage_scale * dcfg["damage"] * lira_power, "enemy", S(8), YELLOW))
                dcfg = difficulty_cfg(getattr(game, "difficulty", "easy")) if game.mode == "arena" else DIFFICULTIES["easy"]
                self.shoot_cd = 1.8 / dcfg["ai"]

        # contato: amigos do Ruan podem realmente proteger o jogador e receber golpes.
        if dist < self.radius + target_entity.radius and self.touch_cd <= 0 and self.lira_fully_censored_timer <= 0.0:
            target_entity.take_damage(self.contact_damage*lira_power, game)
            self.touch_cd = 0.75
            if target_entity is game.player and direction.length_squared() > 0:
                game.player.pos += direction * S(28) * getattr(self,"difficulty_force",1.0)

        self.pos.x = clamp(self.pos.x, self.radius, W - self.radius)
        self.pos.y = clamp(self.pos.y, self.radius, H - self.radius)
        if hank_trapped and getattr(game, "domain_active", False):
            rel = self.pos - game.domain_center
            dist_dom = rel.length()
            limit = max(0, game.domain_radius - self.radius - S(4))
            if dist_dom > limit and dist_dom > 0:
                self.pos = game.domain_center + rel.normalize() * limit

    def draw(self, offset):
        p = self.pos + offset
        color = WHITE if self.flash > 0 else self.color
        if getattr(self,"lira_fully_censored",False):
            img=censured_form_surface(max(S(72),self.radius*2 + S(28)))
            if img is not None:
                SCREEN.blit(img,img.get_rect(center=(int(p.x),int(p.y))))
            else:
                r=pygame.Rect(int(p.x-self.radius),int(p.y-self.radius*0.55),self.radius*2,max(S(18),int(self.radius*1.1)))
                pygame.draw.rect(SCREEN,DARK,r,border_radius=max(1,S(4)))
                pygame.draw.rect(SCREEN,WHITE,r,max(1,S(2)),border_radius=max(1,S(4)))
                draw_text("C#NSUR#",FONT_S,WHITE,r.center,True)
        else:
            pygame.draw.circle(SCREEN,color,(int(p.x),int(p.y)),self.radius)
            pygame.draw.circle(SCREEN,DARK,(int(p.x),int(p.y)),max(2,self.radius//3),S(3))
        # barra hp
        bw = self.radius * 2
        x = p.x - bw / 2
        y = p.y - self.radius - S(15)
        pygame.draw.rect(SCREEN, DARK, (x, y, bw, S(7)))
        pygame.draw.rect(SCREEN, GREEN, (x, y, bw * clamp(self.hp / self.max_hp, 0, 1), S(7)))
        if self.elite:
            pygame.draw.circle(SCREEN, WHITE, (int(p.x), int(p.y)), self.radius + S(5), S(3))
        if self.marked:
            draw_text("EXEC!", FONT_S, YELLOW, (p.x, p.y - self.radius - S(45)), True)
        if self.blood_marked:
            pygame.draw.circle(SCREEN, RED, (int(p.x), int(p.y)), self.radius + S(10), S(4))
        if getattr(self,"lira_fully_censored",False):
            draw_text(f"MUDO {self.lira_fully_censored_timer:.1f}s", FONT_S, LIRA_ACCENT, (p.x, p.y + self.radius + S(18)), True)
            draw_text("PRESA", FONT_S, RED, (p.x, p.y + self.radius + S(44)), True)


class GlonkMinion(Enemy):
    """Pequeno Glonk invocado por GLONK, O ULTIMO. Simples, rapido e irritante."""
    def __init__(self, pos, wave, parent=None):
        super().__init__(pos, "chaser", max(1, wave), None)
        self.kind = "glonk_minion"
        self.parent = parent
        self.color = GREEN
        self.radius = S(18)
        self.max_hp = max(12.0, self.max_hp * 0.28)
        self.hp = self.max_hp
        self.speed = max(S(145), min(S(230), self.speed * 1.12))
        self.contact_damage = max(4.0, self.contact_damage * 0.45)
        self.coin_value = 0
        self.elite = None

    def draw(self, offset):
        p = self.pos + offset
        pygame.draw.circle(SCREEN, GREEN, (int(p.x), int(p.y)), self.radius)
        pygame.draw.circle(SCREEN, DARK, (int(p.x), int(p.y)), self.radius, max(1, S(2)))
        pygame.draw.circle(SCREEN, WHITE, (int(p.x-S(5)), int(p.y-S(4))), max(1,S(2)))
        pygame.draw.circle(SCREEN, WHITE, (int(p.x+S(6)), int(p.y-S(2))), max(1,S(2)))
        draw_text("glonk", FONT_S, GREEN, (p.x, p.y-self.radius-S(22)), True)


class GlonkEnemy(Enemy):
    """Inimigo raro: foge durante a wave e vira GLONK, O ULTIMO se for deixado por ultimo."""
    def __init__(self, pos, wave, target_hp=None, target_speed=None, training=False):
        super().__init__(pos, "chaser", wave, None)
        self.kind = "glonk_fugitive"
        self.color = GREEN
        self.radius = S(34)
        if target_hp is not None:
            self.max_hp = max(4.0, float(target_hp))
            self.hp = self.max_hp
        if target_speed is not None:
            self.speed = max(S(175), float(target_speed))
        else:
            self.speed = max(S(185), self.speed * 1.55)
        self.contact_damage = 0.0
        self.coin_value = 16
        self.phase = "flee"  # flee -> transform -> boss
        self.transform_timer = 0.0
        self.is_glonk_boss = False
        self.flee_rethink = 0.0
        self.flee_target = pygame.Vector2(self.pos)
        self.boss_lunge_cd = 0.0
        self.boss_touch_cd = 0.0
        self.aura_phase = random.random() * math.tau
        self.training = training
        self.is_decoy = False
        self.hunt_level = 1
        self.hunt_dash_cd = random.uniform(1.7,2.8)
        self.hunt_swap_cd = random.uniform(3.2,5.0)
        # Kit exclusivo de GLONK, O ULTIMO.
        self.boss_tongue_cd = random.uniform(1.5, 2.4)
        self.boss_summon_cd = random.uniform(4.8, 6.4)
        self.boss_cry_cd = 3.8
        self.boss_miss_timer = 0.0
        self.boss_cry_count = 0
        self.boss_tantrum_cd = 0.0
        self.tantrum_fx = 0.0
        self.tongue_fx = 0.0
        self.tongue_dir = pygame.Vector2(1,0)
        self.cry_fx = 0.0
        self.death_sequence = False
        self.death_timer = 0.0
        self.death_radius = S(520)

    def damage(self, amount, game, source_pos=None, minimal_fx=False):
        # As cutscenes de transformacao e morte sao invulneraveis.
        if self.phase == "transform" or self.death_sequence:
            if not minimal_fx:
                game.damage_texts.append(DamageText("...", pygame.Vector2(self.pos), GREEN, 0.35))
            return
        super().damage(amount, game, source_pos, minimal_fx)

    def _other_enemies(self, game):
        return [e for e in game.enemies if e is not self and not getattr(e, "dead", False)]

    @staticmethod
    def _point_segment_distance(point, a, b):
        ab = b - a
        den = ab.length_squared()
        if den <= 0.001:
            return point.distance_to(a)
        t = clamp((point-a).dot(ab)/den, 0.0, 1.0)
        return point.distance_to(a + ab*t)

    def _safe_boss_action(self, label, fn, game):
        """Um erro isolado num ataque do Glonk nao deve fechar o APK inteiro."""
        try:
            fn(game)
            return True
        except Exception as exc:
            # Evita spam de efeitos/recursao e deixa a luta continuar.
            self.boss_tongue_cd=max(self.boss_tongue_cd,1.2)
            self.boss_summon_cd=max(self.boss_summon_cd,2.0)
            self.boss_cry_cd=max(self.boss_cry_cd,1.5)
            try:
                game.damage_texts.append(DamageText("GLONK TROPECOU",pygame.Vector2(self.pos),GREEN,0.45))
            except Exception:
                pass
            return False

    def choose_flee_target(self, game):
        """Escolhe uma area que combine distancia, espaco livre, cobertura e rota de fuga."""
        p = game.player.pos
        min_x, max_x = self.radius + S(12), W - self.radius - S(12)
        min_y, max_y = S(175) + self.radius, H - S(345) - self.radius
        arena_diag = max(1.0, math.hypot(max_x-min_x, max_y-min_y))
        others = self._other_enemies(game)
        best_score = -10**9
        best = pygame.Vector2(self.pos)
        step = S(260)
        away = self.pos - p
        away_angle = math.atan2(away.y, away.x) if away.length_squared() else 0.0
        angles = [away_angle + off for off in (0, -0.35, 0.35, -0.75, 0.75, -1.25, 1.25, math.pi)]
        angles += [i*math.tau/12 for i in range(12)]
        for ang in angles:
            raw = self.pos + vec_from_angle(ang) * step
            cand = pygame.Vector2(clamp(raw.x,min_x,max_x), clamp(raw.y,min_y,max_y))
            dist_score = cand.distance_to(p) / arena_diag
            wall_clear = min(cand.x-min_x, max_x-cand.x, cand.y-min_y, max_y-cand.y)
            wall_score = clamp(wall_clear/max(S(120),min(W,H)*0.20),0,1)
            cover = 0
            for e in others:
                ep = pygame.Vector2(e.pos)
                if ep.distance_to(p) < cand.distance_to(p) and self._point_segment_distance(ep,p,cand) <= S(105):
                    cover += 1
            cover_score = min(1.0, cover/5.0)
            exits = 0
            for j in range(8):
                q = cand + vec_from_angle(j*math.tau/8)*S(100)
                if min_x < q.x < max_x and min_y < q.y < max_y:
                    exits += 1
            route_score = exits/8.0
            danger_penalty = max(0.0, 1.0 - cand.distance_to(p)/max(S(350),1))
            score = dist_score*3.2 + wall_score*0.85 + cover_score*1.05 + route_score*0.70 - danger_penalty*2.0
            if score > best_score:
                best_score, best = score, cand
        self.flee_target = best

    def begin_transform(self, game):
        if self.phase != "flee" or self.dead:
            return
        if getattr(game,"mode","")=="arena" and not getattr(self,"is_decoy",False):
            SAVE["profile_glonks_escaped"]=int(SAVE.get("profile_glonks_escaped",0) or 0)+1
            save_data(SAVE)
        self.phase = "transform"
        self.transform_timer = 2.35
        self.speed = 0.0
        self.contact_damage = 0.0
        self.vel = pygame.Vector2() if hasattr(self,"vel") else None
        game.glonk_music_cut_timer = max(game.glonk_music_cut_timer, 2.35)
        game.glonk_event_timer = 2.35
        game.glonk_event_stage = "trapped"
        game.shake = max(game.shake, S(7))
        AUDIO.play("glonk", 1.0, 100)

    def finish_transform(self, game):
        self.phase = "boss"
        self.is_glonk_boss = True
        self.radius = S(62)
        old_max = self.max_hp
        self.max_hp *= 1.35
        self.hp = min(self.max_hp, max(self.hp + (self.max_hp-old_max), self.max_hp*0.55))
        player_speed = max(S(230), min(S(390), getattr(game.player,"base_speed",S(290))*1.05))
        self.speed = player_speed
        self.contact_damage = max(18.0, game.player.max_hp*0.18)
        self.coin_value = 90
        self.boss_touch_cd = 0.0
        self.boss_lunge_cd = 1.0
        self.boss_tongue_cd = 1.6
        self.boss_summon_cd = 4.0
        self.boss_cry_cd = 3.0
        self.boss_miss_timer = 0.0
        game.glonk_event_stage = "boss"
        game.glonk_event_timer = 2.4
        game.glonk_boss_intro_timer = 2.4
        game.glonk_music_cut_timer = 0.0
        game.shake = max(game.shake, S(18))
        if getattr(game,"game_mode","normal")=="glonk_hunt":
            game.hunt_glonk_transform_count += 1
            n=game.hunt_glonk_transform_count
            self.max_hp*=1.0+0.18*max(0,n-1); self.hp=self.max_hp
            self.speed*=min(1.50,1.0+0.07*max(0,n-1)); self.contact_damage*=1.0+0.10*max(0,n-1)
        if not SAVE.get("glonk_last_discovered", False):
            SAVE["glonk_last_discovered"] = True
            save_data(SAVE)
        AUDIO.play("boss", 1.0, 100)

    def _boss_tongue_attack(self, game):
        """Lingua do Glonk: mesmo estilo do ataque do Glonk 100%, mas como chicote longo."""
        delta = game.player.pos - self.pos
        if delta.length_squared() <= 0.001:
            delta = pygame.Vector2(1,0)
        d = delta.normalize()
        self.tongue_dir = pygame.Vector2(d)
        self.tongue_fx = 0.24
        reach = S(355)
        width = S(28)
        end = self.pos + d * reach
        if self._point_segment_distance(game.player.pos, self.pos, end) <= width + game.player.radius:
            hit = game.player.take_damage(max(10.0, game.player.max_hp*0.12), game)
            if hit is not False:
                self.boss_miss_timer = 0.0
                self.boss_cry_count = 0
            game.damage_texts.append(DamageText("LAMBIDA!", pygame.Vector2(game.player.pos), GREEN, 0.65))
        else:
            self.boss_miss_timer += 0.8
        game.shake = max(game.shake, S(5))
        AUDIO.play("hit", 0.35, 80)

    def _boss_cry(self, game):
        """Se o Glonk passa tempo demais sem acertar, ele literalmente chora projeteis gigantes."""
        self.cry_fx = 0.85
        self.boss_cry_count += 1
        game.damage_texts.append(DamageText("BUAAAAAAAA!", pygame.Vector2(self.pos), CYAN, 1.0))
        aim = game.player.pos - self.pos
        base = math.atan2(aim.y, aim.x) if aim.length_squared() else 0.0
        for off in (-0.42, -0.21, 0.0, 0.21, 0.42):
            d = vec_from_angle(base + off)
            pr = Projectile(self.pos + d*(self.radius+S(10)), d*S(245), max(7.0, game.player.max_hp*0.075), "enemy", S(19), CYAN, 4.0, 0)
            pr.kind = "glonk_tear"
            game.projectiles.append(pr)
        for side in (-1,1):
            d = vec_from_angle(base + side*1.05)
            pr = Projectile(self.pos, d*S(185), max(5.0, game.player.max_hp*0.05), "enemy", S(16), BLUE, 3.5, 0)
            pr.kind = "glonk_tear"
            game.projectiles.append(pr)
        game.spawn_particles(self.pos, CYAN, 8)
        game.shake = max(game.shake, S(7))

    def _boss_tantrum(self, game):
        """BIRRA: depois de chorar demais, Glonk perde a paciencia e da um dash desesperado."""
        delta = game.player.pos - self.pos
        if delta.length_squared() <= 0.001:
            return
        d = delta.normalize()
        start = pygame.Vector2(self.pos)
        dash_len = min(S(300), max(S(150), delta.length()*0.72))
        self.pos += d * dash_len
        self.pos.x = clamp(self.pos.x, self.radius, W-self.radius)
        self.pos.y = clamp(self.pos.y, self.radius, H-self.radius)
        self.tantrum_fx = 0.35
        game.damage_texts.append(DamageText("BIRRA!", pygame.Vector2(self.pos), RED, 0.9))
        game.spawn_particles(start, GREEN, 10); game.spawn_particles(self.pos, GREEN, 14)
        if self._point_segment_distance(game.player.pos, start, self.pos) <= self.radius + game.player.radius + S(18):
            hit = game.player.take_damage(max(12.0, game.player.max_hp*0.16), game)
            if hit is not False:
                self.boss_miss_timer = 0.0
        game.shake = max(game.shake, S(12))

    def _boss_summon_glonks(self, game):
        alive = [e for e in game.enemies if isinstance(e, GlonkMinion) and not e.dead]
        slots = max(0, 5-len(alive))
        count = min(slots, random.choice([1,2,2,3]))
        if count <= 0:
            return
        for i in range(count):
            a = i*math.tau/max(1,count) + random.uniform(-0.35,0.35)
            pos = self.pos + vec_from_angle(a)*S(85)
            pos.x = clamp(pos.x, S(30), W-S(30)); pos.y = clamp(pos.y, S(190), H-S(360))
            game.enemies.append(GlonkMinion(pos, self.wave, self))
        game.damage_texts.append(DamageText("MAIS GLONKS!", pygame.Vector2(self.pos), GREEN, 0.8))
        game.spawn_particles(self.pos, GREEN, 12)

    def die(self, game):
        # GLONK, O ULTIMO nao simplesmente cai: ele avisa por 2s e explode.
        if self.phase == "boss" and not self.death_sequence:
            self.death_sequence = True
            self.death_timer = 2.0
            self.hp = 1.0
            self.speed = 0.0
            self.contact_damage = 0.0
            self.boss_tongue_cd = 999.0
            self.boss_summon_cd = 999.0
            game.damage_texts.append(DamageText("...GLONK?", pygame.Vector2(self.pos), GREEN, 1.2))
            game.shake = max(game.shake, S(8))
            return
        if self.death_sequence:
            return
        super().die(game)

    def _finish_death_explosion(self, game):
        radius = self.death_radius
        game.shake = max(game.shake, S(32))
        game.spawn_particles(self.pos, GREEN, 24)
        game.spawn_particles(self.pos, WHITE, 10)
        # A explosao e evitavel saindo da area; dentro dela tira 50% do HP MAXIMO.
        if self.pos.distance_to(game.player.pos) <= radius + game.player.radius:
            if SAVE.get("cheat_immortal", False):
                game.damage_texts.append(DamageText("IMORTAL", pygame.Vector2(game.player.pos), YELLOW, 0.65))
            elif game.player.invuln > 0 or game.player.dash_time > 0:
                game.damage_texts.append(DamageText("ESCAPOU!", pygame.Vector2(game.player.pos), WHITE, 0.75))
            else:
                dmg = game.player.max_hp * 0.50
                game.player.hp -= dmg
                if getattr(game,"game_mode","normal") == "extinction":
                    cap = getattr(game,"extinction_hp_cap",None)
                    game.extinction_hp_cap = game.player.hp if cap is None else min(cap, game.player.hp)
                game.damage_texts.append(DamageText("-50% HP", pygame.Vector2(game.player.pos), RED, 1.0))
                AUDIO.play("hurt", 1.0, 100)
        # Pequenos Glonks somem junto para a wave nao ficar presa.
        for e in game.enemies:
            if isinstance(e, GlonkMinion) and not e.dead:
                e.dead = True
                game.spawn_particles(e.pos, GREEN, 6)
        self.hp = 0.0
        self.death_sequence = False
        super().die(game)

    def update(self, dt, game):
        if self.dead:
            return
        self.flash = max(0, self.flash-dt)
        self.aura_phase += dt*5.0
        self.tongue_fx = max(0.0, self.tongue_fx-dt)
        self.cry_fx = max(0.0, self.cry_fx-dt)
        self.tantrum_fx = max(0.0, self.tantrum_fx-dt)
        if self.death_sequence:
            self.death_timer -= dt
            game.shake = max(game.shake, S(4) + int(S(9)*(1.0-clamp(self.death_timer/2.0,0,1))))
            if random.random() < min(0.45, dt*12):
                game.spawn_particles(self.pos + pygame.Vector2(random.uniform(-self.radius,self.radius),random.uniform(-self.radius,self.radius)), GREEN, 2)
            if self.death_timer <= 0:
                try:
                    self._finish_death_explosion(game)
                except Exception:
                    # Se o FX final falhar, encerra o boss sem derrubar o jogo.
                    self.hp=0.0; self.death_sequence=False; super().die(game)
            return
        if self.phase == "flee":
            if not self._other_enemies(game):
                self.begin_transform(game)
                return
            if getattr(game,"game_mode","normal")=="glonk_hunt":
                self.hunt_dash_cd-=dt; self.hunt_swap_cd-=dt
                if self.hunt_level>=3 and self.hunt_dash_cd<=0:
                    away=self.pos-game.player.pos
                    if away.length_squared()>0: self.pos += away.normalize()*S(105)
                    self.hunt_dash_cd=max(0.85,2.6-0.12*self.hunt_level)
                    game.spawn_particles(self.pos,GREEN,6)
                if self.hunt_level>=7 and self.hunt_swap_cd<=0:
                    opts=[e for e in self._other_enemies(game) if not isinstance(e,GlonkEnemy)]
                    if opts:
                        other=random.choice(opts); old=pygame.Vector2(self.pos); self.pos=pygame.Vector2(other.pos); other.pos=old
                        game.damage_texts.append(DamageText("TROCOU!",pygame.Vector2(self.pos),GREEN,0.55))
                    self.hunt_swap_cd=max(1.8,5.0-0.20*self.hunt_level)
            self.flee_rethink -= dt
            if self.flee_rethink <= 0:
                self.choose_flee_target(game)
                self.flee_rethink = 0.16
            delta = self.flee_target - self.pos
            if delta.length_squared() > S(12)**2:
                d = delta.normalize()
                self.pos += d * self.speed * dt
            self.pos.x = clamp(self.pos.x, self.radius, W-self.radius)
            self.pos.y = clamp(self.pos.y, self.radius, H-self.radius)
            return
        if self.phase == "transform":
            self.transform_timer -= dt
            game.shake = max(game.shake, S(4) + int(S(5)*(1.0-clamp(self.transform_timer/2.35,0,1))))
            if self.transform_timer <= 1.15 and game.glonk_event_stage == "trapped":
                game.glonk_event_stage = "stopped"
                game.glonk_event_timer = max(game.glonk_event_timer, 1.15)
            if self.transform_timer <= 0:
                self.finish_transform(game)
            return

        # GLONK, O ULTIMO: persegue, usa lingua, invoca mini-Glonks e chora se falhar demais.
        self.boss_touch_cd = max(0.0, self.boss_touch_cd-dt)
        self.boss_lunge_cd -= dt
        self.boss_tongue_cd -= dt
        self.boss_summon_cd -= dt
        self.boss_cry_cd -= dt
        self.boss_tantrum_cd = max(0.0, self.boss_tantrum_cd-dt)
        self.boss_miss_timer += dt
        delta = game.player.pos - self.pos
        dist = max(1.0, delta.length())
        d = delta/dist
        move_mult = 1.15
        if self.boss_lunge_cd <= 0:
            move_mult = 2.15 + min(0.75, self.boss_miss_timer*0.06)
            self.boss_lunge_cd = random.uniform(1.05,1.55)
        self.pos += d * self.speed * move_mult * dt
        game.shake = max(game.shake, S(2))

        if self.boss_tongue_cd <= 0 and dist <= S(430):
            self._safe_boss_action("tongue", self._boss_tongue_attack, game)
            self.boss_tongue_cd = random.uniform(2.25,3.15)
        if self.boss_summon_cd <= 0:
            self._safe_boss_action("summon", self._boss_summon_glonks, game)
            self.boss_summon_cd = random.uniform(5.3,7.0)
        if self.boss_miss_timer >= 4.6 and self.boss_cry_cd <= 0:
            self._safe_boss_action("cry", self._boss_cry, game)
            self.boss_cry_cd = random.uniform(3.4,4.4)
            self.boss_miss_timer = 1.2
            if self.boss_cry_count >= 2 and self.boss_tantrum_cd <= 0:
                self._safe_boss_action("tantrum", self._boss_tantrum, game)
                self.boss_tantrum_cd = 8.0
                self.boss_cry_count = 0

        if dist <= self.radius + game.player.radius + S(5) and self.boss_touch_cd <= 0:
            hit = game.player.take_damage(max(self.contact_damage, game.player.max_hp*0.18), game)
            game.player.stamina = max(0.0, game.player.stamina - game.player.max_stamina*0.08)
            game.player.stamina_regen_delay = max(game.player.stamina_regen_delay,0.75)
            game.damage_texts.append(DamageText("AGORA CORRA VOCE.", pygame.Vector2(game.player.pos), GREEN, 0.75))
            if hit is not False:
                self.boss_miss_timer = 0.0
                self.boss_cry_count = 0
            self.boss_touch_cd = 0.48
        self.pos.x = clamp(self.pos.x, self.radius, W-self.radius)
        self.pos.y = clamp(self.pos.y, self.radius, H-self.radius)

    def draw(self, offset):
        p = self.pos + offset
        color = WHITE if self.flash > 0 else GREEN
        if self.phase == "boss" or self.death_sequence:
            aura = self.radius + S(13) + int(S(5)*(0.5+0.5*math.sin(self.aura_phase)))
            if self.death_sequence:
                ratio = 1.0-clamp(self.death_timer/2.0,0,1)
                aura += int(S(90)*ratio)
            pygame.draw.circle(SCREEN, (45,255,95), (int(p.x),int(p.y)), aura, max(2,S(5)))
            pygame.draw.circle(SCREEN, (20,120,50), (int(p.x),int(p.y)), aura+S(10), max(1,S(3)))
        pygame.draw.circle(SCREEN, color, (int(p.x),int(p.y)), self.radius)
        pygame.draw.circle(SCREEN, DARK, (int(p.x),int(p.y)), self.radius, max(2,S(3)))
        eye_col = WHITE if (self.phase != "boss" and not self.death_sequence) else YELLOW
        eye_y = int(p.y-S(8))
        pygame.draw.circle(SCREEN, eye_col, (int(p.x-S(10)), eye_y), max(2,S(4)))
        pygame.draw.circle(SCREEN, eye_col, (int(p.x+S(10)), eye_y), max(2,S(4)))
        name = "GLONK, O ULTIMO" if (self.phase == "boss" or self.death_sequence) else "GLONK"
        draw_text(name, FONT_M if (self.phase=="boss" or self.death_sequence) else FONT_S, GREEN, (p.x,p.y-self.radius-S(58)), True)
        if self.tongue_fx > 0:
            d = self.tongue_dir if self.tongue_dir.length_squared() else pygame.Vector2(1,0)
            end = p + d.normalize()*S(355)
            pygame.draw.line(SCREEN, GREEN, p, end, max(S(14),S(21)))
            pygame.draw.circle(SCREEN, WHITE, (int(end.x),int(end.y)), S(14), max(1,S(3)))
        if self.tantrum_fx > 0:
            pygame.draw.circle(SCREEN, RED, (int(p.x),int(p.y)), self.radius+S(24), max(2,S(5)))
        if self.cry_fx > 0:
            for sx in (-1,1):
                start = pygame.Vector2(p.x+sx*S(12), p.y+S(2))
                end = start + pygame.Vector2(sx*S(5), S(34))
                pygame.draw.line(SCREEN, CYAN, start, end, max(S(6),S(9)))
                pygame.draw.circle(SCREEN, CYAN, (int(end.x),int(end.y)), S(8))
        if self.death_sequence:
            ratio = 1.0-clamp(self.death_timer/2.0,0,1)
            warn_r = int(self.death_radius * (0.45 + 0.55*ratio))
            pygame.draw.circle(SCREEN, GREEN, (int(p.x),int(p.y)), warn_r, max(2,S(7)))
            draw_text("SAIA DA AREA!", FONT_M, RED, (p.x,p.y+self.radius+S(64)), True)
        bw=self.radius*2.2; x=p.x-bw/2; y=p.y-self.radius-S(22)
        pygame.draw.rect(SCREEN,DARK,(x,y,bw,S(8)))
        pygame.draw.rect(SCREEN,GREEN,(x,y,bw*clamp(self.hp/max(1,self.max_hp),0,1),S(8)))


class TrainingDummy(Enemy):
    """Bekita da Zona AFK: alvo imortal, parado e completamente bobinho."""
    def __init__(self, pos, wave=1):
        super().__init__(pos, "tank", wave, None)
        self.max_hp = 260
        self.hp = self.max_hp
        self.radius = S(42)
        self.speed = 0
        self.contact_damage = 0
        self.color = PINK
        self.coin_value = 0
        self.goofy_phase = random.random()*math.tau

    def update(self, dt, game):
        self.flash = max(0, self.flash - dt)
        self.marked = self.hp <= self.max_hp * 0.18 and self.hp > 0
        self.goofy_phase += dt*2.2

    def die(self, game):
        self.dead = False
        self.hp = self.max_hp
        self.marked = False
        self.blood_marked = False
        game.combo = min(50, game.combo + 1)
        game.combo_timer = 3.0
        game.on_enemy_killed(self)
        game.spawn_particles(self.pos, PINK, 12)
        game.damage_texts.append(DamageText("BEKITA: hehe", pygame.Vector2(self.pos), PINK))

    def draw(self, offset):
        p=self.pos+offset
        wob=int(math.sin(self.goofy_phase)*S(3))
        body=(int(p.x),int(p.y+wob))
        pygame.draw.circle(SCREEN,PINK,body,self.radius)
        pygame.draw.circle(SCREEN,WHITE,body,self.radius,max(2,S(3)))
        # Cara deliberadamente boba: olhos tortos e sorriso simples.
        eye_y=body[1]-S(8)
        pygame.draw.circle(SCREEN,WHITE,(body[0]-S(14),eye_y),S(7))
        pygame.draw.circle(SCREEN,WHITE,(body[0]+S(16),eye_y+S(3)),S(7))
        pygame.draw.circle(SCREEN,DARK,(body[0]-S(12),eye_y+S(2)),S(3))
        pygame.draw.circle(SCREEN,DARK,(body[0]+S(18),eye_y+S(1)),S(3))
        pygame.draw.arc(SCREEN,DARK,(body[0]-S(18),body[1]-S(1),S(36),S(28)),0.12*math.pi,0.88*math.pi,max(2,S(3)))
        draw_text("BEKITA", FONT_S, PINK, (p.x, p.y + self.radius + S(24)), True)
        draw_text("hehe", FONT_S, WHITE, (p.x, p.y + self.radius + S(50)), True)


class Boss(Enemy):
    def __init__(self, pos, wave):
        super().__init__(pos, "tank", wave, None)
        self.radius = S(72)
        combat_wave = effective_combat_wave(wave)
        hp_scale, damage_scale, speed_scale = high_wave_scaling(wave)
        self.boss_damage_scale = damage_scale
        self.max_hp = (700 + combat_wave * 95) * hp_scale
        self.hp = self.max_hp
        # Bosses mantem pressao por IA/dano/ataques, nao por velocidade absurda.
        self.speed = S(88) * enemy_wave_speed_mult(wave)
        self.coin_value = 55
        self.wave = combat_wave
        self.display_wave = wave
        cfg = BOSS_VARIANTS[((wave // 5) - 1) % len(BOSS_VARIANTS)]
        self.variant = cfg["key"]
        self.name = cfg["name"]
        self.color = cfg["color"]
        self.domain_name = cfg["domain"]
        self.domain_desc = cfg["domain_desc"]
        self.burst_cd = 1.0
        self.charge_cd = 3.0
        self.charging = 0
        self.charge_dir = pygame.Vector2()
        self.domain_cd = 4.8
        self.domain_active = False
        self.domain_timer = 0.0
        self.domain_radius = S(480)
        self.domain_center = pygame.Vector2(self.pos)
        self.domain_tick = 0.0
        self.clash_buff_timer = 0.0

    def is_in_domain(self, pos):
        return self.domain_active and pygame.Vector2(pos).distance_to(self.domain_center) <= self.domain_radius

    def activate_domain(self, game):
        if self.dead or self.domain_active:
            return
        if getattr(getattr(game,"player",None),"character",None)==KIRA_KEY and getattr(game.player,"kira_bites_armed",False):
            game.player.kira_trigger_bites(game,manual=False,reason="EXPANSAO INIMIGA")
            return
        self.domain_active = True
        self.domain_center = pygame.Vector2(self.pos)
        self.domain_timer = 6.5
        self.domain_tick = 0.15
        self.domain_cd = 11.0
        AUDIO.play("domain", 0.85, 300)
        game.boss_domain_message = f"{self.name}: {self.domain_name}"
        game.boss_domain_message_timer = 2.0
        game.shake = max(game.shake, S(10))
        if game.domain_active and game.domains_overlap(self):
            game.start_domain_clash(self)

    def die(self, game):
        if self.dead:
            return
        was_father = self.variant == "father" and game.mode == "arena"
        was_sentinel = self.variant == "sentinel" and game.mode == "arena"
        killer_character = game.player.character
        super().die(game)
        if (not was_father and not was_sentinel) or is_beta_character(killer_character):
            return

        changed = False
        if not SAVE.get("kayk_unlocked", False):
            SAVE["kayk_unlocked"] = True
            changed = True
            AUDIO.play("unlock", 1.0)
            game.unlock_notice = "KAYK DESBLOQUEADO!"
            game.unlock_notice_timer = 5.0

        victories = set(SAVE.get("father_victories", []))
        if killer_character in FATHER_UNLOCK_CHARACTERS and killer_character not in victories:
            victories.add(killer_character)
            SAVE["father_victories"] = sorted(victories)
            changed = True
            game.unlock_notice = f"PAI DO KAYK: {len(victories)}/{len(FATHER_UNLOCK_CHARACTERS)} PERSONAGENS"
            game.unlock_notice_timer = 5.0

        if all(name in victories for name in FATHER_UNLOCK_CHARACTERS) and not SAVE.get("father_unlocked", False):
            SAVE["father_unlocked"] = True
            changed = True
            AUDIO.play("unlock", 1.0)
            game.unlock_notice = "PAI DO KAYK DESBLOQUEADO!"
            game.unlock_notice_timer = 6.0
            game.unlock_achievement("father_unlock")

        if was_sentinel:
            s_victories = set(SAVE.get("sentinel_victories", []))
            if killer_character in FATHER_UNLOCK_CHARACTERS and killer_character not in s_victories:
                s_victories.add(killer_character)
                SAVE["sentinel_victories"] = sorted(s_victories)
                changed = True
                game.unlock_notice = f"HANK: {len(s_victories)}/{len(FATHER_UNLOCK_CHARACTERS)} PERSONAGENS"
                game.unlock_notice_timer = 5.0
            if all(name in s_victories for name in FATHER_UNLOCK_CHARACTERS) and not SAVE.get("hank_unlocked", False):
                SAVE["hank_unlocked"] = True
                changed = True
                AUDIO.play("unlock", 1.0)
                game.unlock_notice = "HANK J. WIMBLETON DESBLOQUEADO!"
                game.unlock_notice_timer = 6.0

        if changed:
            save_data(SAVE)

    def update(self, dt, game):
        if self.dead:
            return
        if self.lira_stat_level("intelligence",game)>=0.999:
            self.flash=max(0,self.flash-dt); self.burst_cd-=dt; self.touch_cd-=dt
            flee=self.pos-game.player.pos
            if flee.length_squared()<=0: flee=vec_from_angle(random.random()*math.tau)
            move_mult=max(0.20,1.0-self.lira_stat_level("speed",game))
            self.pos += flee.normalize()*self.speed*0.72*move_mult*dt
            if self.burst_cd<=0:
                power=self.lira_outgoing_mult(game)
                for _ in range(3):
                    d=vec_from_angle(random.random()*math.tau)
                    game.projectiles.append(Projectile(self.pos,d*S(300),(7+self.wave*0.35)*self.boss_damage_scale*power*difficulty_cfg(getattr(game,"difficulty","easy"))["damage"],"enemy",S(9),self.color,2.4))
                self.burst_cd=0.75
            self.pos.x=clamp(self.pos.x,self.radius,W-self.radius); self.pos.y=clamp(self.pos.y,self.radius,H-self.radius)
            return
        self.flash = max(0, self.flash - dt)
        self.forge_slow_timer = max(0.0, getattr(self, "forge_slow_timer", 0.0)-dt)
        boss_move_speed = self.speed * (0.55 if self.forge_slow_timer > 0 else 1.0) * max(0.20,1.0-self.lira_stat_level("speed",game))
        self.burst_cd -= dt
        self.charge_cd -= dt
        self.touch_cd -= dt
        self.clash_buff_timer = max(0.0, self.clash_buff_timer-dt)

        if self.domain_active:
            self.domain_timer -= dt
            self.domain_tick -= dt
            if self.domain_timer <= 0:
                self.domain_active = False
                self.domain_timer = 0.0
            else:
                inside = self.is_in_domain(game.player.pos)
                if self.variant == "father" and inside and self.domain_tick <= 0:
                    # Glonk/Glonk 100% sao imunes a dano inevitavel de Expansao.
                    if game.player.character not in ("Glonk", "Glonk 100% Power"):
                        game.player.take_damage((6 + self.wave*0.22) * self.boss_damage_scale * self.lira_outgoing_mult(game) * difficulty_cfg(getattr(game,"difficulty","easy"))["damage"], game)
                        game.damage_texts.append(DamageText("DISCIPLINA!", pygame.Vector2(game.player.pos), RED))
                    self.domain_tick = 0.95
                elif self.variant == "devourer" and inside:
                    drain = (16 + self.wave*0.12) * dt
                    if game.player.stamina > 0:
                        game.player.stamina = max(0, game.player.stamina-drain)
                    elif self.domain_tick <= 0:
                        if game.player.character not in ("Glonk", "Glonk 100% Power"):
                            game.player.take_damage((5 + self.wave*0.15) * self.boss_damage_scale * self.lira_outgoing_mult(game) * difficulty_cfg(getattr(game,"difficulty","easy"))["damage"], game)
                        self.domain_tick = 0.8
                elif self.variant == "sentinel" and inside and self.domain_tick <= 0:
                    for i in range(4):
                        d = vec_from_angle(i*math.pi/2)
                        game.projectiles.append(Projectile(self.domain_center, d*S(355), (6+self.wave*0.35) * self.boss_damage_scale * self.lira_outgoing_mult(game) * difficulty_cfg(getattr(game,"difficulty","easy"))["damage"], "enemy", S(9), CYAN, 2.5))
                    self.domain_tick = 0.72
                elif self.variant == "void" and inside and self.domain_tick <= 0:
                    game.domain_charge = max(0, game.domain_charge-4)
                    game.damage_texts.append(DamageText("SILENCIO", pygame.Vector2(game.player.pos), GRAY))
                    self.domain_tick = 0.9
        else:
            self.domain_cd -= dt
            if self.domain_cd <= 0:
                self.activate_domain(game)

        target_entity = game.get_enemy_target(self.pos)
        to_player = target_entity.pos - self.pos
        dist = max(1, to_player.length())
        d = to_player / dist
        phase2 = self.hp <= self.max_hp * 0.5
        buff = 1.35 if self.clash_buff_timer > 0 else 1.0

        if self.charging > 0:
            self.charging -= dt
            self.pos += self.charge_dir * boss_move_speed * (4.3 if phase2 else 3.4) * buff * dt
        else:
            self.pos += d * boss_move_speed * (1.25 if phase2 else 0.85) * buff * dt
            if self.charge_cd <= 0:
                self.charging = 0.55
                self.charge_dir = pygame.Vector2(d)
                ai_mult = difficulty_cfg(getattr(game,"difficulty","easy"))["ai"] if game.mode=="arena" else 1.0
                self.charge_cd = (2.4 if phase2 else 3.7) / ai_mult

        if self.burst_cd <= 0:
            shots = 14 if phase2 else 9
            for i in range(shots):
                a = i * math.tau / shots + game.time * 0.35
                game.projectiles.append(Projectile(self.pos, vec_from_angle(a) * S(285 if phase2 else 235), (8 + self.wave * 0.5)*buff*self.boss_damage_scale*self.lira_outgoing_mult(game)*difficulty_cfg(getattr(game,"difficulty","easy"))["damage"], "enemy", S(11), PINK))
            ai_mult = difficulty_cfg(getattr(game,"difficulty","easy"))["ai"] if game.mode=="arena" else 1.0
            self.burst_cd = (1.15 if phase2 else 1.9) / ai_mult
            game.shake = max(game.shake, S(5))

        if dist < self.radius + target_entity.radius and self.touch_cd <= 0:
            if self.variant == "gula" and target_entity is game.player:
                game.gula_devour(self)
            else:
                target_entity.take_damage((14 + self.wave * 0.8)*buff*self.boss_damage_scale*self.lira_outgoing_mult(game)*difficulty_cfg(getattr(game,"difficulty","easy"))["damage"], game)
                if target_entity is game.player and d.length_squared()>0:
                    game.player.pos += d*S(34)*difficulty_cfg(getattr(game,"difficulty","easy"))["force"]
            self.touch_cd = 0.65

        self.pos.x = clamp(self.pos.x, self.radius, W - self.radius)
        self.pos.y = clamp(self.pos.y, self.radius, H - self.radius)

    def draw(self, offset):
        super().draw(offset)
        p = self.pos + offset
        draw_text(self.name, FONT_S, WHITE, (p.x, p.y + self.radius + S(24)), True)


class SinBoss(Boss):
    """Pecados e Arcebispos com escala propria, separada da compressao geral das waves."""
    def __init__(self, pos, wave, sin_cfg, archbishop=False):
        # Antes, Luxuria na wave 100 herdava combat wave 700 e DEPOIS recebia buffs de Pecado.
        # Agora a ordem do pecado define uma referencia bem mais suave; a wave real fica so para agenda/UI.
        sin_rank = next((i for i,cfg in enumerate(SIN_SEQUENCE) if cfg["key"]==sin_cfg["key"]), 0)
        reference_wave = 10 + sin_rank*2 + (1 if not archbishop else 0)
        super().__init__(pos, reference_wave)
        self.encounter_wave = wave
        self.display_wave = wave
        self.sin_rank = sin_rank
        self.sin_key = sin_cfg["key"]
        self.sin_name = sin_cfg["name"]
        self.fragment_key = sin_cfg["fragment"]
        self.archbishop = archbishop
        self.variant = "gula" if self.sin_key == "gula" and not archbishop else "sin_" + self.sin_key
        self.name = ("ARCEBISPO DA " if archbishop else "PECADO: ") + self.sin_name
        self.color = sin_cfg["color"]
        self.radius = S(70 if archbishop else 92)
        # Arcebispo = demonstracao; Pecado verdadeiro ainda e boss especial,
        # mas sem multiplicar novamente o endgame comprimido.
        mult = 1.22 if archbishop else 1.85
        self.max_hp *= mult
        self.hp = self.max_hp
        self.speed *= 0.92 if archbishop else 1.05
        self.boss_damage_scale *= 0.68 if archbishop else 0.82
        self.coin_value = 350 if archbishop else 1500
        # V14: Pecados/Arcebispos tambem podem abrir Dominio e causar Clash.
        sin_domains = {
            "wrath": "TRONO DA IRA",
            "pride": "CEU DO ORGULHO",
            "envy": "ESPELHO DA INVEJA",
            "greed": "TESOURO SEM FIM",
            "gula": "BANQUETE SEM FIM",
            "sloth": "SONO DO FIM",
            "lust": "ILUSAO ESCARLATE",
        }
        self.domain_name = sin_domains.get(self.sin_key, "DOMINIO DO PECADO")
        self.domain_desc = "Enquanto ativo, as mecanicas exclusivas deste Pecado aceleram e o Clash e permitido."
        self.domain_active = False
        self.domain_cd = random.uniform(7.0, 9.5) if archbishop else random.uniform(5.2, 7.4)
        self.domain_radius = S(500 if archbishop else 560)
        self.sin_tick = 0.8
        self.sin_aux = 2.0
        self.pride_guard = 0.0
        self.teleport_cd = 2.8
        if self.sin_key == "gula" and not archbishop:
            hunger=max(0,int(SAVE.get("gula_hunger",0)))
            self.max_hp *= 1.25*(1.0+0.35*hunger); self.hp=self.max_hp
            self.speed *= 1.0+min(0.45,0.06*hunger)
            self.boss_damage_scale *= 1.0+min(0.80,0.08*hunger)

    def damage(self, amount, game, source_pos=None, minimal_fx=False):
        raw_resistance = self.lira_stat_level("resistance",game)>=0.999
        if self.sin_key == "pride" and self.pride_guard > 0 and not raw_resistance:
            amount *= 0.28 if not self.archbishop else 0.45
        super().damage(amount, game, source_pos, minimal_fx)

    def update(self, dt, game):
        if self.dead: return
        self.sin_tick -= dt; self.sin_aux -= dt
        # Dentro do proprio Dominio o Pecado "forca" suas mecanicas a acontecerem mais cedo.
        if self.domain_active:
            self.sin_tick -= dt * 0.70
            self.sin_aux -= dt * 0.70
        self.pride_guard=max(0.0,self.pride_guard-dt)
        # Pecado da Preguica: aura azul desacelera o jogador.
        if self.sin_key == "sloth" and self.pos.distance_to(game.player.pos) <= S(560):
            game.sin_sloth_slow = True
        super().update(dt, game)
        if self.dead: return
        if self.lira_stat_level("intelligence",game)>=0.999: return
        strength = 0.60 if self.archbishop else 1.0
        diff_ai = difficulty_cfg(getattr(game,"difficulty","easy"))["ai"] if game.mode=="arena" else 1.0
        if self.sin_key == "wrath" and self.sin_tick <= 0:
            shots = 8 if self.archbishop else (12 if self.hp > self.max_hp*0.5 else 18)
            for i in range(shots):
                d=vec_from_angle(i*math.tau/shots + game.time*0.2)
                game.projectiles.append(Projectile(self.pos,d*S(330), (8+self.wave*0.22)*self.boss_damage_scale*self.lira_outgoing_mult(game)*strength*difficulty_cfg(getattr(game,"difficulty","easy"))["damage"],"enemy",S(9),RED,2.5))
            self.sin_tick = (1.8 if self.archbishop else 1.15) / diff_ai
        elif self.sin_key == "pride" and self.sin_aux <= 0:
            self.pride_guard = 0.85 if self.archbishop else 1.45
            game.damage_texts.append(DamageText("EU ESTOU ACIMA",pygame.Vector2(self.pos),YELLOW,0.8))
            self.sin_aux = (4.6 if self.archbishop else 3.6) / diff_ai
        elif self.sin_key == "envy" and self.sin_tick <= 0:
            to=game.player.pos-self.pos
            if to.length_squared()>0:
                a=math.atan2(to.y,to.x)
                for off in (-0.24,0,0.24):
                    game.projectiles.append(Projectile(self.pos,vec_from_angle(a+off)*S(390),(9+self.wave*0.20)*self.boss_damage_scale*self.lira_outgoing_mult(game)*strength*difficulty_cfg(getattr(game,"difficulty","easy"))["damage"],"enemy",S(10),GREEN,3.0))
            self.speed=max(self.speed, game.player.base_speed*(0.72 if self.archbishop else 0.95))
            self.sin_tick=(1.55 if self.archbishop else 1.05) / diff_ai
        elif self.sin_key == "greed" and self.sin_aux <= 0:
            if self.pos.distance_to(game.player.pos) <= S(520):
                stolen=min(game.run_coins, max(5,int(game.run_coins*(0.03 if self.archbishop else 0.08))))
                game.run_coins=max(0,game.run_coins-stolen)
                self.hp=min(self.max_hp,self.hp+stolen*(2.0 if self.archbishop else 4.0))
                game.damage_texts.append(DamageText(f"ROUBOU {stolen}",pygame.Vector2(game.player.pos),ORANGE,0.8))
            self.sin_aux=(3.2 if self.archbishop else 2.1) / diff_ai
        elif self.sin_key == "gula":
            # Contato do Pecado verdadeiro e o devorar classico; o Arcebispo apenas causa dano normal.
            pass
        elif self.sin_key == "sloth" and self.sin_tick <= 0:
            # Campo pesado: projeteis azuis lentos fecham espaco ao redor do jogador.
            for i in range(6 if self.archbishop else 10):
                d=vec_from_angle(i*math.tau/(6 if self.archbishop else 10))
                game.projectiles.append(Projectile(self.pos,d*S(205),(7+self.wave*0.16)*self.boss_damage_scale*self.lira_outgoing_mult(game)*strength*difficulty_cfg(getattr(game,"difficulty","easy"))["damage"],"enemy",S(13),BLUE,4.0))
            self.sin_tick=(2.4 if self.archbishop else 1.7) / diff_ai
        elif self.sin_key == "lust" and self.sin_aux <= 0:
            # Sem conteudo sexual: mecanica e uma ilusao violeta que teleporta o boss e cria um leque de projeteis.
            to=game.player.pos-self.pos
            if to.length_squared()>0:
                d=to.normalize(); self.pos=game.player.pos-d*S(330)
                a=math.atan2(d.y,d.x)
                for off in (-0.42,-0.21,0,0.21,0.42):
                    game.projectiles.append(Projectile(self.pos,vec_from_angle(a+off)*S(360),(8+self.wave*0.18)*self.boss_damage_scale*self.lira_outgoing_mult(game)*strength*difficulty_cfg(getattr(game,"difficulty","easy"))["damage"],"enemy",S(9),PINK,3.0))
            self.sin_aux=(3.4 if self.archbishop else 2.25) / diff_ai

    def die(self, game):
        if self.dead: return
        Enemy.die(self, game)
        if self.archbishop or game.mode != "arena" or is_beta_character(game.player.character):
            return
        # O fragmento vai direto ao inventario em runs normais.
        # BOSS RUSH e excecao: nunca entrega Pedacos dos Pecados.
        fragment_granted = getattr(game,"game_mode","normal") != "boss_rush"
        if fragment_granted:
            game.collect_forge_material(self.fragment_key,1)
        defeated=set(SAVE.get("sin_defeats",[])); defeated.add(self.sin_key); SAVE["sin_defeats"]=sorted(defeated)
        achievement_key = "gula_defeated" if self.sin_key == "gula" else f"sin_{self.sin_key}_defeated"
        game.unlock_achievement(achievement_key)
        if len(defeated) >= 7:
            game.unlock_achievement("all_sins")
        if all(game.forge_material_amount(k)>=1 for k in SIN_FRAGMENTS):
            game.unlock_achievement("all_sin_fragments")
        if self.sin_key == "gula":
            SAVE["gula_defeats"]=SAVE.get("gula_defeats",0)+1
        save_data(SAVE)
        if fragment_granted:
            game.unlock_notice=f"PEDACO DO PECADO: {self.sin_name}"
            game.unlock_notice_timer=4.5
        elif getattr(game,"game_mode","normal") == "boss_rush":
            game.unlock_notice="BOSS RUSH: SEM PEDACO DO PECADO"
            game.unlock_notice_timer=2.6

    def draw(self, offset):
        super().draw(offset)
        p=self.pos+offset
        if self.sin_key=="pride" and self.pride_guard>0:
            pygame.draw.circle(SCREEN,YELLOW,(int(p.x),int(p.y)),self.radius+S(16),max(2,S(4)))
        draw_text("ARCEBISPO" if self.archbishop else "PECADO",FONT_S,self.color,(p.x,p.y+self.radius+S(50)),True)

class GulaBoss(Boss):
    """Versao especial da Gula. Lembra quantas vezes ja devorou o jogador."""
    def __init__(self, pos, wave=500):
        super().__init__(pos, wave)
        hunger = max(0, int(SAVE.get("gula_hunger", 0)))
        self.variant = "gula"
        self.name = "A GULA"
        self.domain_name = "BANQUETE SEM FIM"
        self.domain_desc = "Tudo que entra vira alimento para uma fome que lembra de voce."
        self.color = (120, 18, 38)
        self.radius = S(92)
        self.hunger_level = hunger
        self.max_hp *= 1.75 * (1.0 + 0.55 * hunger)
        self.hp = self.max_hp
        self.speed *= 1.10 * (1.0 + min(0.65, 0.08 * hunger))
        self.boss_damage_scale *= 1.25 + min(2.0, 0.18 * hunger)
        self.coin_value = 5000 + 750 * hunger
        self.burst_cd = max(0.38, 1.15 - 0.07 * hunger)
        self.charge_cd = max(0.65, 2.0 - 0.10 * hunger)
        self.domain_cd = 2.8
        self.domain_radius = S(560)

    def die(self, game):
        if self.dead:
            return
        # Usa Enemy.die diretamente para nao acionar desbloqueios do Pai do Kayk.
        Enemy.die(self, game)
        if not is_beta_character(game.player.character):
            SAVE["gula_defeats"] = SAVE.get("gula_defeats", 0) + 1
            save_data(SAVE)
            game.unlock_achievement("gula_defeated")
        game.unlock_notice = "A GULA FOI DERROTADA. POR ENQUANTO."
        game.unlock_notice_timer = 6.0

    def update(self, dt, game):
        before = len(game.projectiles)
        # O comportamento-base continua valendo: movimento, investida, dominio e rajadas.
        super().update(dt, game)
        if self.dead:
            return
        if self.lira_stat_level("intelligence",game)>=0.999:
            return
        # Todo projetil criado por A Gula recebe a marca de devorar.
        for pr in game.projectiles[before:]:
            if pr.owner == "enemy":
                pr.gula_devour = True
                pr.color = (190, 35, 60)
                pr.radius = max(pr.radius, S(13))
        # Quanto mais experiencias ela devora, mais projeteis extras produz.
        if self.hunger_level > 0 and random.random() < min(0.18, dt * (0.8 + self.hunger_level*0.15)):
            target = game.player.pos - self.pos
            if target.length_squared() > 0:
                pr = Projectile(self.pos, target.normalize()*S(360 + min(240, self.hunger_level*18)), 1, "enemy", S(15), (220,45,70), 3.2)
                pr.gula_devour = True
                game.projectiles.append(pr)

    def draw(self, offset):
        super().draw(offset)
        p = self.pos + offset
        draw_text(f"FOME {self.hunger_level}", FONT_S, RED, (p.x, p.y + self.radius + S(54)), True)



class DivineDog:
    """Cao Divino do Potential Man. Possui HP proprio, regenera e ataca sozinho."""
    def __init__(self, pos, player, side=1):
        self.pos = pygame.Vector2(pos)
        self.player_ref = player
        self.side = side
        self.radius = S(24)
        # V15 PATCH: cada Cao possui 80% do HP maximo atual do Potential Man.
        # O piso de 105 preserva o balanceamento no inicio da progressao.
        self.max_hp = max(105.0, float(player.max_hp) * 0.80)
        self.hp = self.max_hp
        self.damage = max(8.0, player.base_damage * 0.62) * player.passive_ally_damage_mult() * getattr(player,"summon_power_mult",1.0)
        self.speed = S(205) * getattr(player,"summon_power_mult",1.0)
        if getattr(player,"potential_coordinated_pack",False): self.damage*=1.20; self.speed*=1.20
        if getattr(player,"potential_ten_shadows_general",False): self.damage*=1.40; self.speed*=1.15
        self.attack_cd = 0.0
        self.dead = False
        self.guardian = False
        self.color = (235,235,242) if side > 0 else (72,76,88)

    def take_damage(self, amount, game):
        if self.dead: return
        amount*=max(0.0,1.0-getattr(self.player_ref,"passive_ally_damage_reduction",lambda:0.0)())
        self.hp -= max(0.0, amount)
        game.spawn_particles(self.pos, self.color, 4)
        if self.hp <= 0:
            self.dead = True
            self.hp = 0
            others = [x for x in game.potential_summons if isinstance(x, DivineDog) and x is not self and not x.dead]
            if not others and game.player.character == "Potential Man":
                game.player.potential_dog_cd = max(game.player.potential_dog_cd, 3.5 if game.player.potential_ten_shadows_general else 7.0)
                game.damage_texts.append(DamageText("CAES DERROTADOS - 7s", pygame.Vector2(game.player.pos), RED, 1.0))

    def update(self, dt, game):
        if self.dead: return False
        self.attack_cd = max(0.0, self.attack_cd-dt)
        self.hp = min(self.max_hp, self.hp + self.max_hp*0.035*dt)
        targets=[e for e in game.enemies if not e.dead]
        maho = getattr(game, "mahoraga", None)
        if getattr(game, "mahoraga_hostile_to_dogs", False) and maho is not None and not maho.dead:
            targets.append(maho)
        if not targets:
            desired = game.player.pos + pygame.Vector2(self.side*S(55), S(35))
            d = desired-self.pos
            if d.length_squared()>S(10)**2:
                self.pos += d.normalize()*self.speed*0.70*dt
            return True
        target=min(targets,key=lambda e:e.pos.distance_to(self.pos))
        d=target.pos-self.pos; dist=max(1.0,d.length())
        if dist > self.radius+target.radius+S(10):
            self.pos += d/dist*self.speed*dt
        elif self.attack_cd<=0:
            old=game.current_damage_kind; game.current_damage_kind="divine_dog"
            if isinstance(target, MahoragaSummon):
                target.take_damage(self.damage, game, self.pos, from_player=False)
            else:
                target.damage(self.damage,game,self.pos)
            game.current_damage_kind=old
            self.attack_cd=0.55
        self.pos.x=clamp(self.pos.x,self.radius,W-self.radius)
        self.pos.y=clamp(self.pos.y,S(175)+self.radius,H-S(340)-self.radius)
        return not self.dead

    def draw(self, offset):
        p=self.pos+offset
        pygame.draw.circle(SCREEN,self.color,(int(p.x),int(p.y)),self.radius)
        pygame.draw.polygon(SCREEN,self.color,[(p.x-self.radius*0.7,p.y-self.radius*0.7),(p.x-self.radius*0.25,p.y-self.radius*1.35),(p.x,p.y-self.radius*0.65)])
        pygame.draw.polygon(SCREEN,self.color,[(p.x+self.radius*0.7,p.y-self.radius*0.7),(p.x+self.radius*0.25,p.y-self.radius*1.35),(p.x,p.y-self.radius*0.65)])
        pygame.draw.circle(SCREEN,DARK,(int(p.x-self.radius*0.30),int(p.y-self.radius*0.08)),max(2,S(3)))
        pygame.draw.circle(SCREEN,DARK,(int(p.x+self.radius*0.30),int(p.y-self.radius*0.08)),max(2,S(3)))
        bw=self.radius*2
        pygame.draw.rect(SCREEN,DARK,(p.x-bw/2,p.y-self.radius-S(14),bw,S(6)))
        pygame.draw.rect(SCREEN,GREEN,(p.x-bw/2,p.y-self.radius-S(14),bw*clamp(self.hp/self.max_hp,0,1),S(6)))


class MahoragaSummon:
    """Mahoraga e uma entidade neutra: corta inimigos e o proprio jogador."""
    def __init__(self, pos, player, wave):
        self.pos=pygame.Vector2(pos)
        self.player_ref=player
        self.radius=S(72)
        # Mahoraga deve sobreviver ao ambiente conforme a run escala.
        self.max_hp=max(1600.0 + max(0,wave-1)*55.0, float(player.max_hp)*6.0)
        self.hp=self.max_hp
        self.speed=S(170)
        self.damage=max(26.0,player.base_damage*1.35)
        self.attack_cd=0.45
        self.dead=False
        self.guardian=True
        self.resistance=0.0
        self.player_damage_adaptation=0.0
        self.wave_adaptations=0
        self.color=(220,220,205)
        self.slash_fx=0.0
        self.facing=pygame.Vector2(1,0)

    def take_damage(self, amount, game, source_pos=None, from_player=False):
        if self.dead:return
        dealt=max(0.0,amount)*(1.0-self.resistance)
        # Adaptacao maxima = o ambiente comum ja nao consegue finalizar Mahoraga.
        # O proprio jogador ainda consegue derrota-lo normalmente.
        if not from_player and self.resistance >= 0.80:
            dealt = min(dealt, max(0.0, self.hp-1.0))
        self.hp -= dealt
        if from_player and dealt > 0.0:
            domain_raw = getattr(game, "current_domain_charge_raw_override", None)
            game.current_domain_charge_raw_override = None
            if domain_raw is not None and domain_raw > 0.0:
                game.add_domain_charge(domain_raw)
        if from_player:
            if not getattr(game, "mahoraga_hostile_to_dogs", False):
                game.damage_texts.append(DamageText("MAHORAGA PROVOCADO", pygame.Vector2(self.pos), PINK, 0.65))
            game.mahoraga_hostile_to_dogs = True
        game.spawn_particles(self.pos,self.color,4)
        if self.hp<=0:
            self.hp=0; self.dead=True
            game.damage_texts.append(DamageText("MAHORAGA CAIU",pygame.Vector2(self.pos),GRAY,1.0))

    def adapt(self, game, amount=0.10, heal=False, announce=True):
        if self.dead:
            return
        self.wave_adaptations += 1
        self.resistance = min(0.80, self.resistance + amount)
        # O dano adaptativo cresce SOMENTE quando Mahoraga atinge o jogador.
        # O dano que ele causa aos inimigos permanece inalterado.
        self.player_damage_adaptation = min(0.80, self.player_damage_adaptation + amount)
        if heal:
            self.hp = self.max_hp
        if announce:
            game.damage_texts.append(DamageText(f"ADAPTACAO {int(self.resistance*100)}%",pygame.Vector2(self.pos),YELLOW,1.0))

    def end_wave_adapt(self, game):
        if self.dead:return
        self.adapt(game, 0.10, heal=True, announce=True)

    def update(self, dt, game):
        if self.dead:return False
        self.attack_cd=max(0.0,self.attack_cd-dt)
        if self.resistance > 0:
            # A roda tambem melhora a recuperacao: no cap, ~2% do HP por segundo.
            self.hp=min(self.max_hp,self.hp+self.max_hp*(0.025*self.resistance)*dt)
        self.slash_fx=max(0.0,self.slash_fx-dt)
        candidates=[e for e in game.enemies if not e.dead]
        # O jogador e deliberadamente um alvo valido.
        target=game.player
        best=self.pos.distance_to(game.player.pos)
        for e in candidates:
            d=self.pos.distance_to(e.pos)
            if d<best: target=e; best=d
        d=target.pos-self.pos
        if d.length_squared()>0:
            self.facing=d.normalize()
        if best>S(150):
            self.pos += self.facing*self.speed*dt
        if self.attack_cd<=0:
            rng=S(180)
            hit=False
            old=game.current_damage_kind; game.current_damage_kind="mahoraga_slash"
            for e in list(game.enemies):
                if not e.dead and e.pos.distance_to(self.pos)<=rng+e.radius:
                    e.damage(self.damage,game,self.pos); hit=True
            # Tambem corta o invocador se ele estiver perto.
            if game.player.pos.distance_to(self.pos)<=rng+game.player.radius:
                base_player_damage=max(12.0,min(60.0,12.0+game.wave*0.08))
                game.player.take_damage(base_player_damage*(1.0+self.player_damage_adaptation),game); hit=True
            game.current_damage_kind=old
            if hit:
                self.slash_fx=0.14
                AUDIO.play("kevyn_sword",0.68,90)
            self.attack_cd=0.72
        self.pos.x=clamp(self.pos.x,self.radius,W-self.radius)
        self.pos.y=clamp(self.pos.y,S(175)+self.radius,H-S(340)-self.radius)
        return not self.dead

    def draw(self, offset):
        p=self.pos+offset
        pygame.draw.circle(SCREEN,self.color,(int(p.x),int(p.y)),self.radius)
        pygame.draw.circle(SCREEN,DARK,(int(p.x),int(p.y)),self.radius,max(2,S(5)))
        # Roda de adaptacao simples, sem sprites pesados.
        wr=self.radius+S(28)
        pygame.draw.circle(SCREEN,YELLOW,(int(p.x),int(p.y-wr)),S(10),max(2,S(3)))
        for i in range(8):
            d=vec_from_angle(i*math.tau/8)
            a=p+d*(self.radius+S(14)); b=p+d*(self.radius+S(36))
            pygame.draw.line(SCREEN,YELLOW,a,b,max(2,S(4)))
        draw_text(f"MAHORAGA {int(self.resistance*100)}%",FONT_S,WHITE,(p.x,p.y-self.radius-S(58)),True)
        bw=self.radius*2.2
        pygame.draw.rect(SCREEN,DARK,(p.x-bw/2,p.y+self.radius+S(10),bw,S(8)))
        pygame.draw.rect(SCREEN,GREEN,(p.x-bw/2,p.y+self.radius+S(10),bw*clamp(self.hp/self.max_hp,0,1),S(8)))
        if self.slash_fx>0:
            a=math.atan2(self.facing.y,self.facing.x); r=S(155)
            rect=pygame.Rect(p.x-r,p.y-r,r*2,r*2)
            pygame.draw.arc(SCREEN,WHITE,rect,-(a+0.8),-(a-0.8),S(10))


class AdaptiveMahoragaBoss(MahoragaSummon):
    """Boss exclusivo do modo MAHORAGA: observa, aprende, sobrevive e fecha a luta em fases."""
    def __init__(self,pos,player,difficulty="easy"):
        super().__init__(pos,player,1)
        dcfg=difficulty_cfg(difficulty)
        self.radius=S(88)
        diff_hp={"easy":0.80,"normal":0.95,"hard":1.10,"monarch":1.40,"impossible":1.65}.get(difficulty,1.0)
        # V15.3: HP inicial baixo; as tres barreiras de fase impedem burst de pular a luta inteira.
        self.max_hp=max(2400.0*diff_hp, float(player.max_hp)*10.0)
        self.hp=self.max_hp
        self.base_speed=S(155)*dcfg["speed"]
        self.speed=self.base_speed
        self.base_damage=max(24.0,player.max_hp*0.065)*dcfg["damage"]
        self.damage=self.base_damage
        self.adaptation_pct=0
        self.next_adapt_gain=50
        self.adapt_timer=10.0
        self.elapsed=0.0
        self.attack_cd=0.85
        self.special_cd=4.0
        self.parry_cd=3.5
        self.parry_window=0.0
        self.learned_parry=False
        self.projectile_threats_seen=set()
        self.learned_predictive_dash=False
        self.learned_stationary_counter=False
        self.stationary_observe=0.0
        self.focus_servants=False
        self.focus_turrets=False
        self.focus_dogs=False
        self.dash_observations=0
        self._dash_was_active=False
        self.start_parries=0
        self.dash_cd=2.2
        self.dash_time=0.0
        self.dash_dir=pygame.Vector2(1,0)
        self.name="MAHORAGA — IA ADAPTATIVA"
        self.resistance=0.0
        self.player_damage_adaptation=0.0
        # Escudos de fase: qualquer dano que cruzaria o limiar para exatamente nele e ativa 2s de invulnerabilidade.
        self.phase_shields=(0.80,0.50,0.20)
        self.phase_shields_used=set()
        self.shield_timer=0.0
        # Sobrevivencia: com HP baixo e adaptacao insuficiente, ele para de atacar e compra tempo fugindo.
        self.fleeing=False
        self.flee_announced=False
        # 八握剣・輪廻神域 — Santuário da Roda Eterna.
        # Barreira fechada e soberana: sem Clash. Dura 15s quando o jogador e capturado.
        self.domain_used=False
        self.domain_active=False
        self.domain_duration=15.0
        self.domain_timer=0.0
        self.domain_center=pygame.Vector2(self.pos)
        self.domain_radius=S(731.25)  # V15.18: 30% maior que 562.5
        self.domain_player_trapped=False
        self.domain_break_timer=-1.0  # legado; o dominio nao quebra mais por estar vazio
        self.domain_wheel_timer=3.0
        self.domain_world_cut_timer=1.5
        self.domain_cut_kind="world"
        self.domain_spin_count=0
        self.domain_visual_angle=0.0
        self.domain_recent_damage={}
        self.domain_adapt_category=None
        self.domain_adapt_stacks=0
        self.domain_adapt_resistance=0.0
        self.domain_adaptation_complete=False
        self.domain_cut_pending=False
        self.domain_cut_timer=0.0
        self.domain_cut_start=pygame.Vector2()
        self.domain_cut_end=pygame.Vector2()
        self.domain_analysis_started=False
        self.domain_final_wave_delay=0.0
        self.domain_final_wave_active=False
        self.domain_final_wave_launched=False
        self.domain_final_wave_radius=0.0
        self.domain_final_wave_prev_radius=0.0
        self.domain_final_wave_hit=False

    def notify(self,game,msg,color=YELLOW):
        game.add_mahoraga_ai_message(msg,color)

    def _damage_category(self,game,kind=None):
        raw=str(kind if kind is not None else getattr(game,"current_damage_kind","") or "").lower()
        if any(k in raw for k in ("servant","guardian","dog","summon","friend","turret","miniana","orbital")):
            return "INVOCACAO"
        if any(k in raw for k in ("explosion","artillery","fuuga","blast","bomb","detonation")):
            return "EXPLOSAO"
        if any(k in raw for k in ("domain","magic","staff","reality","soul","purple","censor","sukuna","curse")):
            return "MAGIA"
        if any(k in raw for k in ("projectile","shot","bolt","shell","card","bone","pineapple","ball","arrow","bullet")):
            return "PROJETEIS"
        # Quando o caller nao marcou o tipo, usa o estilo dominante do personagem como fallback.
        char=getattr(getattr(game,"player",None),"character","")
        if char in ("Ana","Kayk","Lira Solis, A C#nsur#"):
            return "MAGIA"
        if char in ("Ruan",):
            return "INVOCACAO"
        return "FISICO"

    def _play_wheel_spin(self,game,volume=0.92):
        if not AUDIO.play_external_sfx("mahoraga_wheel",volume,120):
            AUDIO.play("domain",0.62,120)

    def activate_sovereign_domain(self,game):
        if self.domain_used or self.dead:
            return False
        if getattr(getattr(game,"player",None),"character",None)==KIRA_KEY and getattr(game.player,"kira_bites_armed",False):
            game.player.kira_trigger_bites(game,manual=False,reason="EXPANSAO DO MAHORAGA")
            return False
        self.domain_used=True
        self.domain_active=True
        self.domain_timer=self.domain_duration
        self.domain_center=pygame.Vector2(self.pos)
        self.domain_radius=S(731.25)  # 30% maior
        trapped_radius=max(S(40),self.domain_radius-getattr(game.player,"radius",S(20))-S(8))
        self.domain_player_trapped=game.player.pos.distance_to(self.domain_center)<=trapped_radius
        self.domain_break_timer=-1.0
        self.domain_wheel_timer=3.0
        self.domain_world_cut_timer=1.5
        self.domain_cut_kind="world"
        self.domain_spin_count=0
        self.domain_visual_angle=0.0
        self.domain_recent_damage={}
        self.domain_adapt_category=None
        self.domain_adapt_stacks=0
        self.domain_adapt_resistance=0.0
        self.domain_adaptation_complete=False
        self.domain_cut_pending=False
        self.domain_cut_timer=0.0
        self.domain_analysis_started=False
        self.domain_final_wave_active=False
        self.domain_final_wave_launched=False
        self.domain_final_wave_radius=0.0
        self.domain_final_wave_hit=False
        game.domain_clash_active=False
        game.domain_clash_boss=None
        self.notify(game,"八握剣・輪廻神域 — SANTUARIO DA RODA ETERNA",YELLOW)
        self.notify(game,"A roda gira a cada 3s e adapta UMA categoria por vez.",CYAN)
        if not self.domain_player_trapped:
            self.notify(game,"A barreira permanece ativa. Se o jogador entrar, nao podera mais sair.",GRAY)
        game.boss_domain_message="SANTUARIO DA RODA ETERNA"
        game.boss_domain_message_timer=2.6
        game.shake=max(game.shake,S(20)); game.flash_screen=max(game.flash_screen,0.10)
        AUDIO.play("domain",1.0,250)
        return True

    def _keep_inside_domain(self,entity):
        if not self.domain_active or not hasattr(entity,"pos"):
            return
        delta=pygame.Vector2(entity.pos)-self.domain_center
        radius=max(S(40),self.domain_radius-getattr(entity,"radius",S(20))-S(8))
        if delta.length_squared()>radius*radius:
            if delta.length_squared()<1e-6:
                delta=pygame.Vector2(1,0)
            entity.pos=self.domain_center+delta.normalize()*radius

    def _end_eternal_wheel_domain(self,game):
        if not self.domain_active:
            return
        self.domain_active=False
        self.domain_timer=0.0
        self.domain_recent_damage={}
        self.domain_adapt_category=None
        self.domain_adapt_stacks=0
        self.domain_adapt_resistance=0.0
        self.domain_adaptation_complete=False
        self.domain_cut_pending=False
        self.domain_final_wave_active=False
        self.domain_final_wave_launched=False
        self.domain_analysis_started=False
        self.notify(game,"A Roda Eterna parou. As adaptacoes do Dominio foram apagadas.",GRAY)

    def _prepare_extinction_cut(self,game,kind="world"):
        # A linha nasce mirando a posicao ATUAL do jogador; os 0,8s de aviso permitem sair dela.
        self.domain_cut_kind=str(kind or "world")
        ang=random.uniform(0.0,math.tau)
        d=vec_from_angle(ang)
        center=pygame.Vector2(game.player.pos)
        reach=max(W,H)*1.25
        self.domain_cut_start=center-d*reach
        self.domain_cut_end=center+d*reach
        self.domain_cut_timer=0.80
        self.domain_cut_pending=True

    def _domain_wheel_spin(self,game):
        self.domain_spin_count+=1
        self._play_wheel_spin(game,1.0 if self.domain_spin_count>=4 else 0.88)
        category=None
        if self.domain_recent_damage:
            category=max(self.domain_recent_damage,key=lambda k:self.domain_recent_damage.get(k,0.0))
        if category and self.domain_recent_damage.get(category,0.0)>0:
            if category==self.domain_adapt_category:
                self.domain_adapt_stacks=min(4,self.domain_adapt_stacks+1)
            else:
                self.domain_adapt_category=category
                self.domain_adapt_stacks=1
                self.domain_adaptation_complete=False
            levels=(0.15,0.30,0.50,0.90)
            self.domain_adapt_resistance=levels[self.domain_adapt_stacks-1]
            if self.domain_adapt_stacks>=4:
                self.domain_adaptation_complete=True
                self.domain_adapt_resistance=0.90
                game.boss_domain_message="「 ADAPTACAO CONCLUIDA 」"
                game.boss_domain_message_timer=1.8
                self.notify(game,f"ADAPTACAO CONCLUIDA: {category} — 90% MENOS DANO",RED)
                game.flash_screen=max(game.flash_screen,0.11); game.shake=max(game.shake,S(14))
            else:
                self.notify(game,f"RODA {self.domain_adapt_stacks}/4: {category} — -{int(self.domain_adapt_resistance*100)}% dano",YELLOW)
        else:
            self.notify(game,"A roda girou, mas nao encontrou dano suficiente para analisar.",GRAY)
        self.domain_recent_damage={}

    def _start_final_analysis(self,game):
        if self.domain_analysis_started:
            return
        self.domain_analysis_started=True
        self.domain_final_wave_delay=1.05
        self.domain_final_wave_active=False
        self.domain_final_wave_launched=False
        self.domain_final_wave_radius=S(72)
        self.domain_final_wave_prev_radius=self.domain_final_wave_radius
        self.domain_final_wave_hit=False
        game.boss_domain_message="O General Divino terminou sua analise."
        game.boss_domain_message_timer=2.4
        self.notify(game,"O General Divino terminou sua analise.",WHITE)
        game.shake=max(game.shake,S(8))

    def _update_domain_mechanics(self,dt,game):
        if not self.domain_active:
            return
        self.domain_timer=max(0.0,self.domain_timer-dt)
        fast_spin=self.domain_analysis_started or self.domain_timer<=3.0
        self.domain_visual_angle=(self.domain_visual_angle+dt*(8.5 if fast_spin else 0.65))%math.tau
        self._keep_inside_domain(self)
        # V15.18: o dominio nao quebra se estiver vazio. Quem entrar depois fica preso ate o fim.
        if not self.domain_player_trapped:
            trap_radius=max(S(40),self.domain_radius-getattr(game.player,"radius",S(20))-S(8))
            if game.player.pos.distance_to(self.domain_center)<=trap_radius:
                self.domain_player_trapped=True
                self.notify(game,"A barreira reconheceu o jogador. Agora ele nao pode mais sair.",YELLOW)
                game.damage_texts.append(DamageText("PRESO NO SANTUARIO",pygame.Vector2(game.player.pos),YELLOW,0.8))
        if self.domain_player_trapped:
            self._keep_inside_domain(game.player)
            # A barreira e fechada: aliados/invocacoes que estao dentro tambem nao conseguem sair.
            for group_name in ("servants","potential_summons","vinicius_turrets"):
                for ent in list(getattr(game,group_name,[])):
                    try:
                        if not getattr(ent,"dead",False) and pygame.Vector2(ent.pos).distance_to(self.domain_center)<=self.domain_radius+getattr(ent,"radius",0):
                            self._keep_inside_domain(ent)
                    except Exception:
                        pass

        self.domain_wheel_timer-=dt
        while self.domain_wheel_timer<=0 and self.domain_spin_count<4:
            self.domain_wheel_timer+=3.0
            self._domain_wheel_spin(game)

        # V15.18: Corte do Mundo aparece a cada 1,5s — o dobro da frequencia antiga (3s).
        if not self.domain_analysis_started:
            self.domain_world_cut_timer-=dt
            if self.domain_world_cut_timer<=0:
                self.domain_world_cut_timer+=1.5
                if not self.domain_cut_pending:
                    self._prepare_extinction_cut(game,"world")

        if self.domain_cut_pending:
            self.domain_cut_timer-=dt
            if self.domain_cut_timer<=0:
                self.domain_cut_pending=False
                if point_segment_distance(game.player.pos,self.domain_cut_start,self.domain_cut_end)<=S(30)+game.player.radius:
                    game.player.take_damage(game.player.max_hp*0.35,game)
                    game.damage_texts.append(DamageText("CORTE DO MUNDO -35%",pygame.Vector2(game.player.pos),RED,0.9))
                game.shake=max(game.shake,S(14)); AUDIO.play("kevyn_sword",0.95,70)

        if self.domain_timer<=3.0:
            self._start_final_analysis(game)

        if self.domain_analysis_started:
            self.domain_final_wave_delay-=dt
            if self.domain_final_wave_delay<=0 and not self.domain_final_wave_active and not self.domain_final_wave_launched:
                self.domain_final_wave_active=True
                self.domain_final_wave_launched=True
                self.domain_final_wave_radius=S(72)
                self.domain_final_wave_prev_radius=self.domain_final_wave_radius
                self.domain_final_wave_hit=False
                self.notify(game,"八握剣 — JULGAMENTO DO GENERAL DIVINO",YELLOW)
                game.shake=max(game.shake,S(12))
            if self.domain_final_wave_active:
                self.domain_final_wave_prev_radius=self.domain_final_wave_radius
                wave_speed=max(S(260),self.domain_radius/1.15)
                self.domain_final_wave_radius+=wave_speed*dt
                pd=game.player.pos.distance_to(self.domain_center)
                safe_radius=S(92)
                crossed=(self.domain_final_wave_prev_radius-S(18) <= pd <= self.domain_final_wave_radius+S(28))
                if crossed and not self.domain_final_wave_hit:
                    self.domain_final_wave_hit=True
                    if pd<=safe_radius:
                        game.damage_texts.append(DamageText("ZONA SEGURA",pygame.Vector2(game.player.pos),CYAN,0.8))
                    elif game.player.dash_time>0:
                        game.damage_texts.append(DamageText("ATRAVESSOU A ONDA!",pygame.Vector2(game.player.pos),CYAN,0.8))
                    else:
                        game.player.take_damage(game.player.max_hp*0.50,game)
                        game.damage_texts.append(DamageText("JULGAMENTO -50%",pygame.Vector2(game.player.pos),RED,1.0))
                if self.domain_final_wave_radius>=self.domain_radius+S(60):
                    self.domain_final_wave_active=False

        if self.domain_timer<=0:
            self._end_eternal_wheel_domain(game)

    def _domain_hit_player(self,game,damage):
        # A nova Expansao nao possui mais HITKILL. Ataques normais continuam normais.
        game.player.take_damage(damage,game)
        return False

    def _adapt_step(self,game):
        gain=min(self.next_adapt_gain,99-self.adaptation_pct)
        if gain<=0:return
        self.adaptation_pct+=gain
        self.next_adapt_gain=max(1,self.next_adapt_gain//2)
        ratio=self.adaptation_pct/100.0
        self.resistance=min(0.94,0.95*ratio)
        self.player_damage_adaptation=2.0*ratio
        self.speed=self.base_speed*(1.0+1.05*ratio)
        self.notify(game,f"Mahoraga se adaptou: {self.adaptation_pct}% | menos dano, mais dano e mais velocidade.")
        if self.adaptation_pct>=75 and not self.domain_used:
            self.activate_sovereign_domain(game)
        if self.adaptation_pct>=99:
            game.start_mahoraga_final_countdown()
        game.shake=max(game.shake,S(10)); self._play_wheel_spin(game,0.78)

    def _activate_phase_shield(self,game,threshold):
        self.phase_shields_used.add(threshold)
        self.hp=max(self.hp,self.max_hp*threshold)
        self.shield_timer=2.0
        pct=int(threshold*100)
        self.notify(game,f"ESCUDO DE ADAPTACAO: {pct}% HP — INVULNERAVEL POR 2s",CYAN)
        game.damage_texts.append(DamageText(f"ESCUDO {pct}%",pygame.Vector2(self.pos),CYAN,1.0))
        game.spawn_particles(self.pos,CYAN,24); game.shake=max(game.shake,S(12)); AUDIO.play("shield",0.95,120)

    def take_damage(self,amount,game,source_pos=None,from_player=False):
        if self.dead:return
        if self.shield_timer>0:
            game.damage_texts.append(DamageText("INVULNERAVEL",pygame.Vector2(self.pos),CYAN,0.42))
            return
        if from_player and self.learned_parry and self.parry_window>0:
            self.parry_window=0.0
            self.parry_cd=max(self.parry_cd,1.6)
            game.damage_texts.append(DamageText("PARRY!",pygame.Vector2(self.pos),YELLOW,0.7))
            game.spawn_particles(self.pos,YELLOW,10)
            d=game.player.pos-self.pos
            if d.length_squared()>0:
                d=d.normalize(); pr=Projectile(self.pos+d*S(55),d*S(880),max(12.0,self.base_damage*0.75),"enemy",S(10),YELLOW,1.5); pr.kind="mahoraga_parry_counter"; game.projectiles.append(pr)
            return
        category=self._damage_category(game)
        if self.domain_active:
            resist=self.domain_adapt_resistance if category==self.domain_adapt_category else 0.0
        else:
            resist=self.resistance
        dealt=max(0.0,amount)*(1.0-clamp(resist,0.0,0.95))
        old_hp=self.hp
        proposed=self.hp-dealt
        # Nao deixa dano explosivo atravessar as tres fases de escudo de uma vez.
        for threshold in self.phase_shields:
            if threshold in self.phase_shields_used:
                continue
            line=self.max_hp*threshold
            if old_hp>line and proposed<=line:
                self.hp=line
                self._activate_phase_shield(game,threshold)
                dealt=max(0.0,old_hp-self.hp)
                break
        else:
            self.hp=proposed
        if from_player and dealt>0:
            if self.domain_active:
                self.domain_recent_damage[category]=self.domain_recent_damage.get(category,0.0)+dealt
            domain_raw=getattr(game,"current_domain_charge_raw_override",None); game.current_domain_charge_raw_override=None
            if domain_raw is not None and domain_raw>0: game.add_domain_charge(domain_raw)
        if dealt>0: game.spawn_particles(self.pos,self.color,4)
        if self.hp<=0:
            self.hp=0; self.dead=True
            if self.domain_active:self._end_eternal_wheel_domain(game)
            game.damage_texts.append(DamageText("MAHORAGA FOI EXORCIZADO",pygame.Vector2(self.pos),YELLOW,1.2))

    def _pick_target(self,game):
        if self.focus_turrets:
            ts=[t for t in game.vinicius_turrets if not t.dead]
            if ts:return min(ts,key=lambda x:x.pos.distance_to(self.pos))
        if self.focus_servants:
            ss=[s for s in game.servants if not s.dead]
            if ss:return min(ss,key=lambda x:x.pos.distance_to(self.pos))
        if self.focus_dogs:
            ds=[d for d in game.potential_summons if isinstance(d,DivineDog) and not d.dead]
            if ds:return min(ds,key=lambda x:x.pos.distance_to(self.pos))
        return game.player

    def _hit_target(self,target,damage,game):
        if self.domain_active:
            damage *= (1.0 + 0.10*min(4,int(getattr(self,"domain_spin_count",0))))
        if target is game.player:
            self._domain_hit_player(game,damage)
        elif hasattr(target,"take_damage"):
            target.take_damage(damage,game)

    def _incoming_projectile(self,game):
        best=None; best_t=999.0
        for pr in game.projectiles:
            if getattr(pr,"owner",None)!="player" or getattr(pr,"hit_mahoraga",False):
                continue
            vel=pygame.Vector2(getattr(pr,"vel",(0,0)))
            speed=vel.length()
            if speed<1.0:
                continue
            to_me=self.pos-pr.pos; dist=to_me.length()
            if dist>S(760) or dist<1.0:
                continue
            approach=vel.normalize().dot(to_me/dist)
            if approach<0.74:
                continue
            lateral=abs(to_me.cross(vel.normalize()))
            if lateral>self.radius+getattr(pr,"radius",S(8))+S(70):
                continue
            t=dist/speed
            if t<best_t:
                best,best_t=pr,t
        return best,best_t

    def reflect_projectile(self,pr,game):
        """Parry real: devolve o mesmo projetil ao jogador, como o Parry jogavel."""
        if self.parry_window<=0 or getattr(pr,"owner",None)!="player":
            return False
        self.parry_window=0.0
        self.parry_cd=max(self.parry_cd,1.6)
        pr.owner="enemy"
        pr.vel *= -1.35
        pr.damage *= 2.2
        pr.color=YELLOW
        pr.parry_reflected=True
        pr.hit_mahoraga=True
        game.damage_texts.append(DamageText("PARRY! REFLETIDO",pygame.Vector2(self.pos),YELLOW,0.7))
        game.spawn_particles(self.pos,YELLOW,12)
        game.shake=max(game.shake,S(9))
        AUDIO.play("parry",0.95,80)
        return True

    def _learn(self,game,dt):
        if game.player.character=="Ruan" and not self.focus_servants and any(not s.dead for s in game.servants):
            self.focus_servants=True; self.notify(game,"Mahoraga entendeu o Ruan: vai derrotar os Amigos primeiro.",PINK)
        if game.player.character=="Vinicius 13" and not self.focus_turrets and any(not t.dead for t in game.vinicius_turrets):
            self.focus_turrets=True; self.notify(game,"Mahoraga entendeu o Vinicius: as torretas agora sao prioridade.",ORANGE)
        if game.player.character=="Potential Man" and not self.focus_dogs and any(isinstance(d,DivineDog) and not d.dead for d in game.potential_summons):
            self.focus_dogs=True; self.notify(game,"Mahoraga reconheceu os Caes Divinos e vai elimina-los primeiro.",CYAN)
        active=game.player.dash_time>0
        if active and not self._dash_was_active:self.dash_observations+=1
        self._dash_was_active=active
        if not self.learned_predictive_dash and self.dash_observations>=2:
            self.learned_predictive_dash=True; self.notify(game,f"Mahoraga aprendeu como {game.player.character} usa o Dash. Agora ele prediz a rota.",CYAN)
        threat,ttc=self._incoming_projectile(game)
        if threat is not None:
            pid=id(threat)
            if pid not in self.projectile_threats_seen:
                self.projectile_threats_seen.add(pid)
                if len(self.projectile_threats_seen)>48:
                    self.projectile_threats_seen=set(list(self.projectile_threats_seen)[-24:])
            if not self.learned_parry and (len(self.projectile_threats_seen)>=3 or self.adaptation_pct>=50):
                self.learned_parry=True
                self.notify(game,"Mahoraga identificou projeteis em rota de colisao. PARRY REATIVO aprendido.",YELLOW)
        if not self.learned_parry and game.parries-self.start_parries>=2:
            self.learned_parry=True; self.notify(game,f"Mahoraga aprendeu o PARRY de {game.player.character}. Agora ele tambem pode bloquear ataques.",YELLOW)
        if game.player.character==HANK_KEY and not self.learned_stationary_counter:
            if game.player.still_timer>=1.5:self.stationary_observe+=dt
            else:self.stationary_observe=max(0.0,self.stationary_observe-dt*0.5)
            if self.stationary_observe>=2.25:
                self.learned_stationary_counter=True; self.notify(game,"Mahoraga entendeu a Artilharia do Hank: ficar parado agora atrai investidas e pressao.",ORANGE)
        return threat,ttc

    def update(self,dt,game):
        if self.dead:return False
        self.elapsed+=dt
        if not self.domain_active:self.adapt_timer-=dt
        self.attack_cd=max(0.0,self.attack_cd-dt); self.special_cd=max(0.0,self.special_cd-dt)
        self.parry_cd=max(0.0,self.parry_cd-dt); self.parry_window=max(0.0,self.parry_window-dt); self.dash_cd=max(0.0,self.dash_cd-dt)
        self.shield_timer=max(0.0,self.shield_timer-dt); self.slash_fx=max(0.0,self.slash_fx-dt)
        if self.domain_active:
            self._update_domain_mechanics(dt,game)
            if not self.domain_active:
                pass
            elif self.domain_analysis_started:
                # Nos 3s finais Mahoraga para de atacar e apenas conclui a analise.
                self.pos.x=clamp(self.pos.x,self.radius,W-self.radius); self.pos.y=clamp(self.pos.y,S(175)+self.radius,H-S(340)-self.radius)
                return not self.dead
        while (not self.domain_active) and self.adapt_timer<=0 and self.adaptation_pct<99:
            self.adapt_timer+=10.0; self._adapt_step(game)
        threat,ttc=self._learn(game,dt)
        ratio=self.adaptation_pct/100.0
        hp_ratio=self.hp/max(1.0,self.max_hp)
        # Parry so abre quando um projetil REALMENTE esta vindo na direcao dele.
        if self.learned_parry and self.parry_cd<=0 and threat is not None and ttc<=0.70:
            self.parry_window=clamp(ttc+0.13,0.20,0.52)
            self.parry_cd=max(1.25,2.8-1.1*ratio)
            game.damage_texts.append(DamageText("PARRY REATIVO",pygame.Vector2(self.pos),YELLOW,0.50))
        # HP baixo + pouca adaptacao: para de atacar e foge para comprar segundos de observacao.
        self.fleeing=(hp_ratio<=0.35 and self.adaptation_pct<75 and not self.domain_active)
        if self.fleeing:
            if not self.flee_announced:
                self.flee_announced=True; self.notify(game,"HP baixo e adaptacao insuficiente: Mahoraga esta GANHANDO TEMPO.",ORANGE)
            away=self.pos-game.player.pos
            if away.length_squared()<1.0:away=vec_from_angle(random.random()*math.tau)
            away=away.normalize(); self.facing=-away
            if self.dash_cd<=0:
                self.dash_dir=away; self.dash_time=0.20; self.dash_cd=max(0.8,1.7-0.6*ratio)
            if self.dash_time>0:
                self.dash_time-=dt; self.pos+=self.dash_dir*self.speed*4.7*dt
            else:
                self.pos+=away*self.speed*1.35*dt
            self.pos.x=clamp(self.pos.x,self.radius,W-self.radius); self.pos.y=clamp(self.pos.y,S(175)+self.radius,H-S(340)-self.radius)
            return not self.dead
        elif self.flee_announced and (hp_ratio>0.35 or self.adaptation_pct>=75):
            self.flee_announced=False
        target=self._pick_target(game)
        delta=target.pos-self.pos; dist=max(1.0,delta.length()); d=delta/dist; self.facing=pygame.Vector2(d)
        if self.learned_stationary_counter and target is game.player and game.player.still_timer>=1.5 and not self.domain_active:
            self.dash_cd=min(self.dash_cd,0.30); self.attack_cd=min(self.attack_cd,0.20)
        if (self.learned_predictive_dash or self.learned_stationary_counter) and self.dash_cd<=0 and target is game.player:
            mv=game.get_move_dir(); predicted=game.player.pos+(mv.normalize()*S(190) if mv.length_squared()>0 else pygame.Vector2())
            dd=predicted-self.pos
            if dd.length_squared()>0:self.dash_dir=dd.normalize(); self.dash_time=0.24; self.dash_cd=max(0.75,2.25-1.2*ratio)
        if self.dash_time>0:
            self.dash_time-=dt; self.pos+=self.dash_dir*self.speed*(4.2+1.8*ratio)*dt
            if self.pos.distance_to(target.pos)<=self.radius+getattr(target,"radius",S(25))+S(12):
                self._hit_target(target,self.base_damage*(1.0+2.0*ratio)*1.15,game); self.dash_time=0
        else:
            desired=S(135 if target is not game.player else 170)
            if dist>desired:self.pos+=d*self.speed*dt
        if self.attack_cd<=0 and game.state=="playing":
            atk=self.base_damage*(1.0+2.0*ratio)
            if dist<=S(205)+getattr(target,"radius",0):
                self._hit_target(target,atk,game); self.slash_fx=0.16; AUDIO.play("kevyn_sword",0.72,90)
            elif target is game.player:
                pr=Projectile(self.pos+d*S(60),d*S(620+500*ratio),atk*0.82,"enemy",S(12),self.color,2.2)
                pr.kind="mahoraga_adaptive_slash"; pr.mahoraga_owner=self; game.projectiles.append(pr)
            self.attack_cd=max(0.18,0.88*(1.0-0.72*ratio))
        if self.adaptation_pct>=75 and self.special_cd<=0 and game.state=="playing":
            self.special_cd=max(1.8,4.8-2.2*ratio)
            radius=S(255); game.spawn_particles(self.pos,YELLOW,22); game.shake=max(game.shake,S(10))
            if game.player.pos.distance_to(self.pos)<=radius+game.player.radius:self._hit_target(game.player,self.base_damage*(0.75+ratio),game)
            for ss in list(game.servants):
                if not ss.dead and ss.pos.distance_to(self.pos)<=radius+ss.radius:ss.take_damage(self.base_damage*(0.9+ratio),game)
            for t in list(game.vinicius_turrets):
                if not t.dead and t.pos.distance_to(self.pos)<=radius+t.radius:t.take_damage(self.base_damage*(0.9+ratio),game)
        self.pos.x=clamp(self.pos.x,self.radius,W-self.radius); self.pos.y=clamp(self.pos.y,S(175)+self.radius,H-S(340)-self.radius)
        if self.domain_active:
            self._keep_inside_domain(self)
            if self.domain_player_trapped:
                self._keep_inside_domain(game.player)
        return not self.dead

    def draw(self,offset):
        super().draw(offset)
        p=self.pos+offset
        draw_text(f"IA {self.adaptation_pct}%",FONT_S,YELLOW,(p.x,p.y+self.radius+S(36)),True)
        if self.parry_window>0:pygame.draw.circle(SCREEN,YELLOW,(int(p.x),int(p.y)),self.radius+S(18),max(2,S(5)))
        if self.shield_timer>0:
            pygame.draw.circle(SCREEN,CYAN,(int(p.x),int(p.y)),self.radius+S(24),max(2,S(8)))
            draw_text(f"ESCUDO {self.shield_timer:.1f}s",FONT_S,CYAN,(p.x,p.y-self.radius-S(82)),True)


class SansBossBoneHazard:
    def __init__(self,pos,direction,length,damage,mode="white",life=7.0,motion="vertical",amplitude=None,move_speed=None):
        self.base_pos=pygame.Vector2(pos); self.pos=pygame.Vector2(pos); self.direction=pygame.Vector2(direction)
        if self.direction.length_squared()<0.001:self.direction=pygame.Vector2(1,0)
        self.direction=self.direction.normalize(); self.length=float(length); self.width=S(15)
        self.damage=float(damage); self.mode=mode; self.life=float(life); self.hit_cd=0.0
        self.motion=motion; self.motion_time=random.random()*math.tau
        self.amplitude=float(S(70) if amplitude is None else amplitude)
        self.move_speed=float(random.uniform(1.4,2.15) if move_speed is None else move_speed)
        self.spin_speed=random.choice((-1,1))*random.uniform(80.0,135.0)
    def endpoints(self):
        d=self.direction*(self.length*0.5); return self.pos-d,self.pos+d
    def update(self,dt,game):
        self.life-=dt; self.hit_cd=max(0.0,self.hit_cd-dt); self.motion_time+=dt*self.move_speed
        if self.life<=0:return False
        if self.motion=="vertical":
            self.pos=self.base_pos+pygame.Vector2(0,math.sin(self.motion_time)*self.amplitude)
        elif self.motion=="horizontal":
            self.pos=self.base_pos+pygame.Vector2(math.sin(self.motion_time)*self.amplitude,0)
        elif self.motion=="spin":
            self.pos=pygame.Vector2(self.base_pos)
            self.direction=self.direction.rotate(self.spin_speed*dt)
        p=game.player; a,b=self.endpoints()
        if self.hit_cd<=0 and point_segment_distance(p.pos,a,b)<=self.width+p.radius:
            moving=game.get_move_dir().length_squared()>0.02 or p.dash_time>0
            active=(self.mode=="white") or (self.mode=="blue" and moving) or (self.mode=="orange" and not moving)
            if active:
                p.take_damage(self.damage,game); self.hit_cd=0.55
        return True
    def draw(self,offset):
        p=self.pos+offset; thickness=max(S(30),int(self.width*2.15))
        img = sans_bone_special_surface(self.mode,self.length,thickness,self.direction) if self.mode in ("blue","orange") else sans_bone_large_surface(self.length,thickness,self.direction)
        if img is not None:
            SCREEN.blit(img,img.get_rect(center=(int(p.x),int(p.y))))
        else:
            d=pygame.Vector2(self.direction)
            if d.length_squared()<=0.001:d=pygame.Vector2(1,0)
            d=d.normalize(); a=p-d*(self.length*0.5); b=p+d*(self.length*0.5)
            col=CYAN if self.mode=="blue" else (ORANGE if self.mode=="orange" else WHITE)
            pygame.draw.line(SCREEN,col,(int(a.x),int(a.y)),(int(b.x),int(b.y)),max(S(8),thickness))


class SansBossBlasterHazard:
    def __init__(self,pos,target,damage,scale=1.0):
        self.pos=pygame.Vector2(pos); self.target=pygame.Vector2(target); self.damage=float(damage); self.scale=float(scale)
        d=self.target-self.pos; self.direction=d.normalize() if d.length_squared()>0.001 else pygame.Vector2(1,0)
        self.timer=0.62; self.total=0.62; self.beam_timer=0.0; self.fired=False; self.dead=False; self.sound_played=False
    def update(self,dt,game):
        if self.dead:return False
        if not self.sound_played:
            self.sound_played=True
            if not AUDIO.play_external_sfx("sans_blaster",0.82,45): AUDIO.play("boss",0.52,45)
        if not self.fired:
            d=game.player.pos-self.pos
            if d.length_squared()>0.001 and self.timer>0.08:self.direction=d.normalize()
            self.timer-=dt
            if self.timer<=0:
                self.fired=True; self.beam_timer=0.20
                d=self.direction; start=self.pos+d*S(58); end=ray_to_arena_edge(start,d)
                if beam_hits_point_fast(game.player.pos,start,d,max(1.0,(end-start).length()),S(40)*self.scale+game.player.radius):
                    game.player.take_damage(self.damage,game)
                game.shake=max(game.shake,S(8))
        else:
            self.beam_timer-=dt
            if self.beam_timer<=0:self.dead=True
        return not self.dead
    def draw(self,offset):
        p=self.pos+offset; d=self.direction
        angle=math.degrees(math.atan2(d.y,d.x))-90.0
        if not self.fired:
            progress=clamp(1.0-max(0.0,self.timer)/self.total,0,1)
            idx=0 if progress<.28 else (1 if progress<.56 else (2 if progress<.86 else 3))
        else: idx=3
        img=sans_blaster_frame_surface(idx,int(S(185)*self.scale),angle)
        if img is not None: SCREEN.blit(img,img.get_rect(center=(int(p.x),int(p.y))))
        if self.fired and self.beam_timer>0:
            start=p+d*S(58); end=ray_to_arena_edge(start,d)
            pygame.draw.line(SCREEN,CYAN,start,end,max(S(16),int(S(50)*self.scale)))


class SansTrialBoss(Enemy):
    """Boss de resistencia: Sans sobrevive gastando Estamina para esquivar."""
    def __init__(self,pos,game):
        super().__init__(pos,"kiter",1,None)
        self.kind="sans_trial_boss"; self.radius=S(34); self.max_hp=1.0; self.hp=1.0; self.speed=0.0; self.contact_damage=0.0
        self.color=CYAN; self.name="SANS — BOSSFIGHT"
        # V15.15.4: valor fixo pedido para a provacao.
        self.max_stamina=1000.0
        self.stamina=self.max_stamina
        self.dodge_cost=max(24.0,self.max_stamina/25.0)
        self.time_since_attack=0.0; self.regen_tick=0.0; self.wave_index=0
        self.final_judgement=False; self.relocate_cd=3.4
        self.soul_push_timer=0.0; self.soul_push_dir=pygame.Vector2()
        self.soul_cd=random.uniform(2.2,3.0)
        self.flash=0; self.lira_censor={"strength":0.0,"speed":0.0,"resistance":0.0,"intelligence":0.0}; self.lira_domain_stats=set(); self.lira_fully_censored=False
        self.wave_started=False; self.intro_timer=0.40
        # Fase final de desespero.
        self.desperation_active=False
        self.desperation_timer=0.0
        self.desperation_blasts_left=0
        self.desperation_total_blasts=12
        self.exhausted=False
        self.teleport_far(game,play_effect=False)

    def _arena_bounds(self):
        return S(80),W-S(80),S(215),H-S(385)

    def _teleport_effect(self,game):
        game.sans_teleport_blackout=max(getattr(game,"sans_teleport_blackout",0.0),0.50)
        if not AUDIO.play_external_sfx("sans_teleport",1.0,70):
            AUDIO.play("dash",0.82,70)

    def teleport_far(self,game,play_effect=True):
        left,right,top,bottom=self._arena_bounds()
        spots=[pygame.Vector2(left,top),pygame.Vector2(right,top),pygame.Vector2(left,bottom),pygame.Vector2(right,bottom)]
        self.pos=max(spots,key=lambda q:q.distance_to(game.player.pos))
        if play_effect:
            self._teleport_effect(game)

    def _hazard_damage(self,game,ratio=.05):
        return max(5.0,game.player.max_hp*ratio)*difficulty_cfg(getattr(game,"difficulty","easy"))["damage"]

    def _spread_positions(self,game,count):
        """Distribui slots pela arena inteira, sem formar escada/corredor."""
        left,right,top,bottom=self._arena_bounds()
        cols=7 if count>=21 else 6
        rows=4 if count>=21 else 3
        cell_w=(right-left)/float(cols)
        cell_h=(bottom-top)/float(rows)
        cells=[]
        for ry in range(rows):
            for cx in range(cols):
                x=left+(cx+0.5)*cell_w
                y=top+(ry+0.5)*cell_h
                x+=random.uniform(-cell_w*0.22,cell_w*0.22)
                y+=random.uniform(-cell_h*0.20,cell_h*0.20)
                q=pygame.Vector2(x,y)
                # Evita nascer exatamente em cima do jogador/Sans.
                if q.distance_to(game.player.pos)<S(105):
                    q+=pygame.Vector2(random.choice((-1,1))*S(90),random.choice((-1,1))*S(55))
                if q.distance_to(self.pos)<S(95):
                    q+=pygame.Vector2(random.choice((-1,1))*S(70),random.choice((-1,1))*S(45))
                q.x=clamp(q.x,left,right); q.y=clamp(q.y,top,bottom)
                cells.append(q)
        random.shuffle(cells)
        return cells[:min(count,len(cells))]

    def start_wave(self,game,initial=False):
        if self.exhausted or self.desperation_active:
            return
        game.sans_boss_bones=[]; game.sans_boss_blasters=[]
        if not initial:self.wave_index+=1
        pattern=self.wave_index%4

        # Ossos realmente espalhados por TODA a arena.
        total_bones=18 if not self.final_judgement else 28
        positions=self._spread_positions(game,total_bones)
        special_count=(6 if pattern==1 else 3) if not self.final_judgement else 13
        for i,center in enumerate(positions):
            mode="white"
            if i<special_count:
                mode="blue" if i%2==0 else "orange"
            direction=random.choice((pygame.Vector2(1,0),pygame.Vector2(0,1)))
            if self.final_judgement:
                motion=random.choice(("vertical","horizontal","spin"))
                amp=S(random.randint(55,95))
            else:
                motion="vertical"
                amp=S(random.randint(50,78))
            game.sans_boss_bones.append(
                SansBossBoneHazard(center,direction,S(random.randint(135,175)),self._hazard_damage(game,.04 if mode=="white" else .035),mode,6.6,motion=motion,amplitude=amp)
            )

        # Blasters em toda onda e mais frequentes na Verdadeira Batalha.
        left,right,top,bottom=self._arena_bounds()
        edge_spots=[
            pygame.Vector2(left,top),pygame.Vector2(right,top),pygame.Vector2(left,bottom),pygame.Vector2(right,bottom),
            pygame.Vector2((left+right)/2,top),pygame.Vector2((left+right)/2,bottom),pygame.Vector2(left,(top+bottom)/2),pygame.Vector2(right,(top+bottom)/2)
        ]
        random.shuffle(edge_spots)
        count=2 if not self.final_judgement else 4
        if pattern==2: count+=1
        for q in edge_spots[:count]:
            game.sans_boss_blasters.append(SansBossBlasterHazard(q,game.player.pos,self._hazard_damage(game,.075),1.50 if self.final_judgement else 1.20))

        # Ondas de ALMA extras, agora instantaneas.
        if pattern==3:
            self.trigger_soul_blast(game)

    def _spawn_soul_wall(self,game):
        p=pygame.Vector2(game.player.pos); d=pygame.Vector2(self.soul_push_dir)
        if d.length_squared()<0.001:return
        tangent=pygame.Vector2(-d.y,d.x); damage=self._hazard_damage(game,.04)
        for i in range(10):
            off=(i-4.5)*S(25); center=p+tangent*off-d*S(55)
            motion="vertical" if not self.final_judgement else ("spin" if i%3==0 else "horizontal")
            game.sans_boss_bones.append(SansBossBoneHazard(center,-d,S(150),damage,"blue" if i%2==0 else "orange",4.8,motion=motion,amplitude=S(42)))

    def trigger_soul_blast(self,game,desperation=False):
        """ALMA instantanea: explosao que joga o jogador direto numa parede."""
        p=game.player
        dirs=[pygame.Vector2(1,0),pygame.Vector2(-1,0),pygame.Vector2(0,1),pygame.Vector2(0,-1)]
        d=random.choice(dirs)
        self.soul_push_dir=pygame.Vector2(d)
        left,right,top,bottom=S(25)+p.radius,W-S(25)-p.radius,p.radius,H-p.radius
        if d.x>0:
            p.pos.x=right; p.pos.y=clamp(p.pos.y+random.uniform(-S(90),S(90)),top,bottom)
        elif d.x<0:
            p.pos.x=left; p.pos.y=clamp(p.pos.y+random.uniform(-S(90),S(90)),top,bottom)
        elif d.y>0:
            p.pos.y=bottom; p.pos.x=clamp(p.pos.x+random.uniform(-S(130),S(130)),left,right)
        else:
            p.pos.y=top; p.pos.x=clamp(p.pos.x+random.uniform(-S(130),S(130)),left,right)
        p.invuln=max(getattr(p,"invuln",0.0),0.12)
        if not AUDIO.play_external_sfx("sans_soul",0.95,120):
            AUDIO.play("domain",0.72,120)
        game.shake=max(game.shake,S(18 if desperation else 13))
        game.flash_screen=max(getattr(game,"flash_screen",0.0),0.04)
        if not desperation:
            self._spawn_soul_wall(game)
            game.damage_texts.append(DamageText("ALMA!",pygame.Vector2(p.pos),CYAN,0.45))

    def _start_desperation(self,game):
        self.desperation_active=True
        self.exhausted=False
        self.desperation_blasts_left=self.desperation_total_blasts
        self.desperation_timer=0.12
        self.stamina=0.0
        game.sans_boss_bones=[]; game.sans_boss_blasters=[]
        game.damage_texts.append(DamageText("...",pygame.Vector2(self.pos),WHITE,0.8))
        game.shake=max(game.shake,S(12))

    def _finish_desperation(self,game):
        self.desperation_active=False
        self.exhausted=True
        self.stamina=0.0
        game.sans_boss_bones=[]; game.sans_boss_blasters=[]
        game.player.hp=max(1.0,min(game.player.hp,1.0))
        game.damage_texts.append(DamageText("EXAUSTO",pygame.Vector2(self.pos),RED,2.0))
        game.damage_texts.append(DamageText("...AGORA.",pygame.Vector2(game.player.pos),WHITE,1.3))
        game.shake=max(game.shake,S(8))

    def damage(self,amount,game,source_pos=None,minimal_fx=False):
        if self.dead:return
        if self.desperation_active:
            return
        if self.exhausted:
            self.hp=0; self.dead=True
            game.damage_texts.append(DamageText("SANS FOI ATINGIDO",pygame.Vector2(self.pos),YELLOW,1.2))
            game.sans_trial_victory_pending=True
            return
        if not self.wave_started:
            self.wave_started=True; self.intro_timer=0.0; self.start_wave(game,initial=True)
        self.time_since_attack=0.0; self.regen_tick=0.0
        if self.stamina>0:
            self.hp=1.0; self.dead=False
            self.stamina=max(0.0,self.stamina-self.dodge_cost)
            game.damage_texts.append(DamageText("MISS",pygame.Vector2(self.pos),WHITE,0.65))
            if not AUDIO.play_external_sfx("sans_dodge",1.0,55):AUDIO.play("perfect",0.8,55)
            if self.stamina<=self.max_stamina*0.50 and not self.final_judgement:
                self.final_judgement=True; self.relocate_cd=2.5; self.soul_cd=1.35
                game.damage_texts.append(DamageText("A VERDADEIRA BATALHA COMEÇA.",pygame.Vector2(self.pos),RED,1.8)); game.shake=max(game.shake,S(18))
            if self.stamina<=0:
                # O golpe que esgota a barra inicia a ultima tentativa desesperada.
                self._start_desperation(game)
                return
            # Toda esquiva/troca de lugar usa o MESMO efeito do teleporte jogavel.
            self.teleport_far(game,play_effect=True)
            self.start_wave(game)
            return

    def die(self,game):
        self.damage(999999,game)

    def update(self,dt,game):
        if self.dead:return False
        if not self.wave_started:
            self.intro_timer=max(0.0,self.intro_timer-dt)
            if self.intro_timer<=0:
                self.wave_started=True; self.start_wave(game,initial=True)
            return True

        # Ultimo desespero: ALMA para todos os lados e HP do jogador nunca passa de 1 para baixo.
        if self.desperation_active:
            game.sans_boss_bones=[]; game.sans_boss_blasters=[]
            self.desperation_timer-=dt
            if self.desperation_timer<=0:
                remaining=max(1,self.desperation_blasts_left)
                self.trigger_soul_blast(game,desperation=True)
                p=game.player
                if self.desperation_blasts_left<=1:
                    p.hp=1.0
                else:
                    # Cada explosao parece fatal, mas a sequencia e estritamente nao letal.
                    chunk=max(p.max_hp*0.11,(p.hp-1.0)/remaining)
                    p.hp=max(1.0,p.hp-chunk)
                p.invuln=max(getattr(p,"invuln",0.0),0.16)
                self.desperation_blasts_left-=1
                self.desperation_timer=0.22
                if self.desperation_blasts_left<=0:
                    self._finish_desperation(game)
            return True

        if self.exhausted:
            game.sans_boss_bones=[]; game.sans_boss_blasters=[]
            return True

        self.time_since_attack+=dt; self.flash=max(0.0,self.flash-dt)
        # V15.15.4: Sans so recupera depois de 10s sem o jogador atacar.
        if self.time_since_attack>=10.0 and self.stamina<self.max_stamina:
            self.regen_tick+=dt
            if self.regen_tick>=1.0:
                self.regen_tick-=1.0; gain=self.max_stamina*0.015; self.stamina=min(self.max_stamina,self.stamina+gain)
                game.damage_texts.append(DamageText(f"SANS RECUPEROU +{int(gain)} STA",pygame.Vector2(self.pos),CYAN,0.8))

        # ALMA muito mais frequente e instantanea.
        self.soul_cd-=dt
        if self.soul_cd<=0:
            self.trigger_soul_blast(game)
            self.soul_cd=random.uniform(1.25,1.9) if self.final_judgement else random.uniform(2.0,2.8)

        if self.final_judgement:
            self.relocate_cd-=dt
            if self.relocate_cd<=0:
                self.relocate_cd=random.uniform(2.3,3.6)
                if self.pos.distance_to(game.player.pos)>S(210) and random.random()<0.62:
                    self.teleport_far(game,play_effect=True)
                    self.start_wave(game)
                    game.damage_texts.append(DamageText("AINDA NAO.",pygame.Vector2(self.pos),WHITE,0.65))
        return True

    def draw(self,offset):
        p=self.pos+offset
        img=sans_player_surface("down",0,max(S(118),int(self.radius*5.7)))
        if img is not None:SCREEN.blit(img,img.get_rect(midbottom=(int(p.x),int(p.y+self.radius+S(8)))))
        else:pygame.draw.circle(SCREEN,WHITE,(int(p.x),int(p.y)),self.radius)
        if self.exhausted:
            draw_text("EXAUSTO",FONT_S,RED,(p.x,p.y-self.radius-S(42)),True)
        elif self.desperation_active:
            draw_text("!!!",FONT_M,RED,(p.x,p.y-self.radius-S(42)),True)
        elif self.final_judgement:
            pygame.draw.circle(SCREEN,RED,(int(p.x),int(p.y)),self.radius+S(20),max(2,S(4)))


class KiraSheerHeartAttack:
    """Unidade automatica do Kira. Visual e hitbox procedurais para nunca sumir por asset faltando."""
    def __init__(self, owner):
        self.owner=owner
        self.pos=pygame.Vector2(owner.pos)
        self.radius=S(19)
        self.speed=S(250)
        self.timer=8.0*(1.0+0.35*float(getattr(owner,"kira_passive_heart",0) or 0))
        self.hit_cd=0.0
        self.damage=72.0*(1.0+0.25*float(getattr(owner,"kira_passive_heart",0) or 0))
        self.dead=False
        self.angle=0.0
    def update(self,dt,game):
        if self.dead: return False
        self.timer-=dt; self.hit_cd=max(0.0,self.hit_cd-dt); self.angle+=dt*4.0
        if self.timer<=0:
            self.dead=True; return False
        targets=[e for e in game.enemies if not getattr(e,"dead",False)]
        maho=getattr(game,"mahoraga",None)
        if maho is not None and not getattr(maho,"dead",True): targets.append(maho)
        if targets:
            target=min(targets,key=lambda e:e.pos.distance_to(self.pos))
            d=target.pos-self.pos
            if d.length_squared()>0.01:
                self.pos += d.normalize()*self.speed*dt
            if self.hit_cd<=0 and self.pos.distance_to(target.pos)<=self.radius+getattr(target,"radius",S(20))+S(8):
                game.kira_sha_explode(self.pos,self.damage)
                self.hit_cd=0.62
                # pequeno recuo para nao ficar explodindo o mesmo alvo todo frame
                if d.length_squared()>0.01: self.pos-=d.normalize()*S(42)
        self.pos.x=clamp(self.pos.x,self.radius,W-self.radius)
        self.pos.y=clamp(self.pos.y,self.radius,H-self.radius)
        return True
    def draw(self,offset):
        p=self.pos+offset
        # corpo tipo mini tanque/coracao: procedural e sempre visivel
        pygame.draw.circle(SCREEN,(240,198,72),(int(p.x),int(p.y)),self.radius)
        pygame.draw.circle(SCREEN,(92,54,118),(int(p.x),int(p.y)),self.radius,max(2,S(4)))
        pygame.draw.rect(SCREEN,(92,54,118),(int(p.x-self.radius*0.95),int(p.y+self.radius*0.25),int(self.radius*1.9),max(S(7),int(self.radius*0.42))),border_radius=S(4))
        eye=p+vec_from_angle(self.angle)*S(5)
        pygame.draw.circle(SCREEN,RED,(int(eye.x),int(eye.y)),max(2,S(4)))
        for sx in (-1,1):
            pygame.draw.circle(SCREEN,DARK,(int(p.x+sx*self.radius*0.55),int(p.y+self.radius*0.78)),max(S(4),int(self.radius*0.34)))


class Player:
    def __init__(self, game, character="Ycaro"):
        self.character = character if character in CHARACTER_CONFIG else "Ycaro"
        cfg = CHARACTER_CONFIG[self.character]
        self.radius = S(28)
        self.pos = pygame.Vector2(W / 2, H * 0.62)
        self.facing = pygame.Vector2(0, -1)
        self.color = cfg["color"]
        self.passive_keys = passive_equipped_keys(self.character) if not is_beta_character(self.character) else []
        self.passive_static = passive_static_effects(self.passive_keys)
        self.passive_upgrade_count = 0
        self.passive_wave_count = 0
        self.passive_dash_buff_timer = 0.0
        self.passive_protagonist_used = False
        self.passive_progress_hp_base = 0.0
        # Beta usa valores-base fixos: nao recebe nem aplica pontos de evolucao.
        evo = evolution_profile(self.character) if not is_beta_character(self.character) else {key: 0 for key in EVOLUTION_STAT_KEYS}
        self.evolution = evo
        self.evo_resistance = evo.get("resistance", 0)
        self.evo_parry = evo.get("parry", 0)
        self.base_speed = S(cfg["speed"]) * (1 + min(0.30,0.0075 * permanent_effective_level("speed_level"))) * (1 + 0.015 * evo.get("speed", 0))
        self.base_speed *= max(0.10, 1.0 + self.passive_static.get("move",0.0))
        self.speed_mult = 1.0
        self.speed_buff = 0
        self.still_timer = 0.0

        self.max_hp = cfg["hp"] + permanent_effective_level("vitality_level") * 5 + evo.get("hp", 0) * 6
        if self.character not in ("Sans", "Glonk 100% Power"):
            self.max_hp *= max(0.10, 1.0 + self.passive_static.get("hp",0.0))
        self.hp = self.max_hp
        self.max_stamina = cfg["stamina"] + permanent_effective_level("vitality_level") * 3 + permanent_effective_level("stamina_level") * 6 + evo.get("stamina", 0) * 5
        if self.character == "Sans":
            # Sans sempre possui exatamente 1 HP. Investimentos em HP viram reserva extra de esquiva.
            self.max_hp = 1
            self.hp = 1
            self.max_stamina += evo.get("hp", 0) * 3
        elif self.character == "Glonk 100% Power":
            # A piada do personagem e ter exatamente 1 HP; evolucao de HP vira Estamina.
            self.max_hp = 1
            self.hp = 1
            self.max_stamina += evo.get("hp", 0) * 2
        self.stamina = self.max_stamina
        self.stamina_regen = cfg["regen"] * (1 + 0.02 * permanent_effective_level("regen_level")) * (1 + 0.015 * evo.get("stamina", 0))
        self.stamina_regen_delay = 0.0

        self.base_damage = cfg["damage"] * (1 + 0.025 * permanent_effective_level("damage_level")) * (1 + 0.03 * evo.get("strength", 0))
        self.damage_mult = 1.0
        self.attack_cd = 0
        self.dash_cd = 0
        self.parry_cd = 0
        self.parry_time = 0
        self.dash_time = 0
        self.dash_dir = pygame.Vector2()
        self.invuln = 0
        self.shield = 0

        self.weapon = cfg["weapon"]
        self.weapon_name = cfg.get("weapon_name", "NADA")
        self.weapons = ["ESPADA", "PISTOLA", "SHOTGUN", "CAJADO", "PISTOLAS DUPLAS", "NADA", "ABACAXI BUMERANGUE", "INVESTIDA", "GOLPE EM AREA", "OSSOS / BLASTER"]
        self.domain_name = cfg["domain"]

        # Flags/valores de build. As cartas ligam estes efeitos durante a run.
        self.projectile_pierce = 0
        self.projectile_bonus = 1.0
        self.stamina_on_hit = 1.0
        self.execute_bonus = 0
        self.crit_chance = min(0.18, 0.005 * permanent_effective_level("crit_level")) + self.passive_static.get("crit",0.0)
        self.crit_damage_mult = self.passive_static.get("crit_mult",1.5)
        self.drop_bonus = 0.01 * permanent_effective_level("orb_level")
