    def check_synergies(self):
        for req, name, desc in UPGRADE_SYNERGIES:
            if req.issubset(self.owned_upgrades) and name not in self.synergies:
                self.synergies.add(name)
                AUDIO.play("synergy", 1.0)
                self.synergy_name = name
                self.synergy_timer = 3.2
                self.damage_texts.append(DamageText("SINERGIA!", pygame.Vector2(self.player.pos), YELLOW, 1.2))
                if name == "GEOMETRIA IMPOSSIVEL":
                    self.player.ana_miniana_speed *= 1.20
                    self.player.ana_reality_error = max(self.player.ana_reality_error, 0.30)
                    self.player.ana_blast_mult *= 1.15
                elif name == "EXECUCAO BALISTICA":
                    self.player.ycaro_extra_pellets += 1
                elif name == "PACTO DE SOBREVIVENCIA":
                    self.player.stamina_regen *= 1.15
                elif name == "COLHEITA DE GUERRA":
                    self.player.pedro_damage_mult *= 1.15
                elif name == "MARCHA DOS AMIGOS":
                    self.player.ruan_servant_damage_mult *= 1.15
                elif name == "REALIDADE RECURSIVA":
                    self.player.ana_miniana_speed *= 1.25
                elif name == "ARTILHARIA DE BOLSO":
                    self.player.hank_charge_required=max(0.85,self.player.hank_charge_required-0.12)
                elif name == "FUNERAL EM RAJADA":
                    self.player.kayk_procession_bonus=True
                elif name == "COZINHA MALEVOLENTE":
                    self.player.sukuna_fuuga_synergy=True

    def update_joystick(self, pos):
        rect = self.buttons.get("joystick")
        if rect is None:
            self.joystick_vector.update(0, 0)
            return
        center = pygame.Vector2(rect.center)
        delta = pygame.Vector2(pos) - center
        radius = max(1.0, min(rect.w, rect.h) * 0.46)
        length = delta.length()
        if length < radius * 0.14:
            self.joystick_vector.update(0, 0)
        elif length > 0:
            self.joystick_vector = delta / max(radius, length)

    def uses_aim_stick(self):
        # No Dominio do Hank o canhao vira facas de curtissimo alcance: o analogico de mira
        # vira um botao simples para combinar com o kit corpo a corpo e reduzir custo de UI.
        if self.player.character == HANK_KEY and self.domain_active:
            return False
        return self.player.character in ("Kayk", "Ycaro", "Pedro", "Vasco", LIRA_KEY, HANK_KEY, "Vinicius 13", "Sans", "Atlas")

    def update_aim_stick(self, pos):
        rect = self.buttons.get("attack")
        if rect is None:
            return
        center = pygame.Vector2(rect.center)
        delta = pygame.Vector2(pos) - center
        radius = max(1.0, min(rect.w, rect.h) * 0.46)
        length = delta.length()
        if length >= radius * 0.10:
            self.aim_vector = delta / max(radius, length)
            if self.aim_vector.length_squared() > 1.0:
                self.aim_vector = self.aim_vector.normalize()

    def attack_direction(self):
        if self.uses_aim_stick() and self.aim_active and self.aim_vector.length_squared() > 0.01:
            return self.aim_vector.normalize()
        f = pygame.Vector2(self.player.facing)
        return f.normalize() if f.length_squared() else pygame.Vector2(1,0)

    def handle_touch_motion(self, pos, finger_id=None):
        if self.state != "playing":
            return
        if finger_id is not None:
            if self.joystick_finger == finger_id:
                self.update_joystick(pos)
            if self.aim_finger == finger_id:
                self.update_aim_stick(pos)
            if self.active_fingers.get(finger_id)=="domain_hold" and self.player.character==REGULAR_DUDE_KEY:
                center=pygame.Vector2(self.buttons["domain"].center); d=pygame.Vector2(pos)-center
                if d.length_squared()>S(8)**2:
                    self.player.regular_ult_aim=d.normalize()
        else:
            if self.joystick_mouse_active:
                self.update_joystick(pos)
            if self.aim_mouse_active:
                self.update_aim_stick(pos)
            if self.domain_held and self.player.character==REGULAR_DUDE_KEY:
                center=pygame.Vector2(self.buttons["domain"].center); d=pygame.Vector2(pos)-center
                if d.length_squared()>S(8)**2:
                    self.player.regular_ult_aim=d.normalize()

    def handle_touch_down(self, pos, finger_id=None):
        if self.state == "playing" and (getattr(self, "mahoraga_cutscene_active", False) or getattr(self, "sukuna_cutscene_active", False)):
            return
        if self.state == "playing":
            if getattr(self,"sukuna_fuuga_aiming",False) and S(165)<=pos[1]<=H-S(335):
                self.set_sukuna_ult_target(pos); return
            if self.game_mode=="arena_survival" and self.arena_reward_cards:
                for r,card in self.arena_reward_rects:
                    if r.collidepoint(pos): self.pick_arena_reward(card); return
            if self.buttons["pause"].collidepoint(pos):
                self.pause_game()
                return
            if self.player.character==KIRA_KEY:
                if self.kira_buttons.get("detonate",pygame.Rect(0,0,0,0)).collidepoint(pos):
                    self.player.kira_detonate(self); return
                if self.kira_buttons.get("sha",pygame.Rect(0,0,0,0)).collidepoint(pos):
                    self.player.kira_deploy_sha(self); return
            if self.mode == "afk":
                if self.afk_buttons["DUMMY"].collidepoint(pos):
                    self.spawn_training_dummy()
                    return
                if self.afk_buttons["INIMIGO"].collidepoint(pos):
                    self.spawn_afk_enemy()
                    return
                if self.afk_buttons["BOSS"].collidepoint(pos):
                    self.spawn_afk_boss()
                    return
                if self.afk_buttons["TIRO"].collidepoint(pos):
                    self.afk_test_shot()
                    return
                if self.afk_buttons["DOM"].collidepoint(pos):
                    self.domain_charge = 100
                    self.player.hp = self.player.max_hp
                    self.player.stamina = self.player.max_stamina
                    self.damage_texts.append(DamageText("DOMINIO 100%", pygame.Vector2(self.player.pos), PURPLE))
                    return
                if self.afk_buttons["UP"].collidepoint(pos):
                    self.open_upgrade()
                    return
            if self.buttons["joystick"].collidepoint(pos):
                self.update_joystick(pos)
                if finger_id is not None:
                    self.joystick_finger = finger_id
                    self.active_fingers[finger_id] = "joystick"
                else:
                    self.joystick_mouse_active = True
                return
            if self.buttons["attack"].collidepoint(pos):
                if self.uses_aim_stick():
                    self.aim_active = True
                    self.attack_held = True
                    self.update_aim_stick(pos)
                    if finger_id is not None:
                        self.aim_finger = finger_id
                        self.active_fingers[finger_id] = "aim"
                    else:
                        self.aim_mouse_active = True
                    # Hank mira enquanto segura: o canhao so dispara quando o jogador solta o joystick de mira.
                    if self.player.character != HANK_KEY:
                        self.player.attack(self)
                else:
                    self.attack_held = True
                    if finger_id is not None: self.active_fingers[finger_id] = "attack"
                    if self.player.character == "Potential Man":
                        self.player.potential_hold_timer=0.0; self.player.potential_hold_triggered=False
                    elif self.player.uses_special_attack_hold():
                        if self.player.character==RIP_INDRA_KEY: self.player.rip_hold_time=0.0
                        else: self.player.hisoka_hold_time=0.0
                    elif self.player.has_divine_attack_hold():
                        self.player.divine_attack_hold=0.0; self.player.divine_attack_triggered=False
                    else: self.player.attack(self)
            elif self.buttons["dash"].collidepoint(pos):
                if self.player.character=="Atlas" or self.player.divine_ruan or self.player.divine_kayk or self.player.divine_pedro:
                    self.dash_held=True; self.player.divine_dash_hold=0.0; self.player.divine_dash_triggered=False
                    if finger_id is not None: self.active_fingers[finger_id]="dash_hold"
                else:
                    if finger_id is not None: self.active_fingers[finger_id]="action"
                    self.player.dash(self,self.get_move_dir())
            elif self.control_rect("parry").collidepoint(pos):
                if self.player.character == "Sans":
                    if self.bad_time_active: self.player.use_sans_soul(self)
                    else: self.player.fire_sans_blaster(self,auto=False)
                elif self.player.character == MAHORAGA_MODULE_KEY:
                    self.player.start_mahoraga_adapt(self)
                elif self.player.divine_kevyn:
                    self.parry_held=True; self.player.divine_parry_hold=0.0; self.player.divine_parry_triggered=False
                    if finger_id is not None: self.active_fingers[finger_id]="parry_hold"
                else: self.player.parry(self)
            elif self.buttons["domain"].collidepoint(pos):
                if self.player.character == KIRA_KEY:
                    self.player.kira_arm_or_trigger_bites(self); return
                if self.player.character == "Vinicius 13":
                    self.domain_held=True; self.player.vinicius_ult_hold=0.0; self.player.vinicius_ult_triggered=False
                    if finger_id is not None: self.active_fingers[finger_id]="domain_hold"
                elif self.player.character == REGULAR_DUDE_KEY:
                    if self.domain_charge>=100 and not self.domain_active:
                        self.domain_held=True; self.player.regular_ult_hold=0.0; self.player.regular_ult_active=True; self.player.regular_ult_aim=pygame.Vector2(self.player.facing) if self.player.facing.length_squared() else pygame.Vector2(1,0)
                        if finger_id is not None: self.active_fingers[finger_id]="domain_hold"
                    else:
                        self.damage_texts.append(DamageText("SOCO SERIO AINDA NAO ESTA PRONTO",pygame.Vector2(self.player.pos),GRAY,0.65))
                elif self.player.divine_kevyn:
                    self.domain_held=True; self.player.divine_domain_hold=0.0; self.player.divine_domain_triggered=False
                    if finger_id is not None: self.active_fingers[finger_id]="domain_hold"
                elif self.player.character == HANK_KEY:
                    self.domain_held=True; self.player.hank_domain_hold=0.0; self.player.hank_domain_triggered=False
                    if finger_id is not None: self.active_fingers[finger_id]="domain_hold"
                elif self.player.character == SUKUNA_KEY:
                    self.domain_held=True; self.player.sukuna_domain_hold=0.0; self.player.sukuna_domain_triggered=False
                    if finger_id is not None: self.active_fingers[finger_id]="domain_hold"
                else: self.player.expand_domain(self)

    def handle_touch_up(self, pos, finger_id=None):
        if self.state == "playing" and (getattr(self, "mahoraga_cutscene_active", False) or getattr(self, "sukuna_cutscene_active", False)):
            return
        if finger_id is not None:
            action = self.active_fingers.pop(finger_id, None)
            if action in self.move_touch:
                self.move_touch[action] = False
            elif action == "joystick":
                if self.joystick_finger == finger_id:
                    self.joystick_finger = None
                    self.joystick_vector.update(0, 0)
            elif action == "aim":
                # Hank confirma a direcao no instante em que o dedo e solto.
                if self.player.character == HANK_KEY:
                    if self.aim_vector.length_squared() > 0.01:
                        self.player.facing = self.aim_vector.normalize()
                    self.player.attack(self)
                self.aim_finger = None
                self.aim_active = False
                self.attack_held = False
            elif action == "attack":
                if self.player.character == "Potential Man" and not self.player.potential_hold_triggered: self.player.attack(self)
                elif self.player.uses_special_attack_hold(): self.player.finish_special_attack_hold(self)
                elif self.player.has_divine_attack_hold(): self.player.finish_attack_hold(self)
                self.player.potential_hold_timer=0.0; self.player.potential_hold_triggered=False; self.attack_held=False
            elif action == "dash_hold":
                self.dash_held=False; self.player.finish_dash_hold(self)
            elif action == "parry_hold":
                self.parry_held=False; self.player.finish_parry_hold(self)
            elif action == "domain_hold":
                self.domain_held=False; self.player.finish_domain_hold(self)
        else:
            # mouse/desktop: não há ID de dedo
            for d in self.move_touch:
                self.move_touch[d] = False
            self.joystick_mouse_active = False
            self.joystick_vector.update(0, 0)
            # No desktop, Hank tambem dispara somente ao soltar o controle de mira.
            if self.attack_held and self.player.character == HANK_KEY:
                if self.aim_vector.length_squared() > 0.01:
                    self.player.facing = self.aim_vector.normalize()
                self.player.attack(self)
            self.aim_mouse_active = False
            self.aim_active = False
            self.aim_finger = None
            if self.attack_held and self.player.character != HANK_KEY:
                if self.player.character == "Potential Man" and not self.player.potential_hold_triggered: self.player.attack(self)
                elif self.player.uses_special_attack_hold(): self.player.finish_special_attack_hold(self)
                elif self.player.has_divine_attack_hold(): self.player.finish_attack_hold(self)
            if self.dash_held: self.dash_held=False; self.player.finish_dash_hold(self)
            if self.parry_held: self.parry_held=False; self.player.finish_parry_hold(self)
            if self.domain_held: self.domain_held=False; self.player.finish_domain_hold(self)
            self.player.potential_hold_timer=0.0; self.player.potential_hold_triggered=False; self.attack_held=False

    def get_move_dir(self):
        k = pygame.key.get_pressed()
        x = (1 if k[pygame.K_d] or k[pygame.K_RIGHT] else 0) - (1 if k[pygame.K_a] or k[pygame.K_LEFT] else 0)
        y = (1 if k[pygame.K_s] or k[pygame.K_DOWN] else 0) - (1 if k[pygame.K_w] or k[pygame.K_UP] else 0)
        x += (1 if self.move_touch["right"] else 0) - (1 if self.move_touch["left"] else 0)
        y += (1 if self.move_touch["down"] else 0) - (1 if self.move_touch["up"] else 0)
        keyboard_touch = pygame.Vector2(x, y)
        move = keyboard_touch + self.joystick_vector
        if move.length_squared() > 1.0:
            move = move.normalize()
        return move

    def apply_dev_room_start_stats(self):
        """Aplica overrides DEV uma unica vez por valor a cada inimigo que entra na sala."""
        if not SAVE.get("cheat_dev",False):
            return
        hp_raw=SAVE.get("cheat_enemy_start_hp",-1)
        try: hp_override=int(hp_raw)
        except Exception: hp_override=-1
        sta_raw=SAVE.get("cheat_enemy_start_stamina",-1)
        try: sta_override=int(sta_raw)
        except Exception: sta_override=-1
        targets=list(getattr(self,"enemies",[]) or [])
        maho=getattr(self,"mahoraga",None)
        if maho is not None and not getattr(maho,"dead",True) and maho not in targets:
            targets.append(maho)
        for enemy in targets:
            if enemy is None or getattr(enemy,"dead",False):
                continue
            if hp_override>=0 and getattr(enemy,"_dev_hp_override_value",None)!=hp_override:
                try:
                    max_hp=float(getattr(enemy,"max_hp",hp_override))
                    enemy.hp=max(0.0,min(float(hp_override),max_hp))
                    enemy._dev_hp_override_value=hp_override
                except Exception:
                    pass
            if sta_override>=0 and hasattr(enemy,"stamina") and getattr(enemy,"_dev_sta_override_value",None)!=sta_override:
                try:
                    max_sta=float(getattr(enemy,"max_stamina",sta_override))
                    enemy.stamina=max(0.0,min(float(sta_override),max_sta))
                    enemy._dev_sta_override_value=sta_override
                    if isinstance(enemy,SansTrialBoss):
                        if enemy.stamina<=0 and not enemy.desperation_active and not enemy.exhausted:
                            enemy._start_desperation(self)
                        elif enemy.stamina<=enemy.max_stamina*0.50 and not enemy.final_judgement:
                            enemy.final_judgement=True; enemy.relocate_cd=2.5; enemy.soul_cd=1.35
                            self.damage_texts.append(DamageText("A VERDADEIRA BATALHA COMECA.",pygame.Vector2(enemy.pos),RED,1.3))
                except Exception:
                    pass

    def update_playing(self, dt):
        if getattr(self, "mahoraga_cutscene_active", False):
            self.update_mahoraga_cutscene(dt)
            return
        if getattr(self, "sukuna_cutscene_active", False):
            self.update_sukuna_cutscene(dt)
            return
        self.check_beta_character_unlock_quests()
        self.apply_dev_room_start_stats()
        if getattr(self, "sukuna_destruction_active", False):
            self.update_sukuna_destruction(dt)
        # EXTINCAO: trava o maior HP possivel no menor valor ja atingido.
        # Isso bloqueia ate futuras curas que eventualmente tentem alterar HP diretamente.
        if self.game_mode == "extinction":
            if self.extinction_hp_cap is None:
                self.extinction_hp_cap = self.player.hp
            self.player.hp = min(self.player.hp, self.extinction_hp_cap)
        self.time += dt
        self.mahoraga_ai_messages=[[m,t-dt,c] for m,t,c in self.mahoraga_ai_messages if t-dt>0]
        self.domain_message_timer = max(0, self.domain_message_timer - dt)
        self.boss_domain_message_timer = max(0, self.boss_domain_message_timer - dt)
        self.clash_result_timer = max(0, self.clash_result_timer - dt)
        self.unlock_notice_timer = max(0, self.unlock_notice_timer - dt)
        self.wave_banner = max(0, self.wave_banner - dt)
        self.glonk_event_timer = max(0.0, self.glonk_event_timer-dt)
        self.glonk_boss_intro_timer = max(0.0, self.glonk_boss_intro_timer-dt)
        self.glonk_music_cut_timer = max(0.0, self.glonk_music_cut_timer-dt)
        self.slash_fx = max(0, self.slash_fx - dt)
        self.flash_screen = max(0, self.flash_screen - dt)
        self.father_wave_fx_timer = max(0, self.father_wave_fx_timer - dt)
        self.achievement_timer = max(0, self.achievement_timer - dt)
        self.synergy_timer = max(0, self.synergy_timer - dt)
        self.enemy_slow_timer = max(0, self.enemy_slow_timer - dt)
        self.orb_chain_timer = max(0, self.orb_chain_timer - dt)
        self.kevyn_sword_kill_timer = max(0, self.kevyn_sword_kill_timer - dt)
        if self.orb_chain_timer <= 0:
            self.orb_chain_count = 0
        if self.kevyn_sword_kill_timer <= 0:
            self.kevyn_sword_kills = 0
        if self.domain_active and self.player.character==MAHORAGA_MODULE_KEY and self.domain_name=="SANTUARIO DA ADAPTACAO":
            # Mesmo movimento visual da roda gigante do domínio do boss.
            self.player.mahoraga_domain_visual_angle=(self.player.mahoraga_domain_visual_angle+dt*0.65)%math.tau
            self.player.mahoraga_domain_wheel_cd-=dt
            spins=0
            while self.player.mahoraga_domain_wheel_cd<=0 and spins<2:
                self.player.mahoraga_domain_wheel_cd+=1.0
                self.player.mahoraga_domain_adapt_pct=min(80.0,self.player.mahoraga_domain_adapt_pct+10.0)
                self.player.mahoraga_wheel_fx=0.90
                AUDIO.play_external_sfx("mahoraga_player_wheel",0.95,0)
                self.damage_texts.append(DamageText(f"RODA +10%  |  {int(self.player.mahoraga_domain_adapt_pct)}%",pygame.Vector2(self.player.pos),YELLOW,0.65))
                spins+=1
        if self.domain_active:
            # V11: a area permanece FIXA onde foi ativada.
            self.domain_timer -= dt
            if self.domain_timer <= 0:
                # Atlas: resolve o arremesso FINAL antes de desligar o dominio.
                if self.player.character=="Atlas" and self.domain_name=="REFUTA ISSO NEWTON!!!":
                    old_kind=self.current_damage_kind; self.current_damage_kind="atlas_domain_final"
                    targets=set(getattr(self.player,"atlas_domain_targets",set()))
                    for e in list(self.enemies):
                        if e.dead or e.id not in targets: continue
                        dv=e.pos-self.player.pos
                        if dv.length_squared()<=0.01: dv=vec_from_angle(random.random()*math.tau)
                        d=dv.normalize(); boss=isinstance(e,Boss)
                        if boss:
                            e.pos += d*S(185); dmg=self.player.base_damage*1.10
                        else:
                            # leva ate a parede REAL da arena cheia (0..W, 0..H)
                            tx=(W-e.radius if d.x>=0 else e.radius); ty=(H-e.radius if d.y>=0 else e.radius)
                            sx=abs((tx-e.pos.x)/d.x) if abs(d.x)>1e-5 else 1e9
                            sy=abs((ty-e.pos.y)/d.y) if abs(d.y)>1e-5 else 1e9
                            e.pos += d*max(0,min(sx,sy)); dmg=self.player.base_damage*2.6
                        e.damage(dmg,self,self.player.pos,minimal_fx=True)
                    self.current_damage_kind=old_kind
                    self.spawn_particles(self.player.pos,(155,45,235),55); self.shake=max(self.shake,S(24))
                    self.damage_texts.append(DamageText("REFUTA ISSO NEWTON!!!",pygame.Vector2(self.player.pos),(190,100,255),1.1))
                    self.player.atlas_domain_targets=set(); self.player.atlas_domain_elapsed=0.0
                self.domain_active = False
                self.domain_timer = 0
                if self.bad_time_active:
                    self.bad_time_active=False
                    self.sans_bones=[]
                    self.damage_texts.append(DamageText("BAD TIME ENCERRADA",pygame.Vector2(self.player.pos),GRAY))
                else:
                    self.damage_texts.append(DamageText("DOMINIO ENCERRADO", pygame.Vector2(self.player.pos), GRAY))
                self.hank_domain_active = False
                self.hank_domain_trapped_ids = set()
                self.player.hank_cannon_planted = False
                self.hank_cannon_pos = None
                if self.player.character==LIRA_KEY: self.player.lira_end_domain(self)
                if self.player.character==MAHORAGA_MODULE_KEY:
                    self.player.mahoraga_domain_adapt_pct=0.0
                    self.player.mahoraga_domain_wheel_cd=1.0
                    self.player.mahoraga_domain_visual_angle=0.0
                    self.player.mahoraga_wheel_fx=0.0
                    self.damage_texts.append(DamageText(f"ADAPTACAO RETORNA A {int(self.player.mahoraga_adaptation_pct)}%",pygame.Vector2(self.player.pos),YELLOW,0.8))
                # Guardiao do Ruan so existe enquanto o Dominio estiver ativo.
                if self.ruan_guardian is not None:
                    self.ruan_guardian.dead = True
                    self.ruan_guardian = None

        # SANTUARIO MALEVOLENTE: barreira aberta, cobre a arena inteira.
        # 5 de dano-base a cada 0,1s; nao crita. Dedos e bonus gerais de dano ainda afetam o Sukuna.
        if self.domain_active and self.player.character == SUKUNA_KEY:
            self.sukuna_domain_tick_cd -= dt
            ticks=0
            while self.sukuna_domain_tick_cd <= 0.0 and ticks < 3:
                self.sukuna_domain_tick_cd += 0.10
                old_kind=self.current_damage_kind; self.current_damage_kind="sukuna_domain"
                for e in list(self.enemies):
                    if e.dead or isinstance(e, GlonkEnemy):
                        continue
                    dmg=5.0*(1.25 if self.player.sukuna_king_curses else 1.0)*self.player.effective_damage_mult(self,e,"sukuna_domain",e.pos.distance_to(self.player.pos))
                    e.damage(dmg,self,self.player.pos,minimal_fx=True)
                maho=getattr(self,"mahoraga",None)
                if self.game_mode=="mahoraga_trial" and maho is not None and not maho.dead:
                    dmg=5.0*(1.25 if self.player.sukuna_king_curses else 1.0)*self.player.effective_damage_mult(self,None,"sukuna_domain",maho.pos.distance_to(self.player.pos))
                    maho.take_damage(dmg,self,self.player.pos,from_player=True)
                self.current_damage_kind=old_kind
                ticks+=1

        # Pequenas orbes de vida aparecem naturalmente, EXCETO no EXTINCAO.
        self.ambient_heal_orb_timer -= dt
        if self.ambient_heal_orb_timer <= 0:
            if self.game_mode != "extinction" and sum(1 for d in self.drops if d.kind == "ambient_heal") < 4:
                px = random.uniform(S(90), W-S(90))
                py = random.uniform(S(235), H-S(385))
                self.drops.append(Drop((px, py), "ambient_heal"))
            self.ambient_heal_orb_timer = random.uniform(6.0, 11.0)

        if self.combo_timer > 0:
            self.combo_timer -= dt
            if self.combo_timer <= 0:
                self.combo = 0

        # Dominio do Kayk: almas atacam automaticamente sem criar dezenas de projeteis.
        # Dano direto periodico deixa a expansao muito mais leve no Android.
        if self.domain_active and self.player.character == "Kayk" and self.player.in_domain(self):
            self.kayk_domain_fire_cd -= dt
            if self.kayk_domain_fire_cd <= 0:
                targets = [e for e in self.enemies if not e.dead and not isinstance(e, GlonkEnemy) and self.is_in_domain(e.pos)]
                maho=getattr(self,"mahoraga",None)
                if self.game_mode=="mahoraga_trial" and maho is not None and not maho.dead and self.is_in_domain(maho.pos): targets.append(maho)
                targets.sort(key=lambda e: e.pos.distance_to(self.player.pos))
                max_targets = 3 if self.player.kayk_thousand_souls else 2
                old_kind = self.current_damage_kind
                self.current_damage_kind = "soul_shot"
                for target in targets[:max_targets]:
                    dmg_mult = 0.88 if self.player.kayk_thousand_souls else 0.60
                    damage = self.player.base_damage * dmg_mult * self.player.effective_damage_mult(self, None if isinstance(target,MahoragaSummon) else target, "soul_shot", target.pos.distance_to(self.player.pos))
                    if isinstance(target,MahoragaSummon): target.take_damage(damage,self,self.player.pos,from_player=True)
                    else: target.damage(damage, self, self.player.pos)
                    self.damage_texts.append(DamageText("ALMA!", pygame.Vector2(target.pos), PURPLE))
                self.current_damage_kind = old_kind
                base_cd = 0.28 if self.player.kayk_armed_procession else 0.42
                if self.player.domain_evolution:
                    base_cd *= 0.90
                self.kayk_domain_fire_cd = base_cd

        self.sans_teleport_blackout = max(0.0, getattr(self,"sans_teleport_blackout",0.0)-dt)
        move_dir = self.get_move_dir()
        self.player.update(dt, self, move_dir)
        self.sin_sloth_slow=False
        if self.state != "playing":
            return
        if self.bad_time_active:
            self.update_bad_time(dt)
        self.update_sans_blaster_plants(dt)
        self.sans_bones=[b for b in self.sans_bones if b.update(dt,self)]
        for fx in self.sans_blaster_fx:
            fx["timer"]-=dt
        self.sans_blaster_fx=[fx for fx in self.sans_blaster_fx if fx["timer"]>0]
        # V15.4 SANS FIX: segundo analogico funciona como gatilho continuo.
        # Enquanto o dedo estiver segurando/arrastando a MIRA, attack() e consultado a cada frame;
        # o cooldown interno do Sans controla a cadencia e gera novos ossos automaticamente.
        if (self.attack_held and self.player.character == "Sans" and self.aim_active
                and self.aim_vector.length_squared() > 0.01):
            self.player.attack(self)
        elif self.attack_held and self.player.character not in ("Sans", "Potential Man", HANK_KEY, RIP_INDRA_KEY, HISOKA_KEY) and not self.player.has_divine_attack_hold():
            self.player.attack(self)

        # Atualiza invocacoes da Ana e armas Divinas persistentes.
        self.summons = [summon for summon in self.summons if summon.update(dt, self)]
        self.orbital_anas=[a for a in self.orbital_anas if a.update(dt,self)]
        self.planted_pineapples=[p for p in self.planted_pineapples if p.update(dt,self)]
        if self.divine_burst_fx:
            self.divine_burst_fx["timer"]-=dt
            if self.divine_burst_fx["timer"]<=0: self.divine_burst_fx=None

        # Amigos do Ruan atacam antes dos inimigos; depois podem ser escolhidos como alvo.
        self.servants = [serv for serv in self.servants if serv.update(dt, self)]
        if self.ruan_guardian is not None and self.ruan_guardian.dead:
            self.ruan_guardian = None
        # Vinicius 13: torretas, muros e pedras do Canhao Anti-Tita.
        self.vinicius_turrets=[x for x in self.vinicius_turrets if x.update(dt,self)]
        self.vinicius_walls=[x for x in self.vinicius_walls if x.update(dt,self)]
        self.vinicius_rocks=[x for x in self.vinicius_rocks if x.update(dt,self)]

        # Caes Divinos e Mahoraga. Permanecem entre ondas enquanto estiverem vivos.
        self.potential_summons=[x for x in self.potential_summons if x.update(dt,self)]
        if self.game_mode=="mahoraga_trial" and self.mahoraga is not None and not self.mahoraga.dead and self.mahoraga_final_countdown>0 and self.state=="playing":
            self.mahoraga_final_countdown=max(0.0,self.mahoraga_final_countdown-dt)
            if self.mahoraga_final_countdown<=0:
                self.damage_texts.append(DamageText("99% — TEMPO ESGOTADO",pygame.Vector2(self.player.pos),RED,1.2))
                self.player.hp=0
                self.end_run()
                return
        if self.mahoraga is not None and self.mahoraga.dead:
            if self.game_mode=="mahoraga_trial" and self.state=="playing":
                self.complete_mode("MAHORAGA EXORCIZADO",f"ADAPTACAO FINAL: {getattr(self.mahoraga,'adaptation_pct',0)}%")
                return
            self.mahoraga=None
            self.mahoraga_hostile_to_dogs=False

        slow_factor = 0.45 if self.enemy_slow_timer > 0 else 1.0
        for e in self.enemies:
            e.update(dt * slow_factor, self)
        self.enemies = [e for e in self.enemies if not e.dead]
        if self.game_mode=="sans_trial":
            try:
                self.sans_boss_bones=[b for b in self.sans_boss_bones if b.update(dt,self)]
                self.sans_boss_blasters=[b for b in self.sans_boss_blasters if b.update(dt,self)]
                if self.sans_trial_victory_pending and self.state=="playing":
                    self.sans_trial_victory_pending=False
                    self.complete_mode("SANS DERROTADO","A VERDADEIRA BATALHA TERMINOU")
                    return
            except Exception as exc:
                _write_sans_trial_crash("hazard_update",exc)
                self.sans_trial_error=repr(exc)
                self.sans_boss_bones=[]; self.sans_boss_blasters=[]
                self.damage_texts.append(DamageText("ERRO DE PADRAO IGNORADO",pygame.Vector2(self.player.pos),RED,1.0))
        # ALMA da BAD TIME: o deslocamento forcado acontece DEPOIS da IA inimiga,
        # para a IA nao cancelar o arremesso no mesmo frame.
        self.update_sans_soul_throws(dt)
        self.sans_soul_wall_bones=[b for b in self.sans_soul_wall_bones if b.update(dt,self)]
        self.enemies = [e for e in self.enemies if not e.dead]
        if self.game_mode=="evolution" and self.evolution_traits.count("regeneration")>0:
            regen=0.0035*self.evolution_traits.count("regeneration")*dt
            for e in self.enemies:
                e.hp=min(e.max_hp,e.hp+e.max_hp*regen)

        # Dominios sao moveis: se os circulos se encostarem DEPOIS de ativados,
        # o Clash ainda comeca. Nao depende apenas do instante da ativacao.
        if self.domain_active and not self.domain_clash_active and self.player.character not in ("Sans", "Potential Man"):
            for boss in self.enemies:
                if isinstance(boss, Boss) and boss.domain_active and self.domains_overlap(boss):
                    self.start_domain_clash(boss)
                    break
        self.update_domain_clash(dt)

        # Explosoes atrasadas (Dash Fantasma etc.)
        remaining_blasts = []
        for b in self.delayed_blasts:
            b["timer"] -= dt
            if b["timer"] <= 0:
                self.spawn_particles(b["pos"], b["color"], 22)
                old = self.current_damage_kind
                self.current_damage_kind = "ghost_dash"
                for e in list(self.enemies):
                    if not e.dead and e.pos.distance_to(b["pos"]) <= b["radius"]:
                        e.damage(b["damage"] * self.player.effective_damage_mult(self, e), self, b["pos"])
                self.current_damage_kind = old
                self.shake = max(self.shake, S(12))
            else:
                remaining_blasts.append(b)
        self.delayed_blasts = remaining_blasts

        for fx in getattr(self,"hank_explosions",[]): fx["timer"]-=dt
        self.hank_explosions=[fx for fx in getattr(self,"hank_explosions",[]) if fx["timer"]>0]

        if getattr(self, "hank_artillery_queue", None):
            alive_marks = []
            for mark in self.hank_artillery_queue:
                mark["timer"] -= dt
                if mark["timer"] <= 0 and not mark.get("done", False):
                    mark["done"] = True
                    self.trigger_hank_explosion(mark["pos"],self.player.base_damage*2.8,mark["radius"],artillery=True)
                if mark["timer"] > -0.15:
                    alive_marks.append(mark)
            self.hank_artillery_queue = alive_marks

        new_projectiles = []
        for pr in self.projectiles:
            # Tempo de Caca: abacaxi teleguiado durante a ida.
            if isinstance(pr,BoomerangProjectile) and getattr(pr,"divine_pedro",False) and not pr.returning:
                targets=[e for e in self.enemies if not e.dead and e.id not in pr.hit_ids]
                if targets:
                    target=min(targets,key=lambda e:e.pos.distance_to(pr.pos)); desired=target.pos-pr.pos
                    if desired.length_squared()>0: pr.vel=pr.vel.lerp(desired.normalize()*pr.base_speed,min(1.0,7.5*dt))
            if isinstance(pr,BoomerangProjectile) and getattr(pr,"predator",False) and not pr.returning and pr.hit_ids:
                targets=[e for e in self.enemies if not e.dead and e.id not in pr.hit_ids]
                if targets:
                    target=min(targets,key=lambda e:e.pos.distance_to(pr.pos)); desired=target.pos-pr.pos
                    if desired.length_squared()>0: pr.vel=pr.vel.lerp(desired.normalize()*pr.base_speed,min(1.0,8.0*dt))
            if pr.owner=="player" and getattr(pr,"kind","")=="sans_bone" and self.player.sans_stubborn_bone:
                targets=[e for e in self.enemies if not e.dead and e.id not in pr.hit_ids]
                if targets:
                    target=min(targets,key=lambda e:e.pos.distance_to(pr.pos)); desired=target.pos-pr.pos
                    if desired.length_squared()>0: pr.vel=pr.vel.lerp(desired.normalize()*max(S(520),pr.vel.length()),min(1.0,2.6*dt))

            if pr.owner=="player" and getattr(pr,"kind","")=="hisoka_domain_card":
                target=getattr(pr,"hisoka_target",None)
                if target is not None and not getattr(target,"dead",True):
                    desired=target.pos-pr.pos
                    if desired.length_squared()>0:
                        speed=max(S(760),pr.vel.length()); pr.vel=pr.vel.lerp(desired.normalize()*speed,min(1.0,10.0*dt))

            # Power-up da Strikada: bola teleguiada corrige a rota para o alvo mais proximo.
            if pr.owner == "player" and getattr(pr, "kind", "") == "strikada_ball" and getattr(pr, "strikada_homing", False):
                targets = [e for e in self.enemies if not e.dead and e.id not in pr.hit_ids]
                if targets:
                    target = min(targets, key=lambda e:e.pos.distance_to(pr.pos))
                    desired = target.pos-pr.pos
                    if desired.length_squared() > 0:
                        speed = max(S(420), pr.vel.length())
                        pr.vel = pr.vel.lerp(desired.normalize()*speed, min(1.0, 5.5*dt))

            # Campo de Caca do Zumbi: pellets nascidos dentro do Dominio perseguem o alvo.
            if (pr.owner=="player" and getattr(pr,"kind","")=="shotgun" and getattr(pr,"ycaro_domain_homing",False)
                    and self.player.character=="Ycaro" and self.domain_active):
                targets=[e for e in self.enemies if not e.dead and self.is_in_domain(e.pos)]
                if targets and pr.vel.length_squared()>0:
                    target=min(targets,key=lambda e:e.pos.distance_to(pr.pos)); desired=target.pos-pr.pos
                    if desired.length_squared()>0:
                        speed=max(S(520),pr.vel.length())
                        pr.vel=pr.vel.lerp(desired.normalize()*speed,min(1.0,8.5*dt))

            # Vinicius 13: UMA correcao pequena (max 7 graus) se o tiro ja estiver passando perto do alvo.
            # Depois disso a rota fica reta; nao existe tracking/teleguiado continuo.
            if pr.owner == "player" and getattr(pr,"kind","") == "vinicius_bolt" and not getattr(pr,"vinicius_correction_used",False):
                targets=[e for e in self.enemies if not e.dead and e.id not in pr.hit_ids and e.pos.distance_to(pr.pos)<=S(520)]
                if targets and pr.vel.length_squared()>0:
                    target=min(targets,key=lambda e:e.pos.distance_to(pr.pos)); desired=target.pos-pr.pos
                    if desired.length_squared()>0:
                        cur=pr.vel.normalize(); want=desired.normalize(); angle=cur.angle_to(want)
                        if abs(angle)<=28.0:
                            turn=clamp(angle,-7.0,7.0); speed=pr.vel.length(); pr.vel=cur.rotate(turn)*speed; pr.vinicius_correction_used=True

            # Dominio da Ana: projeteis dentro da area perseguem o alvo mais proximo.
            if pr.owner == "player" and self.player.character == "Ana" and self.domain_active and self.is_in_domain(pr.pos):
                targets = [e for e in self.enemies if not e.dead and self.is_in_domain(e.pos)]
                if targets:
                    target = min(targets, key=lambda e: e.pos.distance_to(pr.pos))
                    desired = target.pos - pr.pos
                    if desired.length_squared() > 0:
                        speed = max(S(260), pr.vel.length())
                        desired = desired.normalize() * speed
                        pr.vel = pr.vel.lerp(desired, min(1.0, 7.0 * dt))
            proj_mult = slow_factor if pr.owner == "enemy" else 1.0
            if pr.owner=="enemy" and self.player.character=="Glonk" and self.player.glonk_professional_coward:
                proj_mult *= 0.75
            # Metavisao do Cadeado Azul: projeteis inimigos perdem muita velocidade dentro da area.
            if (pr.owner == "enemy" and self.player.character == "Strikada Egoísta" and self.domain_active
                    and self.is_in_domain(pr.pos)):
                proj_mult *= 0.45
            proj_dt = dt * proj_mult
            if not pr.update(proj_dt):
                if getattr(pr,"kind","")=="strikada_ball" and self.player.strikada_self_pass:
                    self.player.attack_cd=min(self.player.attack_cd,0.12)
                    self.damage_texts.append(DamageText("PASSE PRA MIM!",pygame.Vector2(self.player.pos),(125,220,255),0.45))
                if isinstance(pr,BoomerangProjectile) and pr.returned_to_player and getattr(pr,"double_crop",False) and random.random()<0.30:
                    d=self.attack_direction() if hasattr(self,"attack_direction") else self.player.facing
                    if d.length_squared()==0: d=pygame.Vector2(1,0)
                    extra=BoomerangProjectile(self.player,d,self.player.base_damage*self.player.projectile_bonus,self.player.pedro_speed_mult,self.player.pedro_range_mult,self.player.pedro_return_hit,self.player.pedro_explosive,self.player.pedro_crown)
                    extra.domain_charge_raw=0.0; extra.domain_charge_uses_left=0; new_projectiles.append(extra)
                    self.damage_texts.append(DamageText("COLHEITA DUPLA!",pygame.Vector2(self.player.pos),YELLOW,0.55))
                if isinstance(pr,BoomerangProjectile) and not pr.hit_any and getattr(pr,"industrial",False):
                    self.delayed_blasts.append({"timer":2.0,"pos":pygame.Vector2(pr.pos),"radius":S(95),"damage":self.player.base_damage*1.10,"color":YELLOW})
                    self.damage_texts.append(DamageText("ABACAXI PLANTADO",pygame.Vector2(pr.pos),YELLOW,0.55))
                if isinstance(pr, BoomerangProjectile) and pr.returned_to_player and (not pr.hit_any or getattr(pr,"divine_pedro",False)):
                    amount=4 if getattr(pr,"divine_pedro",False) else 2
                    self.player.heal(amount, self)
                    self.player.recover_stamina(amount, self)
                    self.damage_texts.append(DamageText(f"+{amount} HP / +{amount} STA", pygame.Vector2(self.player.pos), GREEN, 0.8))
                    if self.mode == "arena" and not is_beta_character(self.player.character):
                        SAVE["pineapple_refunds"] = SAVE.get("pineapple_refunds", 0) + 1
                        if SAVE["pineapple_refunds"] >= 25: self.unlock_achievement("pineapple_25")
                        save_data(SAVE)
                continue

            # Hank: ao atingir 65% do caminho ate a borda, a bala explode mesmo sem acertar alvo.
            if getattr(pr,"kind","")=="hank_shell" and hasattr(pr,"hank_max_distance"):
                range_origin=pygame.Vector2(getattr(pr,"hank_range_origin",getattr(pr,"origin",pr.pos)))
                traveled=pr.pos.distance_to(range_origin)
                if traveled >= pr.hank_max_distance:
                    d=pygame.Vector2(pr.vel)
                    if d.length_squared()>0:
                        d=d.normalize()
                        pr.pos=range_origin+d*pr.hank_max_distance
                    self.trigger_hank_explosion(pr.pos,getattr(pr,"hank_explosion_damage",pr.damage*.85)*(1.50 if getattr(pr,"hank_confirmed_target",False) else 1.0),getattr(pr,"hank_explosion_radius",S(155)),domain_charge_raw=20.0)
                    continue

            # Atlas: ao chegar a 40% da arena, comprime o campo. Se houver 2+ inimigos
            # proximos, vira uma explosao gravitacional AOE e puxa todos com mais forca.
            if getattr(pr,"kind","")=="atlas_gravity" and hasattr(pr,"atlas_max_distance"):
                origin=pygame.Vector2(getattr(pr,"origin",pr.pos)); traveled=pr.pos.distance_to(origin)
                if traveled>=pr.atlas_max_distance:
                    d=pygame.Vector2(pr.vel).normalize() if pr.vel.length_squared()>0 else pygame.Vector2(1,0)
                    pr.pos=origin+d*pr.atlas_max_distance
                    near=[e for e in self.enemies if not e.dead and e.pos.distance_to(pr.pos)<=pr.atlas_pull_radius+e.radius]
                    if near:
                        # Todo inimigo dentro da area gravitacional recebe o dano do ataque.
                        for e in near:
                            dv=pr.pos-e.pos; dd=max(1.0,dv.length())
                            mult=0.38 if isinstance(e,Boss) else 1.0
                            e.pos += dv.normalize()*min(dd*0.96,S(260))*mult
                            e.damage(pr.damage*(0.55 if isinstance(e,Boss) else 1.0),self,pr.pos,minimal_fx=True)
                        self.spawn_particles(pr.pos,(125,55,245),32); self.shake=max(self.shake,S(15))
                        if len(near)>=2:
                            self.damage_texts.append(DamageText("COLAPSO GRAVITACIONAL!",pygame.Vector2(pr.pos),(180,105,255),0.65))
                    continue

            # Hitbox das paredes: Pedro/Strikada refletem; todo o resto para na borda.
            if not projectile_arena_wall_collision(pr):
                if getattr(pr,"kind","")=="hank_shell":
                    self.trigger_hank_explosion(pr.pos,getattr(pr,"hank_explosion_damage",pr.damage*.85)*(1.50 if getattr(pr,"hank_confirmed_target",False) else 1.0),getattr(pr,"hank_explosion_radius",S(155)),domain_charge_raw=20.0)
                continue

            if pr.owner == "enemy":
                if self.player.parry_time > 0 and pr.pos.distance_to(self.player.pos) <= S(95):
                    pr.owner = "player"
                    pr.vel *= -1.35
                    pr.damage *= 2.2
                    pr.color = YELLOW
                    pr.parry_reflected = True
                    self.player.recover_stamina(10, self)
                    self.parries += 1
                    # V15: Parry nao recarrega mais Dominio; somente acertos em inimigos.
                    self.record_clash_parry()
                    AUDIO.play("parry", 0.95, 80)
                    self.damage_texts.append(DamageText("PARRY!", pygame.Vector2(self.player.pos), YELLOW))
                    self.shake = max(self.shake, S(9))
                    if "PARADOXO BALISTICO" in self.synergies:
                        self.enemy_slow_timer = max(self.enemy_slow_timer, 1.25)
                    if self.player.character == "Kevyn" and self.player.kevyn_absolute_parry:
                        self.player.kevyn_absolute_parry_ready=True
                        self.damage_texts.append(DamageText("PARRY ABSOLUTO",pygame.Vector2(self.player.pos),YELLOW,0.65))
                    if self.player.character == "Kevyn" and self.player.kevyn_time_counter:
                        old = self.current_damage_kind
                        self.current_damage_kind = "parry_slash"
                        for e in list(self.enemies):
                            if not e.dead and e.pos.distance_to(self.player.pos) <= S(180):
                                e.damage(self.player.base_damage*1.35*self.player.effective_damage_mult(self,e,"sword"), self, self.player.pos)
                        self.current_damage_kind = old
                    new_projectiles.append(pr)
                    continue

                # Amigos/guardiao do Ruan podem interceptar projeteis inimigos.
                intercepted = False
                for serv in list(self.servants):
                    if not serv.dead and pr.pos.distance_to(serv.pos) <= pr.radius + serv.radius:
                        serv.take_damage(pr.damage, self)
                        intercepted = True
                        break
                if not intercepted:
                    for summon in list(self.potential_summons):
                        if not summon.dead and pr.pos.distance_to(summon.pos) <= pr.radius + summon.radius:
                            summon.take_damage(pr.damage,self)
                            intercepted=True
                            break
                if intercepted:
                    continue

                if pr.pos.distance_to(self.player.pos) <= pr.radius + self.player.radius:
                    if self.player.dash_time <= 0:
                        if getattr(pr, "gula_devour", False):
                            self.gula_devour()
                        elif (getattr(pr,"kind","").startswith("mahoraga_") and self.game_mode=="mahoraga_trial" and self.mahoraga is not None and not self.mahoraga.dead):
                            self.mahoraga._domain_hit_player(self,pr.damage)
                        else:
                            self.player.take_damage(pr.damage, self)
                            if getattr(pr,"kind","") == "rival_vasco_bet":
                                rv = getattr(pr,"rival_vasco_owner",None)
                                if rv is not None and not getattr(rv,"dead",False):
                                    rv.rival_vasco_bet=min(100.0,rv.rival_vasco_bet+2.0)
                    continue
            else:
                hit = False
                strikada_continue = False
                maho = getattr(self, "mahoraga", None)
                if maho is not None and not maho.dead and not getattr(pr, "hit_mahoraga", False):
                    source = getattr(pr, "kind", "projectile")
                    swept = source in ("sukuna_slash","hank_shell","rip_wave") and hasattr(pr,"prev_pos")
                    maho_hit = sans_bone_projectile_hits(pr,maho.pos,maho.radius) if source=="sans_bone" else pr.pos.distance_to(maho.pos) <= pr.radius + maho.radius
                    if swept and not maho_hit:
                        maho_hit = point_segment_distance(maho.pos, pr.prev_pos, pr.pos) <= pr.radius + maho.radius + S(4)
                    if maho_hit:
                        if isinstance(maho,AdaptiveMahoragaBoss) and maho.reflect_projectile(pr,self):
                            new_projectiles.append(pr)
                            continue
                        origin = getattr(pr, "origin", self.player.pos)
                        dist = maho.pos.distance_to(origin)
                        dmg = pr.damage * self.player.effective_damage_mult(self, None, source, dist)
                        if isinstance(pr, BoomerangProjectile) and pr.returning:
                            dmg *= self.player.pedro_return_damage_mult
                        if isinstance(pr, HisokaCardProjectile) and pr.returning:
                            dmg *= 1.40 if self.player.hisoka_elastic_gum else 1.0
                        if random.random() < self.player.crit_chance:
                            dmg *= self.player.crit_damage_mult
                        charge_raw = self.projectile_domain_charge_value(pr)
                        self.current_domain_charge_raw_override = charge_raw if charge_raw > 0 else None
                        old_kind = self.current_damage_kind
                        self.current_damage_kind = source
                        maho.take_damage(dmg, self, pr.pos, from_player=True)
                        self.current_damage_kind = old_kind
                        self.current_domain_charge_raw_override = None
                        if source == "hank_shell":
                            self.trigger_hank_explosion(maho.pos,getattr(pr,"hank_explosion_damage",pr.damage*.85),getattr(pr,"hank_explosion_radius",S(155)),exclude=maho)
                        if source == "vasco_bet" and self.player.character == "Vasco":
                            self.player.vasco_bet_level = min(100.0, self.player.vasco_bet_level + 2.0)
                            if self.domain_active and self.player.vasco_bet_level >= 100.0 and self.player.vasco_jackpot_timer <= 0:
                                self.player.vasco_start_jackpot(self)
                        pr.hit_mahoraga = True
                        self.player.recover_stamina(self.player.stamina_on_hit, self)
                        self.register_combo_hit()
                        if not isinstance(pr, (BoomerangProjectile, HisokaCardProjectile)):
                            if pr.pierce > 0:
                                pr.pierce -= 1
                            else:
                                hit = True
                if hit:
                    continue
                for e in list(self.enemies):
                    if e.id in pr.hit_ids or e.dead:
                        continue
                    source = getattr(pr, "kind", "projectile")
                    swept = source in ("sukuna_slash","hank_shell","rip_wave") and hasattr(pr,"prev_pos")
                    target_hit = sans_bone_projectile_hits(pr,e.pos,e.radius) if source=="sans_bone" else pr.pos.distance_to(e.pos) <= pr.radius + e.radius
                    if swept and not target_hit:
                        target_hit = point_segment_distance(e.pos, pr.prev_pos, pr.pos) <= pr.radius + e.radius + S(4)
                    if target_hit:
                        origin = getattr(pr, "origin", self.player.pos)
                        dist = e.pos.distance_to(origin)
                        dmg = pr.damage * self.player.effective_damage_mult(self, e, source, dist)
                        if isinstance(pr, BoomerangProjectile):
                            pr.hit_any = True
                            if pr.returning:
                                dmg *= self.player.pedro_return_damage_mult
                        if isinstance(pr, HisokaCardProjectile) and pr.returning:
                            dmg *= (1.40 if self.player.hisoka_elastic_gum else 1.0) * getattr(pr,"return_mult",1.0)
                        if isinstance(pr, BoomerangProjectile) and pr.returning and pr.crown:
                            dmg *= 1.65
                            self.damage_texts.append(DamageText("COROA!", pygame.Vector2(e.pos), YELLOW))
                        passive_crit_hit = random.random() < self.player.crit_chance
                        if passive_crit_hit:
                            dmg *= self.player.crit_damage_mult
                            self.damage_texts.append(DamageText("CRIT!", pygame.Vector2(e.pos), YELLOW))
                        self.current_damage_kind = source
                        if source=="strikada_ball":
                            self.strikada_current_bounces=getattr(pr,"strikada_bounce_count",0)
                        was_alive_before_hit = not e.dead
                        charge_raw = self.projectile_domain_charge_value(pr)
                        self.current_domain_charge_raw_override = charge_raw if charge_raw > 0 else None
                        if source=="atlas_gravity":
                            pull_r=float(getattr(pr,"atlas_pull_radius",S(103)))
                            # AOE real: todos dentro do circulo de atracao tomam o dano base.
                            for other in list(self.enemies):
                                if other.dead: continue
                                dv=pygame.Vector2(pr.pos)-other.pos; dd=dv.length()
                                if dd<=pull_r + other.radius:
                                    if dd>1:
                                        strength=0.32 if isinstance(other,Boss) else 0.92
                                        other.pos += dv.normalize()*min(dd*strength,S(220)*strength)
                                    if other is not e:
                                        other.damage(dmg*(0.55 if isinstance(other,Boss) else 1.0), self, pr.pos, minimal_fx=True)
                            self.spawn_particles(pr.pos,(90,75,220),18)
                        e.damage(dmg, self, pr.pos)
                        self.current_domain_charge_raw_override = None
                        if source == "hank_shell":
                            self.trigger_hank_explosion(e.pos,getattr(pr,"hank_explosion_damage",pr.damage*.85),getattr(pr,"hank_explosion_radius",S(155)),exclude=e)
                        if passive_crit_hit and was_alive_before_hit and e.dead:
                            self.award_passive_critical_kill(e)
                        if source == "vasco_bet" and self.player.character == "Vasco":
                            old_bet = self.player.vasco_bet_level
                            self.player.vasco_bet_level = min(100.0, self.player.vasco_bet_level + 2.0)
                            gained = int(self.player.vasco_bet_level-old_bet)
                            if gained > 0:
                                self.damage_texts.append(DamageText(f"APOSTA +{gained}", pygame.Vector2(e.pos), VASCO_NEON, 0.45))
                            if self.domain_active and self.player.vasco_bet_level >= 100.0 and self.player.vasco_jackpot_timer <= 0:
                                self.player.vasco_start_jackpot(self)
                        if source=="lira_censor" and not e.dead and not isinstance(e,Boss):
                            e.apply_lira_censor(random.choice(["strength","speed","resistance","intelligence"]),0.30 if self.player.lira_thick_bar else 0.20,self)
                        if source=="hisoka_charged_card" and not e.dead:
                            e.hisoka_stun_timer=max(getattr(e,"hisoka_stun_timer",0.0),getattr(pr,"hisoka_stun",1.0))
                            self.damage_texts.append(DamageText("PARALISADO!",pygame.Vector2(e.pos),HISOKA_COLOR,0.65))
                        if source=="hisoka_spider_card" and isinstance(pr,HisokaCardProjectile) and pr.returning and not e.dead:
                            toward=self.player.pos-e.pos
                            if toward.length_squared()>0:
                                dist=toward.length(); e.pos += toward.normalize()*max(0.0,min(S(180),dist-S(95)))
                        if source=="rip_wave" and getattr(pr,"rip_explosive",False):
                            oldk=self.current_damage_kind; self.current_damage_kind="rip_wave_explosion"
                            radius=S(205)*(1.20 if "PERMISSAO DE ADMIN" in self.synergies else 1.0)
                            for other in list(self.enemies):
                                if other is not e and not other.dead and other.pos.distance_to(e.pos)<=radius:
                                    other.damage(pr.damage*0.65*self.player.effective_damage_mult(self,other,"rip_wave_explosion",other.pos.distance_to(self.player.pos)),self,e.pos,minimal_fx=True)
                            self.current_damage_kind=oldk; self.spawn_particles(e.pos,ORANGE,20); self.shake=max(self.shake,S(10))
                        if source == "dual_pistol" and getattr(pr, "forge_kayk", False):
                            e.forge_slow_timer = max(getattr(e,"forge_slow_timer",0.0), 2.8)
                            old_kind = self.current_damage_kind; self.current_damage_kind="forge_kayk_explosion"
                            for other in list(self.enemies):
                                if other is not e and not other.dead and other.pos.distance_to(e.pos) <= S(105):
                                    other.forge_slow_timer=max(getattr(other,"forge_slow_timer",0.0),1.8)
                                    other.damage(pr.damage*0.38, self, e.pos, minimal_fx=True)
                            self.current_damage_kind=old_kind
                            self.spawn_particles(e.pos,PURPLE,6)
                        killed_by_this_hit = was_alive_before_hit and e.dead
                        if source=="strikada_ball":
                            pr.strikada_bounce_count=getattr(pr,"strikada_bounce_count",0)+1
                            if killed_by_this_hit:
                                pr.strikada_kills=getattr(pr,"strikada_kills",0)+1
                                if self.player.strikada_impossible_goal and pr.strikada_kills>=3:
                                    self.player.strikada_next_infinite=True
                        double_chance = getattr(pr, "double_hit_chance", 0.0)
                        if self.player.character == "Ana" and self.domain_active and self.is_in_domain(e.pos) and self.player.domain_evolution:
                            double_chance = max(double_chance, 0.25)
                        if self.player.character == "Ana" and self.player.ana_reality_exe and self.domain_active and self.is_in_domain(e.pos):
                            double_chance = max(double_chance, 0.45)
                        if random.random() < double_chance:
                            e.damage(dmg, self, pr.pos)
                            self.damage_texts.append(DamageText("ERRO x2", pygame.Vector2(e.pos), PINK))
                        self.current_damage_kind = None
                        if source=="strikada_ball": self.strikada_current_bounces=0
                        pr.hit_ids.add(e.id)
                        self.player.recover_stamina(self.player.stamina_on_hit, self)
                        if source == "shotgun" and self.player.ycaro_aggressive_reload:
                            self.player.recover_stamina(0.75, self)
                        if source=="shotgun" and getattr(pr,"ycaro_domain_slow",False) and not e.dead:
                            e.forge_slow_timer=max(getattr(e,"forge_slow_timer",0.0),2.0)
                            if getattr(pr,"ycaro_domain_repulse",False):
                                push=pygame.Vector2(pr.vel)
                                if push.length_squared()>0:
                                    push=push.normalize()*S(78)
                                    e.pos.x=clamp(e.pos.x+push.x,S(30),W-S(30)); e.pos.y=clamp(e.pos.y+push.y,S(190),H-S(330))
                            self.damage_texts.append(DamageText("REPULSAO",pygame.Vector2(e.pos),ORANGE,0.30))
                        self.register_combo_hit()
                        if self.player.character=="Vinicius 13" and source=="vinicius_bolt" and not getattr(pr,"vinicius_child",False):
                            scrap_gain=1
                            if self.player.vinicius_premium_scrap and random.random()<0.20:
                                scrap_gain+=1
                                self.damage_texts.append(DamageText("SUCATA PREMIUM +1",pygame.Vector2(e.pos),YELLOW,0.38))
                            self.vinicius_scrap += scrap_gain
                            if self.vinicius_scrap%5==0 or scrap_gain>1:
                                self.damage_texts.append(DamageText(f"SUCATA {self.vinicius_scrap}",pygame.Vector2(self.player.pos),ORANGE,0.45))

                        # Vinicius 13: primeiro impacto espalha ate 3 tiros para alvos proximos.
                        if source == "vinicius_bolt" and not getattr(pr,"vinicius_child",False):
                            options=[o for o in self.enemies if not o.dead and o is not e and o.id not in pr.hit_ids and o.pos.distance_to(e.pos)<=S(390)]
                            options.sort(key=lambda o:o.pos.distance_to(e.pos))
                            for other in options[:3]:
                                d=other.pos-e.pos
                                if d.length_squared()>0:
                                    child=Projectile(e.pos+d.normalize()*S(18),d.normalize()*S(690),pr.damage*0.72,"player",S(7),RED,1.55,0); child.kind="vinicius_bolt"; child.origin=pygame.Vector2(e.pos); child.vinicius_child=True; child.vinicius_correction_used=True; child.hit_ids.add(e.id); child.domain_charge_raw=0.0; child.domain_charge_uses_left=0; new_projectiles.append(child)

                        # Abacaxi Explosivo do Pedro: splash sem consumir o bumerangue.
                        if isinstance(pr, BoomerangProjectile) and pr.explosive:
                            old_kind = self.current_damage_kind
                            self.current_damage_kind = "pineapple_explosion"
                            for other in list(self.enemies):
                                if other is not e and not other.dead and other.pos.distance_to(e.pos) <= S(125):
                                    other.damage(pr.damage*0.48*self.player.pedro_damage_mult, self, e.pos)
                            self.current_damage_kind = old_kind
                            self.spawn_particles(e.pos, YELLOW, 10)

                        # Parry Explosivo / Paradoxo Balistico
                        if getattr(pr, "parry_reflected", False) and self.player.explosive_parry:
                            old = self.current_damage_kind
                            self.current_damage_kind = "parry_explosion"
                            for other in list(self.enemies):
                                if not other.dead and other is not e and other.pos.distance_to(e.pos) <= S(145):
                                    other.damage(pr.damage*0.75, self, e.pos)
                            self.current_damage_kind = old

                        # Strikada Egoista: cada acerto escolhe o proximo inimigo. No Dominio,
                        # o limite deixa de existir e a bola pode revisitar alvos depois de completar o ciclo.
                        if source == "strikada_ball":
                            if getattr(pr, "strikada_kill_explosion", False) and killed_by_this_hit:
                                old_kind = self.current_damage_kind
                                self.current_damage_kind = "strikada_goal_explosion"
                                for other in list(self.enemies):
                                    if other is not e and not other.dead and other.pos.distance_to(e.pos) <= S(145):
                                        other.damage(pr.damage*0.62, self, e.pos)
                                self.current_damage_kind = old_kind
                                self.spawn_particles(e.pos, (125,220,255), 10)
                            infinite = (self.domain_active and self.player.character == "Strikada Egoísta" and self.is_in_domain(e.pos)) or getattr(pr,"strikada_force_infinite",False)
                            if not infinite:
                                pr.strikada_hits_left = max(0, getattr(pr, "strikada_hits_left", 4)-1)
                            # Quando todos os alvos ja foram tocados no Dominio, libera uma nova volta.
                            options = [o for o in self.enemies if not o.dead and o.id not in pr.hit_ids and o is not e]
                            if infinite and not options:
                                pr.hit_ids = {e.id}
                                options = [o for o in self.enemies if not o.dead and o is not e]
                            can_continue = infinite or getattr(pr, "strikada_hits_left", 0) > 0
                            if can_continue and options:
                                target = min(options, key=(lambda o:o.hp/max(1,o.max_hp)) if self.player.strikada_metavision else (lambda o:o.pos.distance_to(e.pos)))
                                d = target.pos-e.pos
                                if d.length_squared() > 0:
                                    speed = max(S(620), pr.vel.length())
                                    pr.vel = d.normalize()*speed
                                    pr.pos = pygame.Vector2(e.pos) + d.normalize()*S(18)
                                    pr.life = max(pr.life, 1.8 if not infinite else 4.0)
                                    strikada_continue = True
                                    break
                            # Sem proximo alvo ou limite encerrado: a bola desaparece neste impacto.
                            hit = True
                            break

                        # Ricochete: nasce um novo projetil em direcao a outro alvo.
                        chance = self.player.ricochet_chance
                        if chance > 0 and not getattr(pr, "ricocheted", False) and random.random() < chance:
                            options = [o for o in self.enemies if not o.dead and o is not e]
                            if options:
                                target = min(options, key=lambda o:o.pos.distance_to(e.pos))
                                d = target.pos-e.pos
                                if d.length_squared()>0:
                                    d=d.normalize()
                                    rp=Projectile(e.pos, d*max(S(520),pr.vel.length()), pr.damage*0.78, "player", pr.radius, pr.color, 1.4, 0)
                                    rp.kind=source
                                    rp.ricocheted=True
                                    rp.hit_ids.add(e.id)
                                    rp.domain_charge_raw=0.0; rp.domain_charge_uses_left=0
                                    rp.double_hit_chance=getattr(pr,"double_hit_chance",0.0)
                                    new_projectiles.append(rp)

                        if isinstance(pr, (BoomerangProjectile, HisokaCardProjectile)):
                            # Bumerangues e cartas do Hisoka continuam o caminho e depois retornam.
                            pass
                        elif pr.pierce > 0:
                            pr.pierce -= 1
                        else:
                            hit = True
                            break
                if strikada_continue:
                    new_projectiles.append(pr)
                    continue
                if hit:
                    continue
            new_projectiles.append(pr)
        self.projectiles = new_projectiles

        alive_drops = []
        for d in self.drops:
            if not d.update(dt):
                continue
            dist = d.pos.distance_to(self.player.pos)
            if self.player.orb_magnet and dist < S(470) and dist > 1:
                d.pos += (self.player.pos-d.pos).normalize() * S(520) * dt
                dist = d.pos.distance_to(self.player.pos)
            pickup_radius=d.radius + self.player.radius + S(8)
            if d.kind in ("coin","heal","ambient_heal","friend_heal"):
                pickup_radius *= 1.0 + getattr(self.player,"passive_collect_bonus",0.0)
            if dist <= pickup_radius:
                if str(d.kind).startswith("mat:"):
                    self.collect_forge_material(d.kind.split(":",1)[1],1)
                    continue
                if d.kind == "heal":
                    if self.game_mode == "extinction":
                        self.damage_texts.append(DamageText("EXTINCAO: SEM CURA", pygame.Vector2(self.player.pos), RED, 0.7))
                    else:
                        AUDIO.play("heal", 0.82, 60)
                        if self.player.insatiable_hunger:
                            self.damage_texts.append(DamageText("FOME", pygame.Vector2(self.player.pos), RED))
                        else:
                            self.player.heal(max(22, self.player.max_hp * 0.18), self)
                        if self.player.questionable_hemo:
                            self.player.recover_stamina(max(12, self.player.max_stamina*0.12), self)
                elif d.kind == "ambient_heal":
                    AUDIO.play("heal", 0.55, 80)
                    if not self.player.insatiable_hunger:
                        self.player.heal(max(6, self.player.max_hp * 0.06), self)
                elif d.kind == "friend_heal":
                    AUDIO.play("heal",0.45,80)
                    if not self.player.insatiable_hunger: self.player.heal(5,self)
                elif d.kind == "stamina":
                    AUDIO.play("stamina", 0.82, 60)
                    self.player.recover_stamina(max(28, self.player.max_stamina * 0.25), self)
                elif d.kind == "shield": AUDIO.play("pickup", 0.70, 50); self.player.shield += 1
                elif d.kind == "haste": AUDIO.play("pickup", 0.70, 50); self.player.speed_buff = 8
                elif d.kind == "coin":
                    AUDIO.play("pickup", 0.62, 45)
                    reward_mult=difficulty_cfg(getattr(self,"difficulty","easy"))["reward"] if self.mode=="arena" else 1.0
                    self.run_coins += max(1,int(8 * self.coin_multiplier * getattr(self,"meta_coin_multiplier",1.0) * reward_mult * max(0.10,1.0+self.player.passive_coin_bonus)))
                self.spawn_particles(d.pos, Drop.COLORS[d.kind], 9)
                if self.player.orb_magnet and d.kind in ("heal","ambient_heal","friend_heal","stamina"):
                    self.orb_chain_count += 1
                    self.orb_chain_timer = 2.0
                    if self.orb_chain_count >= 3:
                        self.orb_chain_count = 0
                        old = self.current_damage_kind
                        self.current_damage_kind = "orb_blast"
                        for e in list(self.enemies):
                            if not e.dead and e.pos.distance_to(self.player.pos) <= S(250):
                                e.damage(self.player.base_damage*1.8*self.player.damage_mult, self, self.player.pos)
                        self.current_damage_kind = old
                        self.damage_texts.append(DamageText("COLAPSO DE ORBES!", pygame.Vector2(self.player.pos), PURPLE))
                continue
            alive_drops.append(d)
        self.drops = alive_drops

        self.particles = [p for p in self.particles if p.update(dt)]
        self.damage_texts = [d for d in self.damage_texts if d.update(dt)]
        self.forge_fire_trails = [f for f in self.forge_fire_trails if f.update(dt, self)]

        if self.parries >= 100:
            self.unlock_achievement("parry_100")
        if self.perfect_dodges >= 75:
            self.unlock_achievement("dodge_75")

        if self.mode == "afk":
            self.player.hp = min(self.player.max_hp, self.player.hp + self.player.max_hp * 0.08 * dt)
            cap = self.player.max_stamina * (1.30 if self.player.beyond_limit else 1.0)
            afk_sta_regen = 18.0 * (0.20 if self.player.character == "Sans" and self.bad_time_active else 1.0)
            self.player.stamina = min(cap, self.player.stamina + afk_sta_regen * dt)
            if not any(isinstance(e, TrainingDummy) for e in self.enemies): self.spawn_training_dummy()
        elif self.mode == "training":
            self.player.hp=min(self.player.max_hp,self.player.hp+self.player.max_hp*0.05*dt)
            if not self.enemies:
                self.training_respawn_timer-=dt
                if self.training_respawn_timer<=0:
                    self.spawn_bestiary_target(self.training_target_name); self.training_respawn_timer=1.5
        elif self.game_mode=="arena_survival":
            self.update_arena_survival(dt)
        elif self.game_mode in ("mahoraga_trial","sans_trial"):
            pass
        elif not self.enemies and not self.wave_clear_lock and self.state == "playing":
            self.wave_clear_lock = True
            if self.mahoraga is not None and not self.mahoraga.dead:
                self.mahoraga.end_wave_adapt(self)
            if hasattr(self.player, "vasco_wave_clear"):
                self.player.vasco_wave_clear(self)
            if self.game_mode!="extinction": self.player.heal(10, self)
            self.player.recover_stamina(18, self)
            AUDIO.play("wave_clear", 0.85)
            self.check_special_character_unlocks_on_wave_clear()
            self.player.passive_on_wave_clear(self)
            self.roll_evolution_point()
            # Modo EVOLUCAO: inimigos ganham uma nova propriedade ANTES da proxima wave.
            if self.game_mode=="evolution": self.add_evolution_trait()
            # BOSS RUSH herda um fragmento mecanico do boss anterior.
            if self.game_mode=="boss_rush":
                inherit=["FRENESI","CARAPACA","CERCO","RITUAL","FOME","ECO","PRESSAO"]
                self.boss_heritages.append(inherit[(self.wave-1)%len(inherit)])
                if self.wave>=self.boss_rush_sequence_length():
                    self.complete_mode("BOSS RUSH COMPLETO",f"HERANCAS ACUMULADAS: {len(self.boss_heritages)}"); return
            if self.game_mode=="one_vs_all" and self.wave>=len(self.one_vs_all_roster):
                self.unlock_achievement("solo_survivor")
                self.complete_mode("SOBROU SO VOCE",f"TODOS OS {len(self.one_vs_all_roster)} RIVAIS CAIRAM"); return
            if self.game_mode=="infinite" and self.wave%10==0:
                self.open_curse_choice()
            else:
                self.open_upgrade()

    def update(self, dt):
        self.evolution_notice_timer = max(0.0, self.evolution_notice_timer - dt)
        self.passive_roll_anim=max(0.0,getattr(self,"passive_roll_anim",0.0)-dt)
        self.update_passive_roll_system(dt)
        if self.state == "playing":
            self.update_playing(dt)
        elif self.state in ("menu", "mode_select", "character_select", "character_catalog_list", "character_catalog_detail", "difficulty_select", "easy_trial_warning", "curse_choice", "mode_complete", "shop", "upgrade", "death", "glonk_death", "upgrade_catalog", "passive_catalog", "passive_roll", "passive_auto_config", "passive_dev", "bestiary", "forge", "items", "weapons", "control_editor", "run_upgrades", "whats_new", "achievements", "missions", "cheats", "profile", "profile_full", "vinicius_mini", "vinicius_mega"):
            if self.state=="whats_new": self.update_whats_new_scroll(dt)
            if self.state=="shop": self.update_shop_scroll(dt)
            self.particles = [p for p in self.particles if p.update(dt)]
            self.damage_texts = [d for d in self.damage_texts if d.update(dt)]
        AUDIO.sync_music(self)

    def draw_bg(self):
        maho=getattr(self,"mahoraga",None)
        maho_boss_domain=(self.game_mode=="mahoraga_trial" and maho is not None and not maho.dead and getattr(maho,"domain_active",False))
        maho_player_domain=(self.domain_active and self.player.character==MAHORAGA_MODULE_KEY and self.domain_name=="SANTUARIO DA ADAPTACAO")
        maho_domain=(maho_boss_domain or maho_player_domain)
        if maho_domain:
            SCREEN.fill((12,12,14))
        else:
            SCREEN.fill((7, 13, 34) if self.bad_time_active else BG)
        grid = S(80)
        map_top = 0
        map_bottom = H
        for x in range(0, W, grid):
            col=(42,42,45) if maho_domain else ((15,42,74) if self.bad_time_active else (24,26,34))
            pygame.draw.line(SCREEN,col,(x,map_top),(x,map_bottom),1)
        for y in range(map_top, map_bottom, grid):
            col=(42,42,45) if maho_domain else ((15,42,74) if self.bad_time_active else (24,26,34))
            pygame.draw.line(SCREEN,col,(0,y),(W,y),1)

        # V8: borda branca mostrando claramente o limite da arena.
        inset = max(2, S(4))
        arena_rect = pygame.Rect(inset, map_top, W - inset * 2, map_bottom - map_top)
        pygame.draw.rect(SCREEN, (190,190,195) if maho_domain else WHITE, arena_rect, width=max(2, S(5)))

    def camera_offset(self):
        if self.shake <= 0:
            return pygame.Vector2()
        self.shake *= 0.82
        if self.shake < 0.5:
            self.shake = 0
        return pygame.Vector2(random.uniform(-self.shake, self.shake), random.uniform(-self.shake, self.shake))

    def draw_domain_zone(self, offset):
        # V10: apenas contornos leves. Sem superficies alpha gigantes = amigo do Android.
        if self.domain_active and self.player.character not in ("Sans", "Potential Man"):
            if self.player.character == SUKUNA_KEY:
                arena=pygame.Rect(S(4),S(165),W-S(8),max(S(40),H-S(500)))
                pygame.draw.rect(SCREEN,SUKUNA_SLASH,arena,max(2,S(7)))
                pygame.draw.rect(SCREEN,WHITE,arena.inflate(-S(14),-S(14)),max(1,S(2)))
            else:
                c = self.domain_center + offset
                pygame.draw.circle(SCREEN, self.player.color, (int(c.x), int(c.y)), int(self.domain_radius), max(2, S(6)))
                pygame.draw.circle(SCREEN, WHITE, (int(c.x), int(c.y)), max(1, int(self.domain_radius-S(10))), max(1, S(2)))

        # V15.19: o Mahoraga jogável usa o MESMO visual-base da Roda Eterna do boss:
        # marcas concêntricas no chão + roda gigante girando ao fundo + barreira dupla.
        if self.domain_active and self.player.character==MAHORAGA_MODULE_KEY and self.domain_name=="SANTUARIO DA ADAPTACAO":
            c=self.domain_center+offset
            r=int(self.domain_radius)
            ang0=float(getattr(self.player,"mahoraga_domain_visual_angle",0.0))
            for frac in (0.20,0.34,0.48,0.64,0.82):
                pygame.draw.circle(SCREEN,(92,92,96),(int(c.x),int(c.y)),max(1,int(r*frac)),max(1,S(2)))
            for i in range(8):
                a=ang0+i*math.tau/8
                mc=c+vec_from_angle(a)*r*0.58
                pygame.draw.circle(SCREEN,(108,108,112),(int(mc.x),int(mc.y)),S(34),max(1,S(3)))
            wheel_r=max(S(120),int(r*0.70))
            pygame.draw.circle(SCREEN,(150,150,154),(int(c.x),int(c.y)),wheel_r,max(2,S(5)))
            for i in range(8):
                a=ang0+i*math.tau/8
                d=vec_from_angle(a)
                a1=c+d*(wheel_r*0.34); b1=c+d*wheel_r
                pygame.draw.line(SCREEN,(165,165,170),(int(a1.x),int(a1.y)),(int(b1.x),int(b1.y)),max(2,S(5)))
                tip=c+d*wheel_r
                pygame.draw.circle(SCREEN,(205,205,208),(int(tip.x),int(tip.y)),S(8),max(1,S(2)))
            pygame.draw.circle(SCREEN,(210,210,214),(int(c.x),int(c.y)),r,max(2,S(8)))
            pygame.draw.circle(SCREEN,(95,95,100),(int(c.x),int(c.y)),max(1,r-S(10)),max(2,S(3)))
        for e in self.enemies:
            if isinstance(e, Boss) and not e.dead and e.domain_active:
                c = e.domain_center + offset
                pygame.draw.circle(SCREEN, e.color, (int(c.x), int(c.y)), int(e.domain_radius), max(2, S(7)))
                pygame.draw.circle(SCREEN, RED, (int(c.x), int(c.y)), max(1, int(e.domain_radius-S(12))), max(1, S(2)))
        maho=getattr(self,"mahoraga",None)
        if self.game_mode=="mahoraga_trial" and maho is not None and not maho.dead and getattr(maho,"domain_active",False):
            c=maho.domain_center+offset
            r=int(maho.domain_radius)
            # Marcas circulares no chao.
            for frac in (0.20,0.34,0.48,0.64,0.82):
                pygame.draw.circle(SCREEN,(92,92,96),(int(c.x),int(c.y)),max(1,int(r*frac)),max(1,S(2)))
            for i in range(8):
                a=getattr(maho,"domain_visual_angle",0.0)+i*math.tau/8
                mc=c+vec_from_angle(a)*r*0.58
                pygame.draw.circle(SCREEN,(108,108,112),(int(mc.x),int(mc.y)),S(34),max(1,S(3)))
            # Roda gigante ao fundo, girando lentamente (ou muito rapido na analise final).
            wheel_r=max(S(120),int(r*0.70))
            pygame.draw.circle(SCREEN,(150,150,154),(int(c.x),int(c.y)),wheel_r,max(2,S(5)))
            for i in range(8):
                a=getattr(maho,"domain_visual_angle",0.0)+i*math.tau/8
                d=vec_from_angle(a)
                a1=c+d*(wheel_r*0.34); b1=c+d*wheel_r
                pygame.draw.line(SCREEN,(165,165,170),(int(a1.x),int(a1.y)),(int(b1.x),int(b1.y)),max(2,S(5)))
                tip=c+d*wheel_r
                pygame.draw.circle(SCREEN,(205,205,208),(int(tip.x),int(tip.y)),S(8),max(1,S(2)))
            # Barreira fechada.
            pygame.draw.circle(SCREEN,(210,210,214),(int(c.x),int(c.y)),r,max(2,S(8)))
            pygame.draw.circle(SCREEN,(95,95,100),(int(c.x),int(c.y)),max(1,r-S(10)),max(2,S(3)))
            # Telegraph do Corte do Mundo.
            if getattr(maho,"domain_cut_pending",False):
                a=maho.domain_cut_start+offset; b=maho.domain_cut_end+offset
                pulse=1.0+0.25*math.sin(pygame.time.get_ticks()*0.025)
                pygame.draw.line(SCREEN,WHITE,(int(a.x),int(a.y)),(int(b.x),int(b.y)),max(S(5),int(S(8)*pulse)))
            # Julgamento final: onda circular chegando.
            if getattr(maho,"domain_final_wave_active",False):
                wr=int(maho.domain_final_wave_radius)
                pygame.draw.circle(SCREEN,WHITE,(int(c.x),int(c.y)),wr,max(3,S(12)))
                pygame.draw.circle(SCREEN,(145,145,150),(int(c.x),int(c.y)),max(S(18),S(92)),max(2,S(4)))

    def draw_domain_cutscene(self):
        # Apenas texto curto: muito mais leve que criar superficies alpha gigantes por frame.
        if self.domain_message_timer <= 0:
            return
        title = "BAD TIME" if self.player.character == "Sans" else ("ULT: INVOCACAO" if self.player.character == "Potential Man" else "EXPANSAO DE DOMINIO")
        draw_text(title, FONT_L, WHITE, (W/2, H*0.25), True)
        draw_text(self.domain_name, FONT_M, CYAN if self.player.character == "Sans" else self.player.color, (W/2, H*0.31), True)
        draw_text(CHARACTER_CONFIG[self.player.character]["domain_desc"], FONT_S, GRAY, (W/2, H*0.355), True)

    def draw_hud(self):
        p = self.player
        x = S(35)
        bw = min(S(900), int(W * 0.39))
        bh = S(34)

        # HP
        y = S(30)
        pygame.draw.rect(SCREEN, DARK, (x, y, bw, bh), border_radius=S(12))
        hp_ratio = clamp(p.hp / max(1, p.max_hp), 0, 1)
        pygame.draw.rect(SCREEN, RED, (x, y, bw*hp_ratio, bh), border_radius=S(12))
        draw_text(f"HP {int(p.hp)}/{int(p.max_hp)}", FONT_S, WHITE, (x+bw/2, y+bh/2), True)

        # Estamina
        sy = y + bh + S(12)
        pygame.draw.rect(SCREEN, DARK, (x, sy, bw, bh), border_radius=S(12))
        st_ratio = clamp(p.stamina / max(1, p.max_stamina), 0, 1)
        pygame.draw.rect(SCREEN, CYAN, (x, sy, bw*st_ratio, bh), border_radius=S(12))
        draw_text(f"ESTAMINA {int(p.stamina)}/{int(p.max_stamina)}", FONT_S, WHITE, (x+bw/2, sy+bh/2), True)

        hud_shift=0
        if p.character=="Vinicius 13":
            scrap_y=sy+bh+S(8); scrap_h=S(28)
            pygame.draw.rect(SCREEN,DARK,(x,scrap_y,bw,scrap_h),border_radius=S(9))
            scrap_ratio=clamp(self.vinicius_scrap/20.0,0,1)
            pygame.draw.rect(SCREEN,ORANGE,(x,scrap_y,bw*scrap_ratio,scrap_h),border_radius=S(9))
            pygame.draw.rect(SCREEN,WHITE,(x,scrap_y,bw,scrap_h),max(1,S(2)),border_radius=S(9))
            draw_text(f"SUCATA {self.vinicius_scrap}   |   TORRES PRONTAS x{self.vinicius_turret_tokens}",FONT_S,WHITE,(x+bw/2,scrap_y+scrap_h/2),True)
            hud_shift=S(42)
        char_hud = "Vasco, O Apostador Incansável" if p.character == "Vasco" else p.character
        draw_text(f"{char_hud} | {p.weapon_name}", FONT_S, p.color, (x, sy+S(48)+hud_shift))
        if self.mode == "afk":
            draw_text("ZONA AFK", FONT_M, CYAN, (x, sy+S(82)+hud_shift))
        elif self.mode == "training":
            draw_text("TREINO: "+str(self.training_target_name), FONT_M, CYAN, (x, sy+S(82)+hud_shift))
        else:
            draw_text(f"ONDA {self.wave}", FONT_M, WHITE, (x, sy+S(82)+hud_shift))
            dcfg = difficulty_cfg(getattr(self,"difficulty","easy"))
            draw_text(dcfg["name"], FONT_S, dcfg["color"], (x+S(245), sy+S(92)+hud_shift))
            gm=GAME_MODES.get(getattr(self,"game_mode","normal"),GAME_MODES["normal"])
            draw_text(gm["name"],FONT_S,gm["color"],(x+S(390),sy+S(92)+hud_shift))
        draw_text(f"KOs {self.kills}   $ {self.run_coins}", FONT_S, GRAY, (x, sy+S(130)+hud_shift))
        active_bits=[]
        for _k,_info in CONSUMABLES.items():
            _rem=consumable_remaining(_k)
            if _rem>0: active_bits.append(f"{_info['name'].replace('POCAO DE ','')} {int(_rem//60):02d}:{int(_rem%60):02d}")
        if active_bits:
            draw_text("BOOSTS: "+" | ".join(active_bits),FONT_S,YELLOW,(x,sy+S(160)+hud_shift))
        if SAVE.get("scanner_unlocked",False):
            live=[e for e in self.enemies if not getattr(e,"dead",False)]
            if live:
                target=max(live,key=lambda e:(1 if isinstance(e,Boss) else 0,float(getattr(e,"max_hp",0))))
                nm=str(getattr(target,"name",getattr(target,"kind",target.__class__.__name__))).upper()
                hp=int(max(0,getattr(target,"hp",0))); mh=int(max(1,getattr(target,"max_hp",1))); sp=int(getattr(target,"speed",0))
                draw_text(f"SCANNER: {nm} | HP {hp}/{mh} | VEL {sp}",SHOP_FONT_XS,DIVINE_BLUE,(x,sy+S(190)+hud_shift))

        if self.combo > 0:
            draw_text(f"COMBO x{1 + self.combo*0.08:.1f}", FONT_M, YELLOW, (W/2, S(86)), True)

        if self.game_mode=="mahoraga_trial" and self.mahoraga is not None:
            mw=min(S(850),int(W*0.42)); mx=W/2-mw/2; my=S(118); mh=S(24)
            pygame.draw.rect(SCREEN,DARK,(mx,my,mw,mh),border_radius=S(8))
            pygame.draw.rect(SCREEN,YELLOW,(mx,my,mw*clamp(self.mahoraga.hp/max(1,self.mahoraga.max_hp),0,1),mh),border_radius=S(8))
            draw_text(f"MAHORAGA — IA {getattr(self.mahoraga,'adaptation_pct',0)}% | HP {int(self.mahoraga.hp)}/{int(self.mahoraga.max_hp)}",FONT_S,WHITE,(W/2,my+S(38)),True)
            status=[]
            if getattr(self.mahoraga,"shield_timer",0)>0: status.append(f"ESCUDO {self.mahoraga.shield_timer:.1f}s")
            if getattr(self.mahoraga,"domain_active",False):
                cat=getattr(self.mahoraga,"domain_adapt_category",None) or "SEM ALVO"
                res=int(getattr(self.mahoraga,"domain_adapt_resistance",0.0)*100)
                spins=getattr(self.mahoraga,"domain_adapt_stacks",0)
                status.append(f"RODA ETERNA {self.mahoraga.domain_timer:.1f}s | {cat} {spins}/4 -{res}%")
            if self.mahoraga_final_countdown>0: status.append(f"99%: DERROTE EM {self.mahoraga_final_countdown:.1f}s")
            if status: draw_text("  |  ".join(status),FONT_S,RED if self.mahoraga_final_countdown>0 else CYAN,(W/2,my+S(68)),True)

        if self.game_mode=="sans_trial" and self.sans_trial_error:
            draw_text("SANS TRIAL: ERRO SALVO EM sans_trial_crash.log",FONT_S,RED,(W/2,S(108)),True)
        if self.game_mode=="sans_trial" and self.sans_trial_boss is not None and not self.sans_trial_boss.dead:
            sb=self.sans_trial_boss; sw=min(S(850),int(W*0.42)); sx=W/2-sw/2; syb=S(118); sh=S(24)
            pygame.draw.rect(SCREEN,DARK,(sx,syb,sw,sh),border_radius=S(8))
            pygame.draw.rect(SCREEN,CYAN,(sx,syb,sw*clamp(sb.stamina/max(1,sb.max_stamina),0,1),sh),border_radius=S(8))
            pygame.draw.rect(SCREEN,WHITE,(sx,syb,sw,sh),max(1,S(2)),border_radius=S(8))
            title="SANS — VERDADEIRA BATALHA" if sb.final_judgement else "SANS — ESTAMINA"
            draw_text(f"{title} {int(sb.stamina)}/{int(sb.max_stamina)}",FONT_S,RED if sb.final_judgement else WHITE,(W/2,syb+S(38)),True)
            if sb.time_since_attack>=6.0: draw_text("VOCE DEMOROU: SANS ESTA RECUPERANDO ESTAMINA",FONT_S,CYAN,(W/2,syb+S(66)),True)

        # Expansao de Dominio no topo direito
        uw = min(S(700), int(W * 0.31))
        ux, uy, uh = W-SAFE-uw, S(35), S(28)
        pygame.draw.rect(SCREEN, DARK, (ux, uy, uw, uh), border_radius=S(10))
        if p.character in ("Glonk", "Glonk 100% Power"):
            draw_text("DOMINIO: indisponivel", FONT_S, GRAY, (ux, uy+S(42)))
        elif p.character=="Vinicius 13":
            minis=sum(1 for t in self.vinicius_turrets if not t.dead and not t.mega)
            pygame.draw.rect(SCREEN,ORANGE,(ux,uy,uw*clamp(minis/10.0,0,1),uh),border_radius=S(10))
            draw_text(f"AUTOMACAO V13 | MINI {minis}/10 | TORRES PRONTAS x{self.vinicius_turret_tokens}",FONT_S,WHITE,(ux,uy+S(42)))
        elif p.character == "Potential Man":
            alive_maho=self.mahoraga is not None and not self.mahoraga.dead
            if alive_maho:
                ratio=clamp(self.mahoraga.hp/max(1,self.mahoraga.max_hp),0,1)
                pygame.draw.rect(SCREEN,YELLOW,(ux,uy,uw*ratio,uh),border_radius=S(10))
                draw_text(f"MAHORAGA ATIVO | ADAPTACAO {int(self.mahoraga.resistance*100)}%",FONT_S,WHITE,(ux,uy+S(42)))
            else:
                pygame.draw.rect(SCREEN,PURPLE,(ux,uy,uw*(self.domain_charge/100),uh),border_radius=S(10))
                draw_text(f"MAHORAGA {int(self.domain_charge)}%",FONT_S,WHITE,(ux,uy+S(42)))
            dogs=sum(1 for x in self.potential_summons if isinstance(x,DivineDog) and not x.dead)
            dogtxt=f"CAES: {dogs}/2" if dogs else ("CAES: PRONTOS" if p.potential_dog_cd<=0 else f"CAES: {p.potential_dog_cd:.1f}s")
            draw_text(dogtxt,FONT_S,WHITE,(ux,uy+S(76)))
        elif p.character == "Sans":
            ready = self.domain_charge >= 100 or p.stamina < p.max_stamina*0.50
            if self.bad_time_active:
                ratio=clamp(self.domain_timer/max(0.01,self.domain_duration),0,1)
                pygame.draw.rect(SCREEN,CYAN,(ux,uy,uw*ratio,uh),border_radius=S(10))
                draw_text(f"BAD TIME ATIVA {self.domain_timer:.1f}s",FONT_S,WHITE,(ux,uy+S(42)))
            else:
                pygame.draw.rect(SCREEN,CYAN if ready else PURPLE,(ux,uy,uw*(self.domain_charge/100),uh),border_radius=S(10))
                draw_text("BAD TIME PRONTA" if ready else f"BAD TIME {int(self.domain_charge)}% | libera abaixo de 50% STA",FONT_S,WHITE,(ux,uy+S(42)))
            if self.bad_time_active:
                draw_text("ALMA: SEM COOLDOWN | CUSTO 10% STA",FONT_S,CYAN,(ux,uy+S(76)))
            else:
                cd_txt="PRONTO" if p.sans_blaster_cd<=0 else f"{p.sans_blaster_cd:.1f}s"
                draw_text(f"BLASTER: {cd_txt}",FONT_S,CYAN,(ux,uy+S(76)))
        elif p.character == "Vasco" and p.vasco_jackpot_timer > 0:
            ratio = clamp(p.vasco_jackpot_timer / max(0.01, p.vasco_jackpot_duration), 0, 1)
            pygame.draw.rect(SCREEN, VASCO_NEON, (ux, uy, uw*ratio, uh), border_radius=S(10))
            draw_text(f"JACKPOT MODE {p.vasco_jackpot_timer:.1f}s | DOMINIO TRAVADO", FONT_S, WHITE, (ux, uy+S(42)))
        elif p.character==MAHORAGA_MODULE_KEY:
            if self.domain_active and self.domain_name=="SANTUARIO DA ADAPTACAO":
                ratio=clamp(self.domain_timer/max(0.01,self.domain_duration),0,1)
                pygame.draw.rect(SCREEN,YELLOW,(ux,uy,uw*ratio,uh),border_radius=S(10))
                draw_text(f"SANTUARIO DA ADAPTACAO {self.domain_timer:.1f}s | RODA {int(p.mahoraga_domain_adapt_pct)}%",FONT_S,WHITE,(ux,uy+S(42)))
            else:
                pygame.draw.rect(SCREEN,YELLOW if self.domain_charge>=100 else PURPLE,(ux,uy,uw*(self.domain_charge/100),uh),border_radius=S(10))
                ready_txt="PRONTA" if self.domain_charge>=100 else f"{int(self.domain_charge)}%"
                draw_text(f"SANTUARIO DA ADAPTACAO {ready_txt} | CARGA 4x MAIS LENTA",FONT_S,WHITE,(ux,uy+S(42)))
        elif self.domain_active:
            ratio = clamp(self.domain_timer / max(0.01, self.domain_duration), 0, 1)
            pygame.draw.rect(SCREEN, p.color, (ux, uy, uw*ratio, uh), border_radius=S(10))
            draw_text(f"DOMINIO ATIVO {self.domain_timer:.1f}s - {p.domain_name}", FONT_S, WHITE, (ux, uy+S(42)))
        else:
            pygame.draw.rect(SCREEN, PURPLE, (ux, uy, uw*(self.domain_charge/100), uh), border_radius=S(10))
            draw_text(f"DOMINIO {int(self.domain_charge)}% - {p.domain_name}", FONT_S, WHITE, (ux, uy+S(42)))

        # V13: painel padrao de cooldowns no canto. Novas habilidades devem sempre aparecer aqui.
        cool_x=ux; cool_y=uy+S(104); cool_w=uw
        def _cd(v): return "PRONTO" if v<=0.01 else f"{v:.1f}s"
        if p.character=="Sans" and self.bad_time_active:
            parry_label="ALMA"; parry_val=0.0
        elif p.character==MAHORAGA_MODULE_KEY:
            parry_label="ADAPT"; parry_val=p.mahoraga_adapt_cd
        else:
            parry_label="BLAST" if p.character=="Sans" else "PARRY"
            parry_val=p.sans_blaster_cd if p.character=="Sans" else p.parry_cd
        draw_text(f"ATK {_cd(p.attack_cd)}  |  DASH {_cd(p.dash_cd)}  |  {parry_label} {_cd(parry_val)}",FONT_S,GRAY,(cool_x,cool_y))
        special_text=""; special_color=DIVINE_BLUE
        if p.divine_ana:
            if self.attack_held:
                remain=max(0.0,p.longinus_next_threshold-p.divine_attack_hold)
                special_text=f"LONGINUS: PROXIMA ANA {remain:.1f}s"
            else:
                special_text="LONGINUS: SEGURE ATK 2.0s"
        elif p.divine_kayk:
            used=p.kayk_builder_wave_used==self.wave
            if self.dash_held and not used: special_text=f"BIG BUILDER: {max(0,1-p.divine_dash_hold):.1f}s"
            else: special_text="BIG BUILDER: USADO" if used else "BIG BUILDER: SEGURE DASH 1.0s"
        elif p.divine_ruan:
            if self.dash_held: special_text=f"MANTO: TELEPORTE {max(0,1-p.divine_dash_hold):.1f}s"
            else: special_text="MANTO: DASH=AMIGO SE SOZINHO | SEGURE 1.0s"
        elif p.divine_kevyn:
            special_text=(f"SETE FACES: ATRAIR {max(0,1-p.divine_dash_hold):.1f}s" if self.dash_held else "SETE FACES: SEGURE DASH 1s = ATRAIR | ATK=SPAM | PARRY 1s | DOM 3s")
        elif p.divine_pedro:
            special_text=f"TEMPO DE CACA: SEGURE DASH {max(0,1-p.divine_dash_hold):.1f}s" if self.dash_held else "TEMPO DE CACA: SEGURE DASH 1.0s"
        elif p.divine_vasco:
            special_text=f"LEME DE DHARMA BETA: -{int(p.vasco_dharma_reduction*100)}% DANO RECEBIDO"
        elif p.character==SUKUNA_KEY:
            if self.domain_held:
                special_text=f"SANTUARIO: SEGURE {max(0,3-p.sukuna_domain_hold):.1f}s"
                special_color=SUKUNA_SLASH
            elif self.sukuna_ult_marked:
                special_text="FUUGA MARCADO: TOQUE ULT = DISPARAR | SEGURE 3s = SANTUARIO"
                special_color=SUKUNA_FIRE
            else:
                special_text="TOQUE ULT = MIRAR FUUGA | SEGURE 3s = SANTUARIO"
                special_color=SUKUNA_FIRE
        elif p.character==MAHORAGA_MODULE_KEY:
            eff=p.mahoraga_effective_adaptation_pct(self)
            if p.mahoraga_adapt_timer>0:
                special_text=f"ADAPTANDO {p.mahoraga_adapt_timer:.1f}s | BASE {int(p.mahoraga_adaptation_pct)}%"
            elif self.domain_active and self.domain_name=="SANTUARIO DA ADAPTACAO":
                special_text=f"RODA {int(p.mahoraga_domain_adapt_pct)}% | EFETIVA {int(eff)}%"
            else:
                special_text=f"ADAPTACAO {int(p.mahoraga_adaptation_pct)}% / 70%"
            special_color=YELLOW
        elif p.character=="Vinicius 13":
            minis=sum(1 for t in self.vinicius_turrets if not t.dead and not t.mega); megas=[t for t in self.vinicius_turrets if t.mega and not t.dead]
            threshold=10
            to_next=threshold-(self.vinicius_shots%threshold) if self.vinicius_shots%threshold else threshold
            if self.domain_held:
                special_text=f"ULT: SEGURE {max(0.0,1.5-p.vinicius_ult_hold):.1f}s PRA MEGA | TOQUE = MINI"
            elif megas:
                mt=megas[0]; special_text=f"MINI {minis}/10 | TOKENS x{self.vinicius_turret_tokens} | PROXIMA EM {to_next} TIROS | {ViniciusTurret.LABELS.get(mt.kind,'MEGA')} {_cd(mt.cd)}"
            else:
                special_text=f"MINI {minis}/10 | TOKENS x{self.vinicius_turret_tokens} | PROXIMA EM {to_next} TIROS | MEGA: 5 MINI + 20 SUCATA"
        if special_text:
            draw_text(special_text,FONT_S,special_color,(cool_x,cool_y+S(30)))

        if self.game_mode=="mahoraga_trial" and self.mahoraga_ai_messages:
            my=cool_y+S(72)
            for msg,timer,color in self.mahoraga_ai_messages[:4]:
                alpha_note=""  # timers only control lifetime; keep drawing cheap on Android
                draw_wrapped_text(msg,FONT_S,color,pygame.Rect(ux,my,uw,S(60)),2,False,2)
                my+=S(58)

        if p.character == "Vasco":
            bet_y = uy + S(174)
            bet_h = S(24)
            pygame.draw.rect(SCREEN, DARK, (ux,bet_y,uw,bet_h), border_radius=S(9))
            ratio = clamp(p.vasco_bet_level/100.0,0,1)
            if p.vasco_bet_level < 25: bet_color=RED
            elif p.vasco_bet_level < 50: bet_color=ORANGE
            elif p.vasco_bet_level < 75: bet_color=YELLOW
            elif p.vasco_bet_level < 100: bet_color=GREEN
            else: bet_color=VASCO_NEON
            pygame.draw.rect(SCREEN, bet_color, (ux,bet_y,uw*ratio,bet_h), border_radius=S(9))
            draw_text(f"NIVEL DA APOSTA {int(p.vasco_bet_level)}% | DANO x{p.vasco_damage_multiplier():.2f}", FONT_S, WHITE, (ux,bet_y+S(40)))

        if p.character==LIRA_KEY:
            ly=uy+S(174)
            if self.domain_active and p.lira_domain_buffs:
                lm={"strength":"FORCA+70%","life":"HP+50%","resistance":"DEFESA+","speed":"VEL+50%","intelligence":"CD/ALCANCE+"}
                draw_text("C#NSUR# ATIVA: "+" | ".join(lm[k] for k in self.lira_domain_selected if k in p.lira_domain_buffs),FONT_S,LIRA_ACCENT,(ux,ly))
            else:
                draw_text("CENSURA: FORCA / VELOCIDADE / RESISTENCIA / INTELIGENCIA",FONT_S,LIRA_ACCENT,(ux,ly))
        if p.character==SUKUNA_KEY:
            fy=uy+S(174); fh=S(22); gap=max(1,S(2)); seg_w=max(2,(uw-gap*19)/20)
            for i in range(20):
                x=ux+i*(seg_w+gap)
                pygame.draw.rect(SCREEN,SUKUNA_HAIR if i<p.sukuna_fingers else PANEL2,(x,fy,seg_w,fh),border_radius=max(1,S(3)))
            draw_text(f"DEDOS DO SUKUNA {p.sukuna_fingers}/20 | DANO x{p.sukuna_finger_damage_multiplier():.1f} | HP +{p.sukuna_fingers*5}%",FONT_S,WHITE,(ux,fy+S(36)))

        if self.event_name:
            draw_text("EVENTO: " + self.event_name, FONT_S, PINK, (W/2, S(165)), True)

        if self.achievement_timer > 0:
            r = pygame.Rect(W/2-S(250), S(205), S(500), S(70))
            pygame.draw.rect(SCREEN, PANEL2, r, border_radius=S(18))
            draw_text("CONQUISTA: " + self.achievement, FONT_S, YELLOW, r.center, True)

    def control_rect(self, key):
        """Hitbox efetiva dos controles: respeita exatamente o layout salvo/editor."""
        return self.buttons[key]

    def draw_controls(self):
        # Joystick analogico: base + knob acompanha o dedo.
        joy = self.buttons["joystick"]
        center = pygame.Vector2(joy.center)
        base_r = min(joy.w, joy.h)//2
        knob_r = max(S(34), int(base_r*0.38))
        knob = center + self.joystick_vector * (base_r-knob_r-S(6))
        pygame.draw.circle(SCREEN, PANEL2, (int(center.x), int(center.y)), base_r)
        pygame.draw.circle(SCREEN, WHITE, (int(center.x), int(center.y)), base_r, max(2,S(4)))
        pygame.draw.circle(SCREEN, CYAN, (int(knob.x), int(knob.y)), knob_r)
        pygame.draw.circle(SCREEN, WHITE, (int(knob.x), int(knob.y)), knob_r, max(2,S(3)))
        draw_text("MOVE", FONT_S, DARK, (int(knob.x), int(knob.y)), True)

        if self.uses_aim_stick():
            ar = self.buttons["attack"]
            ac = pygame.Vector2(ar.center); br=min(ar.w,ar.h)//2; kr=max(S(28),int(br*0.34))
            av = self.aim_vector if self.aim_active else pygame.Vector2(0,0)
            knob = ac + av*(br-kr-S(5))
            pygame.draw.circle(SCREEN, PANEL2, (int(ac.x),int(ac.y)), br)
            pygame.draw.circle(SCREEN, WHITE, (int(ac.x),int(ac.y)), br, max(2,S(4)))
            pygame.draw.circle(SCREEN, RED, (int(knob.x),int(knob.y)), kr)
            pygame.draw.circle(SCREEN, WHITE, (int(knob.x),int(knob.y)), kr, max(2,S(3)))
            draw_text("SOCO" if self.player.character==REGULAR_DUDE_KEY else "MIRA", FONT_S, DARK, (int(knob.x),int(knob.y)), True)
        else:
            attack_label = "FACAS" if (self.player.character == HANK_KEY and self.domain_active) else "ATK"
            circle_button(self.buttons["attack"], attack_label, RED)
        circle_button(self.buttons["dash"], "DASH", CYAN)
        if self.player.character == "Sans":
            if self.bad_time_active:
                soul_cost=self.player.max_stamina*0.10
                soul_color=CYAN if self.player.stamina>=soul_cost and not self.player.sans_exhausted else PANEL2
                circle_button(self.control_rect("parry"), "ALMA", soul_color)
            else:
                blast_color = CYAN if self.player.sans_blaster_cd <= 0 and not self.player.sans_exhausted else PANEL2
                circle_button(self.control_rect("parry"), "BLAST", blast_color)
        elif self.player.character == MAHORAGA_MODULE_KEY:
            rr=self.control_rect("parry"); center=pygame.Vector2(rr.center); rad=min(rr.w,rr.h)//2
            ready=self.player.mahoraga_adapt_cd<=0 and self.player.mahoraga_adapt_timer<=0
            col=YELLOW if ready or self.player.mahoraga_adapt_timer>0 else PANEL2
            pygame.draw.circle(SCREEN,col,(int(center.x),int(center.y)),rad)
            pygame.draw.circle(SCREEN,WHITE,(int(center.x),int(center.y)),rad,max(2,S(3)))
            ang=pygame.time.get_ticks()/180.0 if self.player.mahoraga_adapt_timer>0 else 0.0
            wr=int(rad*0.72); pygame.draw.circle(SCREEN,DARK,(int(center.x),int(center.y)),wr,max(1,S(3)))
            for i in range(8):
                d=vec_from_angle(ang+i*math.tau/8); pygame.draw.line(SCREEN,DARK,center+d*max(2,S(4)),center+d*wr,max(1,S(3)))
            draw_text("ADAPT",FONT_S,DARK,(int(center.x),int(center.y)),True)
        else:
            circle_button(self.control_rect("parry"), "PARRY", YELLOW)
        sans_ready = self.player.character == "Sans" and (self.domain_charge >= 100 or self.player.stamina < self.player.max_stamina*0.50) and not self.player.sans_exhausted
        if self.player.character=="Vinicius 13":
            minis=sum(1 for t in self.vinicius_turrets if not t.dead and not t.mega)
            can_mini=self.vinicius_turret_tokens>0 and minis<10
            can_mega=minis>=5 and self.vinicius_scrap>=20
            dom_color=YELLOW if (can_mini or can_mega or self.domain_held) else PANEL2
            dom_label="MEGA" if self.domain_held and self.player.vinicius_ult_hold>=0.55 else "TORRE"
        elif self.player.character==REGULAR_DUDE_KEY:
            dom_color=ORANGE if self.domain_charge>=100 else PANEL2; dom_label="ULT"
        elif self.player.character==KIRA_KEY:
            kira_btd_ready=(self.domain_charge>=100 and not self.player.kira_bites_used_wave) or self.player.kira_bites_armed
            dom_color=PURPLE if kira_btd_ready else PANEL2; dom_label="BTD"
        else:
            dom_color = PURPLE if ((self.domain_charge >= 100 and self.player.character not in ("Glonk", "Glonk 100% Power")) or sans_ready) else PANEL2
            dom_label = "BAD" if self.player.character == "Sans" else ("MAHO" if self.player.character == "Potential Man" else ("ART" if self.player.character==HANK_KEY else ("ULT" if self.player.character==SUKUNA_KEY else "DOM")))
        if self.player.character==REGULAR_DUDE_KEY:
            rr=self.buttons["domain"]; cc=pygame.Vector2(rr.center); br=min(rr.w,rr.h)//2; kr=max(S(28),int(br*0.34))
            av=self.player.regular_ult_aim if self.domain_held and self.player.regular_ult_active else pygame.Vector2(0,0)
            if av.length_squared()>1.0: av=av.normalize()
            kk=cc+av*(br-kr-S(5))
            pygame.draw.circle(SCREEN,PANEL2,(int(cc.x),int(cc.y)),br)
            pygame.draw.circle(SCREEN,WHITE,(int(cc.x),int(cc.y)),br,max(2,S(4)))
            pygame.draw.circle(SCREEN,dom_color,(int(kk.x),int(kk.y)),kr)
            pygame.draw.circle(SCREEN,WHITE,(int(kk.x),int(kk.y)),kr,max(2,S(3)))
            draw_text("SERIO",FONT_S,DARK if dom_color!=PANEL2 else WHITE,(int(kk.x),int(kk.y)),True)
        else:
            circle_button(self.buttons["domain"], dom_label, dom_color)
        if self.player.character==KIRA_KEY:
            marked=len(self.player._kira_marked_targets(self))
            sha_active=any(isinstance(s,KiraSheerHeartAttack) and not getattr(s,"dead",False) for s in self.summons)
            specs=[
                ("detonate","DET",PINK,marked>0,0.0),
                ("sha","SHA",YELLOW,self.player.kira_sha_cd<=0 and not sha_active,self.player.kira_sha_cd),
            ]
            for key,label,col,ready,cd in specs:
                rr=self.kira_buttons.get(key)
                if rr is None: continue
                circle_button(rr,label,col if ready else PANEL2)
                if cd>0:
                    draw_text(f"{cd:.1f}",SHOP_FONT_TINY,WHITE,(rr.centerx,rr.bottom-S(12)),True)
            if marked>0 and self.kira_buttons.get("detonate") is not None:
                rr=self.kira_buttons["detonate"]
                draw_text(f"BOMBAS {marked}/{self.player.kira_mark_limit}",SHOP_FONT_TINY,PINK,(rr.centerx,rr.y-S(16)),True)
            if self.player.kira_bites_armed:
                draw_text(f"BITES THE DUST {self.player.kira_bites_timer:.1f}s",SHOP_FONT_TINY,PINK,(self.buttons["domain"].centerx,self.buttons["domain"].y-S(18)),True)
        pygame.draw.rect(SCREEN, PANEL2, self.buttons["pause"], border_radius=S(16))
        draw_text("PAUSE", FONT_S, WHITE, self.buttons["pause"].center, True)
        if self.mode == "afk":
            colors = {"DUMMY": PANEL2, "INIMIGO": ORANGE, "BOSS": RED, "TIRO": PINK, "DOM": PURPLE, "UP": BLUE}
            for label, rect in self.afk_buttons.items():
                pygame.draw.rect(SCREEN, colors[label], rect, border_radius=S(12))
                draw_text(label, FONT_S, WHITE, rect.center, True)

    def draw_father_wave_fx(self, offset):
        if self.father_wave_fx_timer <= 0 or self.father_wave_fx_radius <= 0:
            return
        progress = 1.0 - self.father_wave_fx_timer / max(0.01, self.father_wave_fx_total)
        center = self.father_wave_fx_center + offset
        radius = int(self.father_wave_fx_radius * (0.70 + 0.30*progress))
        pygame.draw.circle(SCREEN, WHITE, (int(center.x), int(center.y)), radius, max(2,S(8)))
        pygame.draw.circle(SCREEN, YELLOW, (int(center.x), int(center.y)), max(1,radius-S(12)), max(1,S(3)))

    def draw_atlas_aim_preview(self, offset):
        """Pre-visualizacao do Atlas: trajeto do projetil + area de atracao no ponto final."""
        if self.player.character != "Atlas" or self.domain_active or not self.aim_active:
            return
        d=pygame.Vector2(self.aim_vector)
        if d.length_squared()<=0.01: d=pygame.Vector2(self.player.facing)
        if d.length_squared()<=0.0001: d=pygame.Vector2(1,0)
        d=d.normalize()
        origin_world=pygame.Vector2(self.player.pos)+d*(self.player.radius+S(28))
        arena_radius=math.hypot(W*0.5,H*0.5)
        max_dist=max(S(220),arena_radius*0.40)
        pull_r=max(S(103),arena_radius*0.155)
        end_world=origin_world+d*max_dist
        origin=origin_world+offset; end=end_world+offset
        normal=pygame.Vector2(-d.y,d.x); half_w=max(S(10),int(self.player.radius*0.38))
        col=(95,145,255); bright=(150,195,255)
        pygame.draw.line(SCREEN,col,origin+normal*half_w,end+normal*half_w,max(1,S(2)))
        pygame.draw.line(SCREEN,col,origin-normal*half_w,end-normal*half_w,max(1,S(2)))
        length=max(1.0,(end-origin).length()); pieces=max(4,min(16,int(length/max(S(45),1))))
        for i in range(0,pieces,2):
            a=origin+(end-origin)*(i/pieces); b=origin+(end-origin)*(min(pieces,i+1)/pieces)
            pygame.draw.line(SCREEN,bright,a,b,max(1,S(2)))
        pygame.draw.circle(SCREEN,col,(int(end.x),int(end.y)),int(pull_r),max(2,S(3)))
        pygame.draw.circle(SCREEN,bright,(int(end.x),int(end.y)),max(S(7),int(self.player.radius*0.25)),max(1,S(2)))

    def draw_hank_aim_preview(self, offset):
        """Mira leve do Hank: 2 bordas + eixo, sem criar Surface alpha gigante por frame."""
        if self.player.character != HANK_KEY or self.domain_active or not self.aim_active:
            return
        d=pygame.Vector2(self.aim_vector)
        if d.length_squared()<=0.01: d=pygame.Vector2(self.player.facing)
        if d.length_squared()<=0.0001: d=pygame.Vector2(1,0)
        d=d.normalize()
        origin_world=pygame.Vector2(self.player.pos)+d*(self.player.radius+S(10))
        end_world=hank_range_endpoint(origin_world,d)
        origin=origin_world+offset; end=end_world+offset
        normal=pygame.Vector2(-d.y,d.x)
        half_w=max(S(20),int(self.player.radius*0.90))
        faint=(145,145,155); brighter=(195,195,205)
        pygame.draw.line(SCREEN,faint,origin+normal*half_w,end+normal*half_w,max(1,S(2)))
        pygame.draw.line(SCREEN,faint,origin-normal*half_w,end-normal*half_w,max(1,S(2)))
        # eixo tracejado: muito mais barato que um overlay 2340x1080 todo frame.
        length=max(1.0,(end-origin).length())
        pieces=max(3,min(12,int(length/max(S(55),1))))
        for i in range(0,pieces,2):
            a=origin+(end-origin)*(i/pieces); b=origin+(end-origin)*(min(pieces,i+1)/pieces)
            pygame.draw.line(SCREEN,brighter,a,b,max(1,S(2)))
        pygame.draw.circle(SCREEN,brighter,(int(end.x),int(end.y)),max(S(6),int(self.player.radius*0.32)),max(1,S(2)))

    def draw_hank_artillery(self, offset):
        if getattr(self,"hank_domain_active",False) and getattr(self,"hank_cannon_pos",None) is not None:
            p=self.hank_cannon_pos+offset; pygame.draw.circle(SCREEN,DARK,(int(p.x),int(p.y)),S(34)); pygame.draw.circle(SCREEN,RED,(int(p.x),int(p.y)),S(34),max(2,S(5))); pygame.draw.rect(SCREEN,(150,150,155),(int(p.x-S(8)),int(p.y-S(55)),S(16),S(62)),border_radius=S(5)); draw_text("CANHAO",FONT_S,RED,(p.x,p.y+S(48)),True)
        for fx in getattr(self,"hank_explosions",[]):
            ratio=clamp(1.0-fx["timer"]/max(0.01,fx["total"]),0,1); p=fx["pos"]+offset; r=int(fx["radius"]*(0.35+0.65*ratio))
            pygame.draw.circle(SCREEN,RED if fx.get("artillery") else ORANGE,(int(p.x),int(p.y)),max(1,r),max(2,S(9))); pygame.draw.circle(SCREEN,YELLOW,(int(p.x),int(p.y)),max(1,int(r*.65)),max(1,S(4)))
        for mark in getattr(self, "hank_artillery_queue", []):
            if mark.get("done", False): continue
            p = mark["pos"] + offset; img = hank_target_surface(max(S(110), int(mark["radius"]*1.55)))
            if img is not None: SCREEN.blit(img, img.get_rect(center=(int(p.x), int(p.y))))
            else:
                pygame.draw.circle(SCREEN, RED, (int(p.x), int(p.y)), int(mark["radius"]*0.72), max(2,S(4))); pygame.draw.line(SCREEN, RED, (int(p.x-S(28)), int(p.y)), (int(p.x+S(28)), int(p.y)), max(2,S(3))); pygame.draw.line(SCREEN, RED, (int(p.x), int(p.y-S(28))), (int(p.x), int(p.y+S(28))), max(2,S(3)))

    def draw_playing(self):
        if getattr(self, "mahoraga_cutscene_active", False):
            self.draw_mahoraga_cutscene()
            return
        if getattr(self, "sukuna_cutscene_active", False):
            self.draw_sukuna_cutscene()
            return
        # Teleporte do Sans: por 0,5s absolutamente nada do mundo/HUD aparece.
        # Somente os controles permanecem visiveis e clicaveis.
        if getattr(self,"sans_teleport_blackout",0.0) > 0.0:
            SCREEN.fill((0,0,0))
            self.draw_controls()
            return
        self.draw_bg()
        offset = self.camera_offset()
        self.draw_domain_zone(offset)
        # Sukuna: zona marcada entre o primeiro e o segundo toque do ULT.
        if self.player.character == SUKUNA_KEY and getattr(self,"sukuna_fuuga_aiming",False):
            draw_text("FUUGA: TOQUE NA ARENA PARA ESCOLHER O ALVO",FONT_S,SUKUNA_FIRE,(W/2,S(142)),True)
        if self.player.character == SUKUNA_KEY and getattr(self,"sukuna_ult_marked",False):
            c=self.sukuna_ult_center+offset; r=int(self.sukuna_ult_radius)
            pygame.draw.circle(SCREEN,SUKUNA_FIRE,(int(c.x),int(c.y)),r,max(2,S(4)))
            pygame.draw.line(SCREEN,SUKUNA_FIRE,(int(c.x-S(22)),int(c.y)),(int(c.x+S(22)),int(c.y)),max(1,S(3)))
            pygame.draw.line(SCREEN,SUKUNA_FIRE,(int(c.x),int(c.y-S(22))),(int(c.x),int(c.y+S(22))),max(1,S(3)))
        if getattr(self,"sukuna_fuuga_fx",None):
            fx=self.sukuna_fuuga_fx; ratio=clamp(fx["timer"]/max(0.01,fx["total"]),0,1)
            a=fx["start"]+offset; b=fx["end"]+offset
            pygame.draw.line(SCREEN,SUKUNA_FIRE,a,b,max(S(12),int(S(32)*ratio)))
            pygame.draw.line(SCREEN,YELLOW,a,b,max(S(5),int(S(12)*ratio)))
            rr=int(fx["radius"]*(1.0-ratio*0.35))
            pygame.draw.circle(SCREEN,SUKUNA_FIRE,(int(b.x),int(b.y)),rr,max(2,S(10)))
            pygame.draw.circle(SCREEN,YELLOW,(int(b.x),int(b.y)),max(S(18),int(rr*.72)),max(2,S(5)))
        self.draw_father_wave_fx(offset)
        self.draw_atlas_aim_preview(offset)
        self.draw_hank_aim_preview(offset)
        self.draw_hank_artillery(offset)
        for f in self.forge_fire_trails:
            f.draw(offset)
        for plant in self.planted_pineapples:
            plant.draw(offset)
        for d in self.drops:
            d.draw(offset)
        for p in self.projectiles:
            p.draw(offset)
        for bone in self.sans_bones:
            bone.draw(offset)
        for bone in self.sans_soul_wall_bones:
            bone.draw(offset)
        if self.game_mode=="sans_trial":
            try:
                for bone in self.sans_boss_bones:
                    bone.draw(offset)
                for blast in self.sans_boss_blasters:
                    blast.draw(offset)
            except Exception as exc:
                _write_sans_trial_crash("hazard_draw",exc)
                self.sans_trial_error=repr(exc)
                self.sans_boss_bones=[]; self.sans_boss_blasters=[]
        else:
            for bone in self.sans_boss_bones:
                bone.draw(offset)
            for blast in self.sans_boss_blasters:
                blast.draw(offset)
        for plant in self.sans_blaster_plants:
            draw_sans_blaster_plant(SCREEN, plant, offset)
        for fx in self.sans_blaster_fx:
            start=fx["start"]+offset; end=fx["end"]+offset
            ratio=clamp(fx["timer"]/max(0.01,fx["total"]),0,1)
            width=max(S(8),int(fx["width"]*(0.35+0.65*ratio)))
            # Feixe unico azul: uma unica camada reduz draw calls e travadas no Android.
            pygame.draw.line(SCREEN,CYAN,start,end,width)
        for summon in self.summons:
            summon.draw(offset)
        for a in self.orbital_anas:
            a.draw(offset)
        for serv in self.servants:
            serv.draw(offset)
        for summon in self.potential_summons:
            summon.draw(offset)
        for wall in self.vinicius_walls: wall.draw(offset)
        for turret in self.vinicius_turrets: turret.draw(offset)
        for rock in self.vinicius_rocks: rock.draw(offset)
        for e in self.enemies:
            e.draw(offset)
        if self.player.character==KIRA_KEY:
            marked=[e for e in self.enemies if not getattr(e,"dead",False) and getattr(e,"kira_bomb_mark",False)]
            maho=getattr(self,"mahoraga",None)
            if maho is not None and not getattr(maho,"dead",True) and getattr(maho,"kira_bomb_mark",False): marked.append(maho)
            for e in marked:
                bp=e.pos+offset+pygame.Vector2(0,-getattr(e,"radius",S(20))-S(20)); rr=max(S(7),int(S(9)))
                pygame.draw.circle(SCREEN,DARK,(int(bp.x),int(bp.y)),rr); pygame.draw.circle(SCREEN,PINK,(int(bp.x),int(bp.y)),rr,max(1,S(2)))
                pygame.draw.line(SCREEN,YELLOW,(int(bp.x+rr*.45),int(bp.y-rr*.65)),(int(bp.x+rr),int(bp.y-rr*1.20)),max(1,S(2)))
        self.draw_kira_explosion_fx(offset)
        self.draw_kira_rewind_fx(offset)
        for p in self.particles:
            p.draw(offset)
        self.player.draw(offset, self)
        if self.divine_burst_fx:
            fx=self.divine_burst_fx; ratio=clamp(fx["timer"]/fx["total"],0,1); c=fx["center"]+offset
            pygame.draw.circle(SCREEN,PURPLE,(int(c.x),int(c.y)),int(fx["radius"]*(1.0-0.25*ratio)),max(3,S(14)))
        for d in self.damage_texts:
            d.draw(offset)
        self.draw_hud()

        if self.game_mode=="arena_survival":
            if self.arena_inset>0:
                safe=pygame.Rect(int(self.arena_inset),int(S(175)+self.arena_inset*0.35),int(W-self.arena_inset*2),int(H-S(520)-self.arena_inset*0.70))
                pygame.draw.rect(SCREEN,ORANGE,safe,max(2,S(5)),border_radius=S(12))
            for h in self.arena_hazards:
                pp=h["pos"]+offset
                col=RED if h.get("boom") else ORANGE
                pygame.draw.circle(SCREEN,col,(int(pp.x),int(pp.y)),int(h["r"]),max(2,S(6)))
            if self.arena_reward_cards:
                self.arena_reward_rects=[]
                cw=S(360); ch=S(145); gap=S(18); total=len(self.arena_reward_cards)*cw+(len(self.arena_reward_cards)-1)*gap; xx=(W-total)/2; yy=S(195)
                for i,card in enumerate(self.arena_reward_cards):
                    r=pygame.Rect(xx+i*(cw+gap),yy,cw,ch); pygame.draw.rect(SCREEN,PANEL,r,border_radius=S(15)); pygame.draw.rect(SCREEN,YELLOW,r,max(2,S(4)),border_radius=S(15));
                    draw_text(card[1],FONT_S,YELLOW,(r.centerx,r.y+S(34)),True); draw_wrapped_text(card[2],FONT_S,WHITE,pygame.Rect(r.x+S(12),r.y+S(60),r.w-S(24),S(70)),2,True,2); self.arena_reward_rects.append((r,card))
                draw_text("ESCOLHA RAPIDO - A ARENA NAO PAUSA",FONT_S,RED,(W/2,yy-S(26)),True)
        if self.game_mode=="infinite" and self.infinite_curses:
            draw_text(f"MALDICOES {len(self.infinite_curses)}",FONT_S,PURPLE,(W/2,S(120)),True)
        elif self.game_mode=="evolution" and self.evolution_traits:
            names=[next((x[1] for x in EVOLUTION_TRAITS if x[0]==k),k) for k in self.evolution_traits[-3:]]
            draw_text("EVOLUCOES: "+" / ".join(names),FONT_S,GREEN,(W/2,S(120)),True)
        elif self.game_mode=="rogue" and self.rogue_rule:
            nm=next((x[1] for x in ROGUE_RULES if x[0]==self.rogue_rule),self.rogue_rule); draw_text("ROGUE: "+nm,FONT_S,PURPLE,(W/2,S(120)),True)
        elif self.game_mode=="boss_rush" and self.boss_heritages:
            draw_text("HERANCAS: "+" > ".join(self.boss_heritages[-4:]),FONT_S,RED,(W/2,S(120)),True)

        # GLONK, O ULTIMO: barra gigante de boss sem trocar o inimigo por outra entidade.
        glonk_boss=next((e for e in self.enemies if isinstance(e,GlonkEnemy) and not e.dead and (e.phase=="boss" or e.death_sequence)),None)
        if glonk_boss is not None:
            bw=int(W*0.56); bh=S(28); bx=(W-bw)//2; by=S(145)
            pygame.draw.rect(SCREEN,DARK,(bx,by,bw,bh),border_radius=S(10))
            pygame.draw.rect(SCREEN,GREEN,(bx,by,bw*clamp(glonk_boss.hp/max(1,glonk_boss.max_hp),0,1),bh),border_radius=S(10))
            pygame.draw.rect(SCREEN,WHITE,(bx,by,bw,bh),width=max(2,S(3)),border_radius=S(10))
            draw_text("GLONK, O ULTIMO",FONT_M,GREEN,(W/2,by-S(26)),True)

        self.draw_controls()

        if self.glonk_event_timer > 0:
            if self.glonk_event_stage == "spawn":
                draw_text("Um Glonk apareceu.",FONT_L,GREEN,(W/2,H*0.24),True)
            elif self.glonk_event_stage == "trapped":
                draw_text("Glonk nao tem mais para onde fugir.",FONT_L,WHITE,(W/2,H*0.24),True)
            elif self.glonk_event_stage == "stopped":
                draw_text("Glonk decidiu parar de fugir.",FONT_L,GREEN,(W/2,H*0.24),True)
            elif self.glonk_event_stage == "boss":
                draw_text("GLONK",FONT_XL,GREEN,(W/2,H*0.27),True)
                draw_text("O ULTIMO",FONT_L,WHITE,(W/2,H*0.35),True)
                draw_text("Ele correu o suficiente.",FONT_M,GREEN,(W/2,H*0.42),True)

        if self.wave_banner > 0 and self.mode == "arena":
            if self.game_mode=="boss_rush": banner=f"BOSS RUSH {self.wave}/{self.boss_rush_sequence_length()}"; bcolor=RED
            elif self.game_mode=="one_vs_all": banner=f"RIVAL {self.wave}/{max(1,len(self.one_vs_all_roster))}"; bcolor=YELLOW
            elif self.game_mode=="arena_survival": banner="ARENA SEM DESCANSO"; bcolor=ORANGE
            else:
                sp=sin_encounter_for_wave(self.wave)
                if sp:
                    cfg,arch=sp; banner=("ARCEBISPO DA " if arch else "PECADO: ")+cfg["name"]; bcolor=cfg["color"]
                else:
                    banner="BOSS" if self.wave%5==0 else f"ONDA {self.wave}"; bcolor=WHITE
            draw_text(banner,FONT_XL,bcolor,(W/2,H*0.36),True)
        if self.unlock_notice_timer > 0:
            draw_text(self.unlock_notice, FONT_L, PURPLE, (W/2,H*0.20), True)
        if self.synergy_timer > 0:
            draw_text("《 SINERGIA DESPERTADA 》", FONT_M, YELLOW, (W/2,H*0.27), True)
            draw_text(self.synergy_name, FONT_L, WHITE, (W/2,H*0.33), True)
        if self.boss_domain_message_timer > 0:
            draw_text("DOMINIO DO BOSS", FONT_M, RED, (W/2, H*0.40), True)
            draw_text(self.boss_domain_message, FONT_S, WHITE, (W/2, H*0.445), True)
        if self.domain_clash_active:
            draw_text("CLASH DE DOMINIO", FONT_L, YELLOW, (W/2, H*0.475), True)
            # Centro da barra = 0 (limite para vencer). Ela cai 4 pontos/s mesmo sem sofrer dano.
            bw, bh = S(430), S(20)
            br = pygame.Rect(W/2-bw/2, H*0.525, bw, bh)
            pygame.draw.rect(SCREEN, PANEL2, br, border_radius=max(2,S(8)))
            ratio = clamp((self.domain_clash_score + 60.0) / 120.0, 0.0, 1.0)
            if ratio > 0:
                fill = pygame.Rect(br.x, br.y, int(br.w*ratio), br.h)
                pygame.draw.rect(SCREEN, YELLOW if self.domain_clash_score >= 0 else RED, fill, border_radius=max(2,S(8)))
            pygame.draw.rect(SCREEN, WHITE, br, max(1,S(2)), border_radius=max(2,S(8)))
            pygame.draw.line(SCREEN, WHITE, (br.centerx,br.y-S(3)), (br.centerx,br.bottom+S(3)), max(1,S(2)))
            draw_text(f"{self.domain_clash_timer:.1f}s   PODER {self.domain_clash_score:+.1f}", FONT_S, WHITE, (W/2, H*0.565), True)
        elif self.clash_result_timer > 0:
            draw_text(self.clash_result, FONT_M, YELLOW if "SOBERANO" in self.clash_result else RED, (W/2, H*0.49), True)
        if self.flash_screen > 0:
            surf = pygame.Surface((W,H), pygame.SRCALPHA)
            surf.fill((255,255,255,int(160*self.flash_screen/0.22)))
            SCREEN.blit(surf,(0,0))
        self.draw_domain_cutscene()

    def draw_menu(self):
        # V15.23: cada tema comprado agora muda de verdade a identidade do menu.
        theme_key=str(SAVE.get("menu_theme","default") or "default")
        theme=current_menu_theme(); SCREEN.fill(theme["bg"]); accent=theme["accent"]; secondary=theme["secondary"]
        ticks=pygame.time.get_ticks()

        # RODA ETERNA: roda dourada gigante, marcas circulares e CLANK a cada 10s.
        if theme_key=="mahoraga":
            c=pygame.Vector2(W*0.52,H*0.56); rr=max(S(260),int(min(W,H)*0.39)); ang=ticks/1850.0
            gold=(218,174,46); gold2=(255,215,86); dim=(72,58,20)
            for frac in (0.26,0.42,0.60,0.80):
                pygame.draw.circle(SCREEN,dim,(int(c.x),int(c.y)),max(1,int(rr*frac)),max(1,S(2)))
            pygame.draw.circle(SCREEN,gold,(int(c.x),int(c.y)),rr,max(2,S(8)))
            pygame.draw.circle(SCREEN,(114,86,25),(int(c.x),int(c.y)),max(1,rr-S(20)),max(2,S(3)))
            for i in range(8):
                d=vec_from_angle(ang+i*math.tau/8); a=c+d*(rr*0.28); b=c+d*rr
                pygame.draw.line(SCREEN,gold,(int(a.x),int(a.y)),(int(b.x),int(b.y)),max(2,S(8)))
                tip=c+d*rr; pygame.draw.circle(SCREEN,gold2,(int(tip.x),int(tip.y)),S(11),max(2,S(3)))
            AUDIO.play_external_sfx("mahoraga_wheel",0.72,10000)

        # GLONK: um bando inteiro corre por tras dos cards.
        elif theme_key=="glonk":
            for i in range(11):
                direction=-1 if i%3==0 else 1
                speed=S(70+13*(i%5)); span=W+S(220); phase=(ticks/1000.0)*speed
                x=((phase*direction+i*S(247))%span)-S(110)
                if direction<0: x=W-x
                y=S(175+(i%5)*155 + 26*math.sin(ticks/500.0+i))
                r=S(22+(i%3)*4); body=(24,112,52) if i%2 else (35,145,64)
                pygame.draw.circle(SCREEN,body,(int(x),int(y)),r)
                pygame.draw.circle(SCREEN,(7,25,12),(int(x),int(y)),r,max(1,S(2)))
                eye_y=int(y-S(5)); pygame.draw.circle(SCREEN,WHITE,(int(x-S(7)),eye_y),max(2,S(3))); pygame.draw.circle(SCREEN,WHITE,(int(x+S(7)),eye_y),max(2,S(3)))
                pygame.draw.line(SCREEN,(30,84,44),(int(x-direction*S(34)),int(y+S(18))),(int(x-direction*S(58)),int(y+S(18))),max(1,S(3)))

        # RETRO: grid/scanlines + fonte monoespacada usada nos textos principais.
        elif theme_key=="retro":
            grid=(58,43,29); scan=(38,30,23)
            for x in range(0,W,max(S(76),1)): pygame.draw.line(SCREEN,grid,(x,0),(x,H),max(1,S(1)))
            for y in range(0,H,max(S(76),1)): pygame.draw.line(SCREEN,grid,(0,y),(W,y),max(1,S(1)))
            for y in range(0,H,max(S(16),1)): pygame.draw.line(SCREEN,scan,(0,y),(W,y),max(1,S(1)))
            pygame.draw.rect(SCREEN,ORANGE,pygame.Rect(S(22),S(18),W-S(44),H-S(36)),max(2,S(4)))

        # BAD TIME: ossos e linhas azuis discretos; a musica propria e cuidada pelo AudioManager.
        elif theme_key=="sans":
            for i in range(9):
                xx=int((i+1)*W/10); drift=S(20)*math.sin(ticks/620.0+i)
                yy=S(180+(i%4)*190)+drift
                col=CYAN if i%3==0 else (125,145,165)
                pygame.draw.line(SCREEN,col,(xx,yy-S(42)),(xx,yy+S(42)),max(2,S(7)))
                pygame.draw.circle(SCREEN,col,(xx,int(yy-S(48))),S(11),max(2,S(4)))
                pygame.draw.circle(SCREEN,col,(xx,int(yy+S(48))),S(11),max(2,S(4)))
            pygame.draw.line(SCREEN,(28,68,92),(0,S(145)),(W,S(145)),max(1,S(3)))

        # Linhas decorativas base.
        for i in range(5):
            yy=S(150+i*165); pygame.draw.line(SCREEN,(28,30,38),(CONTROL_SAFE_X,yy),(W-CONTROL_SAFE_X,yy),max(1,S(1)))

        title="Derrote o Gordo do Pai do Kayk"
        menu_title_font=RETRO_FONT_TITLE if theme_key=="retro" else FONT_TITLE
        title_img=menu_title_font.render(title,True,WHITE); max_w=W-SAFE*4
        if title_img.get_width()>max_w:
            ratio=max_w/title_img.get_width(); title_img=pygame.transform.smoothscale(title_img,(int(title_img.get_width()*ratio),int(title_img.get_height()*ratio)))
        SCREEN.blit(title_img,title_img.get_rect(center=(W/2,S(55))))
        subtitle="Ou seja devorado...."; equipped_title=str(SAVE.get("equipped_title","") or "")
        sub_font=RETRO_FONT_S if theme_key=="retro" else FONT_FANCY_S
        draw_text(subtitle,sub_font,GRAY,(W/2,S(108)),True)

        # Perfil compacto no canto superior esquerdo.
        profile=pygame.Rect(S(48),S(28),S(350),S(110)); profile_accent=PROFILE_COLORS[int(SAVE.get("profile_color",0) or 0)%len(PROFILE_COLORS)]
        self._ui_shape(profile,profile_accent,fill=(14,16,22),style=1,width=3,featured=False)
        avatar_r=pygame.Rect(profile.x+S(14),profile.y+S(14),S(82),S(82))
        self._draw_profile_avatar(avatar_r,int(SAVE.get("profile_avatar",0) or 0),True)
        pname=str(SAVE.get("profile_name","JOGADOR") or "JOGADOR")[:18]; rp=int(SAVE.get("profile_rank_points",0) or 0); _,rn,rc=profile_rank_info(rp)
        pname_box=pygame.Rect(profile.x+S(112),profile.y+S(12),profile.w-S(124),S(48))
        rank_box=pygame.Rect(profile.x+S(112),profile.y+S(61),profile.w-S(124),S(34))
        draw_fitted_text(pname,[FONT_M,FONT_S,SHOP_FONT_XS],WHITE,pname_box,False)
        draw_fitted_text(f"{rn} • {rp:,} R.P".replace(",","."),[FONT_S,SHOP_FONT_XS,SHOP_FONT_TINY],rc,rank_box,False)
        self.menu_profile_rect=profile

        # Titulo equipado agora parece titulo de verdade: banner grande, borda, sombra e pulso.
        if equipped_title:
            shown=equipped_title.replace("🔥","").strip(); title_font=RETRO_FONT_M if theme_key=="retro" else FONT_M
            tw=title_font.size(shown)[0]; bw=min(W-S(240),max(S(420),tw+S(110))); bh=S(64); bx=W/2-bw/2; by=S(121)
            _,title_meta=title_catalog_entry_by_value(equipped_title)
            if title_meta and title_meta.get("chromatic"):
                edge=chromatic_color()
                text_col=edge
            else:
                base_col=title_display_color(equipped_title,accent); q=.5+.5*math.sin(ticks/300.0); edge=(min(255,int(base_col[0]+45*q)),min(255,int(base_col[1]+45*q)),min(255,int(base_col[2]+45*q))); text_col=WHITE
            banner=pygame.Rect(int(bx),by,int(bw),bh); pygame.draw.rect(SCREEN,(10,11,16),banner,border_radius=S(18)); pygame.draw.rect(SCREEN,edge,banner,max(2,S(4)),border_radius=S(18))
            img=title_font.render(shown,True,text_col); max_text=banner.w-S(70)
            if img.get_width()>max_text:
                ratio=max_text/img.get_width(); img=pygame.transform.smoothscale(img,(int(img.get_width()*ratio),int(img.get_height()*ratio)))
            shadow=img.copy(); shadow.fill((0,0,0),special_flags=pygame.BLEND_RGB_MULT); SCREEN.blit(shadow,shadow.get_rect(center=(banner.centerx+S(3),banner.centery+S(3))))
            SCREEN.blit(img,img.get_rect(center=banner.center))
            if "🔥" in equipped_title:
                fx=banner.right-S(38); fy=banner.centery+S(2); pygame.draw.polygon(SCREEN,ORANGE,[(fx,fy+S(15)),(fx-S(9),fy-S(2)),(fx,fy-S(19)),(fx+S(9),fy-S(2))]); pygame.draw.circle(SCREEN,YELLOW,(fx,fy+S(4)),S(6))

        def card(rect,color,label,sub="",style=0,hero=False,pulse=False):
            bg=theme["panel"]; edge=color
            if pulse:
                q=.5+.5*math.sin(pygame.time.get_ticks()/240.0); edge=(min(255,int(color[0]*(.82+.18*q)+35*q)),min(255,int(color[1]*(.82+.18*q)+35*q)),min(255,int(color[2]*(.82+.18*q)+35*q)))
            cut=max(S(8),min(S(28),rect.h//6))
            if style%5==0:
                pts=[(rect.x+cut,rect.y),(rect.right,rect.y),(rect.right,rect.bottom-cut),(rect.right-cut,rect.bottom),(rect.x,rect.bottom),(rect.x,rect.y+cut)]
                pygame.draw.polygon(SCREEN,bg,pts); pygame.draw.polygon(SCREEN,edge,pts,max(2,S(5 if hero else 3)))
            elif style%5==1:
                pygame.draw.rect(SCREEN,bg,rect,border_radius=S(24)); pygame.draw.rect(SCREEN,edge,rect,max(2,S(5 if hero else 3)),border_radius=S(24)); pygame.draw.rect(SCREEN,edge,pygame.Rect(rect.x,rect.y,S(13),rect.h),border_radius=S(6))
            elif style%5==2:
                pygame.draw.rect(SCREEN,bg,rect,border_radius=S(5)); pygame.draw.rect(SCREEN,edge,rect,max(2,S(4)),border_radius=S(5)); pygame.draw.line(SCREEN,edge,(rect.x+S(12),rect.bottom-S(15)),(rect.right-S(12),rect.bottom-S(15)),max(1,S(4)))
            elif style%5==3:
                pygame.draw.rect(SCREEN,bg,rect,border_radius=S(14)); pygame.draw.rect(SCREEN,edge,rect,max(2,S(3)),border_radius=S(14)); pygame.draw.polygon(SCREEN,edge,[(rect.x,rect.y),(rect.right-S(68),rect.y),(rect.right,rect.y+S(68)),(rect.x,rect.y+S(68))])
            else:
                pygame.draw.rect(SCREEN,bg,rect,border_radius=S(10)); pygame.draw.rect(SCREEN,edge,rect,max(2,S(3)),border_radius=S(10)); pygame.draw.rect(SCREEN,edge,rect.inflate(-S(14),-S(14)),max(1,S(2)),border_radius=S(6))
            if theme_key=="retro":
                label_font=RETRO_FONT_L if hero else (RETRO_FONT_M if rect.h>=S(130) and rect.w>=S(300) else RETRO_FONT_S)
                sub_font_card=RETRO_FONT_S
            else:
                label_font=FONT_L if hero else (FONT_M if rect.h>=S(130) and rect.w>=S(300) else FONT_S)
                sub_font_card=SHOP_FONT_XS
            ly=rect.y+S(28 if hero else 18)
            remaining=max(1,rect.bottom-S(16)-ly)
            label_h=remaining if not sub else max(S(28),int(remaining*(0.48 if hero else 0.55)))
            label_box=pygame.Rect(rect.x+S(22),ly,rect.w-S(44),label_h)
            draw_responsive_text(label,[label_font,FONT_M,FONT_S,SHOP_FONT_XS,SHOP_FONT_TINY],
                                 WHITE,label_box,2,False,2,"center")
            if sub:
                sy=label_box.bottom+S(3)
                sub_box=pygame.Rect(rect.x+S(22),sy,rect.w-S(44),max(0,rect.bottom-sy-S(16)))
                draw_responsive_text(sub,[FONT_S,sub_font_card,SHOP_FONT_TINY],GRAY,sub_box,2,False,3 if hero else 2,"top")
            return rect

        # Coordenadas em linguagem DESIGN_W=2340 / DESIGN_H=1080.
        # V15.23.1: o mosaico começa mais abaixo para nao esmagar nome/subtitulo/titulo equipado.
        y0=S(220)
        start=pygame.Rect(S(70),y0,S(650),S(300)); card(start,RED,"JOGAR","Modos, Provações, Julgamentos e dificuldades.",0,True,True)
        shop=pygame.Rect(S(750),y0,S(590),S(220)); card(shop,YELLOW,"LOJA","Ofertas 24h, Relíquias, Cosméticos e Seu Zé.",3,True,True)
        characters_btn=pygame.Rect(S(750),y0+S(245),S(285),S(165)); card(characters_btn,DIVINE_BLUE,"PERSONAGENS","Ficha, expansão e kit.",1)
        passives=pygame.Rect(S(1055),y0+S(245),S(285),S(165)); card(passives,PASSIVE_RARITIES["divine"]["color"],"PASSIVAS","Roleta e slots.",4)

        upgrades=pygame.Rect(S(1370),y0,S(360),S(170)); card(upgrades,PURPLE,"UPGRADES","Catálogo de Power Ups.",2)
        bestiary=pygame.Rect(S(1755),y0,S(515),S(170)); card(bestiary,ORANGE,"BESTIÁRIO","Inimigos, bosses e treino.",1)
        missions=pygame.Rect(S(1370),y0+S(195),S(330),S(135)); card(missions,PURPLE,"MISSÕES","Progressão por personagem.",4)
        ach=pygame.Rect(S(1725),y0+S(195),S(545),S(135)); card(ach,YELLOW,"CONQUISTAS","Feitos, raridades e metas.",0)

        row2=y0+S(440)
        afk=pygame.Rect(S(70),row2,S(315),S(165)); card(afk,CYAN,"ZONA AFK","Teste builds e kits sem perder progresso.",1)
        news=pygame.Rect(S(405),row2,S(315),S(165)); card(news,CYAN,"NOVIDADES","Notas das versões e mudanças recentes.",3,pulse=True)
        forge=pygame.Rect(S(750),row2,S(280),S(165)); card(forge,ORANGE,"FORJA","Crie armas com materiais.",0)
        items=pygame.Rect(S(1050),row2,S(290),S(165)); card(items,CYAN,"ITENS","Materiais e boosts usáveis.",2)
        weapons=pygame.Rect(S(1370),row2,S(360),S(165)); card(weapons,PURPLE,"ARMAS","Equipe o arsenal fabricado.",3)
        settings_btn=pygame.Rect(S(1755),row2,S(515),S(100)); card(settings_btn,BLUE,"CONFIGURAÇÕES","Áudio, cutscenes e opções.",4)
        controls=pygame.Rect(S(1755),row2+S(115),S(250),S(95)); card(controls,BLUE,"CONTROLES","Edite o layout.",2)
        backup=pygame.Rect(S(2020),row2+S(115),S(250),S(95)); card(backup,GREEN,"BACKUP","Código de save.",0)

        bottom_y=row2+S(190)
        cheats=pygame.Rect(S(70),bottom_y,S(315),S(95)); card(cheats,RED,"CHEATS","Painel DEV e testes.",2)
        # Pequeno bloco de identidade da conta no centro inferior, em vez de outro monte de botoes.
        info=pygame.Rect(S(405),bottom_y,S(1335),S(95)); pygame.draw.rect(SCREEN,(18,20,27),info,border_radius=S(12)); pygame.draw.rect(SCREEN,accent,info,max(1,S(2)),border_radius=S(12))
        info_top=pygame.Rect(info.x+S(24),info.y+S(8),info.w-S(48),S(39))
        draw_fitted_text(f"MOEDAS {format_big_money(SAVE['coins'])}   •   MELHOR ONDA {SAVE['best_wave']}   •   KOs {SAVE['best_kills']}",[FONT_M,FONT_S,SHOP_FONT_XS],WHITE,info_top,False)
        relic=SAVE.get("equipped_relic",""); relic_name=SHOP_RELICS.get(relic,{}).get("name","NENHUMA") if relic else "NENHUMA"
        info_bottom=pygame.Rect(info.x+S(24),info.y+S(49),info.w-S(48),S(35))
        draw_fitted_text(f"RELIQUIA: {relic_name}   •   FRAG. DOMINIO {int(SAVE.get('domain_fragments',0))}   •   FRAG. RODA {int(SAVE.get('wheel_fragments',0))}",[FONT_S,SHOP_FONT_XS,SHOP_FONT_TINY],GRAY,info_bottom,False)

        # Mantem as mesmas referencias de clique; somente a apresentacao mudou.
        self.menu_start_rect=start; self.menu_afk_rect=afk; self.menu_shop_rect=shop; self.menu_upgrades_rect=upgrades; self.menu_bestiary_rect=bestiary; self.menu_passives_rect=passives; self.menu_controls_rect=controls; self.menu_characters_rect=characters_btn; self.menu_settings_rect=settings_btn; self.menu_news_rect=news; self.menu_achievements_rect=ach; self.menu_missions_rect=missions; self.menu_cheats_rect=cheats; self.menu_forge_rect=forge; self.menu_items_rect=items; self.menu_weapons_rect=weapons; self.menu_backup_rect=backup

        # O menu nao exibe mais mensagens permanentes de desbloqueio/progresso.

    def character_catalog_names(self):
        return list(CHARACTER_ORDER)+list(BETA_CHARACTER_ORDER)

    def _ui_theme_key(self):
        return str(SAVE.get("menu_theme","default") or "default")

    def _ui_fonts(self):
        retro = self._ui_theme_key() == "retro"
        return {
            "title": RETRO_FONT_TITLE if retro else FONT_L,
            "big": RETRO_FONT_M if retro else FONT_M,
            "body": RETRO_FONT_S if retro else FONT_S,
            "tiny": RETRO_FONT_S if retro else SHOP_FONT_XS,
        }

    def _draw_ui_background(self, title, subtitle="", accent=None):
        theme_key=self._ui_theme_key(); theme=current_menu_theme(); SCREEN.fill(theme["bg"])
        accent=accent or theme.get("accent",CYAN); ticks=pygame.time.get_ticks()
        if theme_key=="mahoraga":
            c=pygame.Vector2(W*0.82,H*0.32); rr=max(S(120),int(min(W,H)*0.17)); ang=ticks/2200.0
            gold=(198,156,38); dim=(62,50,18)
            for frac in (0.30,0.50,0.74):
                pygame.draw.circle(SCREEN,dim,(int(c.x),int(c.y)),max(1,int(rr*frac)),max(1,S(2)))
            pygame.draw.circle(SCREEN,gold,(int(c.x),int(c.y)),rr,max(2,S(6)))
            for i in range(8):
                d=vec_from_angle(ang+i*math.tau/8); a=c+d*(rr*0.30); b=c+d*rr
                pygame.draw.line(SCREEN,gold,(int(a.x),int(a.y)),(int(b.x),int(b.y)),max(1,S(4)))
        elif theme_key=="glonk":
            for i in range(7):
                direction=-1 if i%2 else 1; speed=S(52+8*(i%4)); span=W+S(180); phase=(ticks/1000.0)*speed
                x=((phase*direction+i*S(210))%span)-S(90)
                if direction<0: x=W-x
                y=S(132+(i%4)*130 + 18*math.sin(ticks/540.0+i))
                r=S(14+(i%3)*3)
                pygame.draw.circle(SCREEN,(26,120,58),(int(x),int(y)),r)
                pygame.draw.circle(SCREEN,(8,26,12),(int(x),int(y)),r,max(1,S(2)))
        elif theme_key=="retro":
            grid=(58,43,29); scan=(38,30,23)
            for x in range(0,W,max(S(76),1)): pygame.draw.line(SCREEN,grid,(x,0),(x,H),max(1,S(1)))
            for y in range(0,H,max(S(76),1)): pygame.draw.line(SCREEN,grid,(0,y),(W,y),max(1,S(1)))
            for y in range(0,H,max(S(16),1)): pygame.draw.line(SCREEN,scan,(0,y),(W,y),max(1,S(1)))
        elif theme_key=="sans":
            for i in range(7):
                xx=int((i+1)*W/8); drift=S(16)*math.sin(ticks/620.0+i); yy=S(136+(i%3)*180)+drift
                col=CYAN if i%3==0 else (116,136,160)
                pygame.draw.line(SCREEN,col,(xx,yy-S(30)),(xx,yy+S(30)),max(1,S(5)))
                pygame.draw.circle(SCREEN,col,(xx,int(yy-S(34))),S(9),max(1,S(3)))
                pygame.draw.circle(SCREEN,col,(xx,int(yy+S(34))),S(9),max(1,S(3)))
        for i in range(6):
            yy=S(140+i*155); pygame.draw.line(SCREEN,(26,28,36),(CONTROL_SAFE_X,yy),(W-CONTROL_SAFE_X,yy),max(1,S(1)))
        fonts=self._ui_fonts()
        # Painel primeiro, texto depois. A ordem antiga desenhava a faixa POR CIMA do titulo.
        top_rect=pygame.Rect(CONTROL_SAFE_X,S(22),W-CONTROL_SAFE_X*2,S(92))
        pygame.draw.rect(SCREEN,(12,13,18),top_rect,border_radius=S(16))
        pygame.draw.rect(SCREEN,accent,top_rect,max(1,S(3)),border_radius=S(16))
        title_box=pygame.Rect(top_rect.x+S(22),top_rect.y+S(5),top_rect.w-S(44),S(54))
        draw_responsive_text(title,[fonts["title"],fonts["big"],fonts["body"]],WHITE,title_box,1,True,1,"center")
        if subtitle:
            subtitle_box=pygame.Rect(top_rect.x+S(22),top_rect.y+S(60),top_rect.w-S(44),S(26))
            draw_fitted_text(subtitle,[fonts["body"],fonts["tiny"],SHOP_FONT_TINY],accent,subtitle_box,True)
        return theme

    def _ui_shape(self, rect, edge, fill=None, style=0, width=None, featured=False):
        fill = fill or (22,23,30)
        width = max(1, S(5 if featured else (width or 3)))
        cut=max(S(10),min(S(30),rect.h//6))
        if style % 6 == 0:
            pts=[(rect.x+cut,rect.y),(rect.right,rect.y),(rect.right,rect.bottom-cut),(rect.right-cut,rect.bottom),(rect.x,rect.bottom),(rect.x,rect.y+cut)]
            pygame.draw.polygon(SCREEN,fill,pts); pygame.draw.polygon(SCREEN,edge,pts,width)
        elif style % 6 == 1:
            pygame.draw.rect(SCREEN,fill,rect,border_radius=S(22)); pygame.draw.rect(SCREEN,edge,rect,width,border_radius=S(22)); pygame.draw.rect(SCREEN,edge,pygame.Rect(rect.x,rect.y,S(12),rect.h),border_radius=S(6))
        elif style % 6 == 2:
            pygame.draw.rect(SCREEN,fill,rect,border_radius=S(8)); pygame.draw.rect(SCREEN,edge,rect,width,border_radius=S(8)); pygame.draw.line(SCREEN,edge,(rect.x+S(12),rect.bottom-S(14)),(rect.right-S(12),rect.bottom-S(14)),max(1,S(4)))
        elif style % 6 == 3:
            pygame.draw.rect(SCREEN,fill,rect,border_radius=S(14)); pygame.draw.rect(SCREEN,edge,rect,width,border_radius=S(14)); pygame.draw.polygon(SCREEN,edge,[(rect.x,rect.y),(rect.right-S(62),rect.y),(rect.right,rect.y+S(62)),(rect.x,rect.y+S(62))])
        elif style % 6 == 4:
            pygame.draw.rect(SCREEN,fill,rect,border_radius=S(10)); pygame.draw.rect(SCREEN,edge,rect,width,border_radius=S(10)); pygame.draw.rect(SCREEN,edge,rect.inflate(-S(14),-S(14)),max(1,S(2)),border_radius=S(6))
        else:
            pts=[(rect.x,rect.y+cut),(rect.x+cut,rect.y),(rect.right-cut,rect.y),(rect.right,rect.y+cut),(rect.right,rect.bottom),(rect.x,rect.bottom)]
            pygame.draw.polygon(SCREEN,fill,pts); pygame.draw.polygon(SCREEN,edge,pts,width)
        if featured:
            glow=rect.inflate(S(10),S(10)); pygame.draw.rect(SCREEN,(90,70,20),glow,max(1,S(2)),border_radius=S(20))

    def _ui_card(self, rect, edge, title, desc="", badge="", style=0, featured=False, title_color=WHITE, desc_color=GRAY, center_title=False, max_lines=3):
        self._ui_shape(rect, edge, style=style, featured=featured)
        fonts=self._ui_fonts(); pad=S(16); top=rect.y+S(14); inner_bottom=rect.bottom-S(16)
        if badge:
            badge_font=fonts["tiny"]; bw=min(rect.w-S(48), max(S(120), badge_font.size(str(badge))[0]+S(22)))
            br=pygame.Rect(rect.x+pad, top, bw, min(S(38),max(S(28),rect.h//6))); pygame.draw.rect(SCREEN, edge, br, border_radius=S(9))
            draw_fitted_text(badge,[fonts["body"],badge_font,SHOP_FONT_TINY],
                             DARK if edge in (YELLOW,CYAN,GREEN,ORANGE,DIVINE_BLUE) else WHITE,
                             br.inflate(-S(10),-S(3)),True)
            top = br.bottom + S(10)
        available=max(1,inner_bottom-top)
        if desc:
            title_h=min(available,max(S(38),min(S(84),int(available*0.38))))
        else:
            title_h=available
        title_rect=pygame.Rect(rect.x+pad,top,rect.w-pad*2,title_h)
        title_fonts=[fonts["big"],fonts["body"],fonts["tiny"],SHOP_FONT_TINY]
        draw_responsive_text(title,title_fonts,title_color,title_rect,2,center_title,2,"center" if not desc else "top")
        if desc and title_rect.bottom < inner_bottom:
            desc_y=title_rect.bottom+S(4)
            desc_rect=pygame.Rect(rect.x+pad,desc_y,rect.w-pad*2,max(0,inner_bottom-desc_y))
            desc_fonts=([fonts["body"],fonts["tiny"],SHOP_FONT_TINY]
                        if rect.h>=S(230) else [fonts["tiny"],SHOP_FONT_TINY])
            draw_responsive_text(desc,desc_fonts,desc_color,desc_rect,2,False,max_lines,"top")

    def _ui_button(self, rect, label, color, active=True, style=1, small=False):
        fill=(18,20,28) if active else (35,37,44)
        edge=color if active else GRAY
        self._ui_shape(rect, edge, fill=fill, style=style, width=max(1,S(3)), featured=False)
        fonts=self._ui_fonts()
        choices=([fonts["body"],fonts["tiny"],SHOP_FONT_TINY] if small
                 else [fonts["big"],fonts["body"],fonts["tiny"],SHOP_FONT_TINY])
        fg=WHITE if active else GRAY
        draw_fitted_text(label,choices,fg,rect.inflate(-S(20),-S(8)),True)

    def _ui_nav_triplet(self, back, prev, nxt, page_text=""):
        self._ui_button(back, "VOLTAR", CYAN, True, 1)
        self._ui_button(prev, "< ANTERIOR", ORANGE, True, 2)
        self._ui_button(nxt, "PROXIMA >", ORANGE, True, 3)
        if page_text:
            page_box=pygame.Rect(W/2-S(240),H-CONTROL_SAFE_Y-S(47),S(480),S(42))
            draw_fitted_text(page_text,[self._ui_fonts()["body"],self._ui_fonts()["tiny"],SHOP_FONT_TINY],GRAY,page_box,True)

    def _profile_accent(self):
        idx=int(SAVE.get("profile_color",0) or 0)%len(PROFILE_COLORS)
        return PROFILE_COLORS[idx]

    def _profile_banner_keys(self):
        return [k for k,_,_ in PROFILE_BANNERS if profile_banner_unlocked(k)] or ["default"]

    def _profile_favorite_options(self):
        chars=[c for c in CHARACTER_ORDER if c in CHARACTER_CONFIG and self.character_unlocked(c) and not is_beta_character(c)]
        return chars or ["Ycaro"]

    def _draw_profile_avatar(self, rect, index, selected=False):
        idx=int(index)%len(PROFILE_AVATAR_NAMES); accent=self._profile_accent()
        palette=(RED,YELLOW,GREEN,CYAN,ORANGE,(160,205,255),(150,150,160),PURPLE,WHITE,(245,208,80),(100,180,255),(220,90,170))
        edge=palette[idx]
        cx,cy=rect.center; m=max(S(5),min(rect.w,rect.h)//16); rr=max(S(14),min(rect.w,rect.h)//2-m)
        # Molduras propositalmente diferentes: o avatar nao parece uma foto quadrada generica.
        if idx%4==0:
            pts=[(cx,rect.y),(rect.right,cy),(cx,rect.bottom),(rect.x,cy)]
            pygame.draw.polygon(SCREEN,(13,15,21),pts); pygame.draw.polygon(SCREEN,WHITE if selected else edge,pts,max(2,S(5 if selected else 3)))
        elif idx%4==1:
            pygame.draw.circle(SCREEN,(13,15,21),(cx,cy),rr); pygame.draw.circle(SCREEN,WHITE if selected else edge,(cx,cy),rr,max(2,S(5 if selected else 3)))
        elif idx%4==2:
            cut=max(S(10),rect.w//6); pts=[(rect.x+cut,rect.y),(rect.right,rect.y),(rect.right-cut,rect.bottom),(rect.x,rect.bottom)]
            pygame.draw.polygon(SCREEN,(13,15,21),pts); pygame.draw.polygon(SCREEN,WHITE if selected else edge,pts,max(2,S(5 if selected else 3)))
        else:
            pygame.draw.rect(SCREEN,(13,15,21),rect,border_radius=max(S(10),rect.w//4)); pygame.draw.rect(SCREEN,WHITE if selected else edge,rect,max(2,S(5 if selected else 3)),border_radius=max(S(10),rect.w//4))
        # Emblemas / artes internas.
        if idx==0: # Kakuja
            pygame.draw.ellipse(SCREEN,WHITE,pygame.Rect(cx-rr*.55,cy-rr*.27,rr*1.1,rr*.54)); pygame.draw.circle(SCREEN,RED,(cx,cy),max(S(5),rr//5)); pygame.draw.circle(SCREEN,(20,0,0),(cx,cy),max(S(2),rr//10))
        elif idx==1: # Dharma
            pygame.draw.circle(SCREEN,YELLOW,(cx,cy),int(rr*.72),max(2,S(4)))
            for j in range(8):
                d=vec_from_angle(j*math.tau/8); pygame.draw.line(SCREEN,YELLOW,(cx+int(d.x*rr*.18),cy+int(d.y*rr*.18)),(cx+int(d.x*rr*.68),cy+int(d.y*rr*.68)),max(1,S(3)))
            pygame.draw.circle(SCREEN,YELLOW,(cx,cy),max(S(5),rr//6),max(2,S(3)))
        elif idx==2: # Glonk
            pygame.draw.circle(SCREEN,GREEN,(cx,cy),int(rr*.55)); pygame.draw.circle(SCREEN,DARK,(cx-int(rr*.18),cy-int(rr*.12)),max(2,S(4))); pygame.draw.circle(SCREEN,DARK,(cx+int(rr*.18),cy-int(rr*.12)),max(2,S(4)))
            for off in (-1,1): pygame.draw.line(SCREEN,GREEN,(cx+off*int(rr*.65),cy+int(rr*.22)),(cx+off*int(rr*.92),cy+int(rr*.22)),max(1,S(3)))
        elif idx==3: # Sans / Bad Time
            pygame.draw.circle(SCREEN,WHITE,(cx,cy),int(rr*.55),max(2,S(4))); pygame.draw.circle(SCREEN,CYAN,(cx+int(rr*.19),cy-int(rr*.10)),max(S(4),rr//9)); pygame.draw.line(SCREEN,WHITE,(cx-int(rr*.42),cy+int(rr*.28)),(cx+int(rr*.42),cy+int(rr*.28)),max(1,S(3)))
        elif idx==4: # Abacaxi
            body=pygame.Rect(cx-int(rr*.30),cy-int(rr*.15),int(rr*.60),int(rr*.62)); pygame.draw.ellipse(SCREEN,YELLOW,body); 
            for ang in (-0.45,0,0.45):
                d=vec_from_angle(-math.pi/2+ang); pygame.draw.line(SCREEN,GREEN,(cx,cy-int(rr*.18)),(cx+int(d.x*rr*.52),cy+int(d.y*rr*.52)),max(2,S(4)))
        elif idx==5: # Shotgun
            pygame.draw.line(SCREEN,WHITE,(cx-int(rr*.58),cy+int(rr*.25)),(cx+int(rr*.58),cy-int(rr*.20)),max(3,S(7))); pygame.draw.line(SCREEN,ORANGE,(cx-int(rr*.18),cy+int(rr*.07)),(cx-int(rr*.02),cy+int(rr*.38)),max(2,S(5)))
        elif idx==6: # Sucata
            pygame.draw.circle(SCREEN,(170,175,185),(cx,cy),int(rr*.50),max(2,S(5))); pygame.draw.circle(SCREEN,(170,175,185),(cx,cy),max(S(6),rr//7));
            for j in range(8):
                d=vec_from_angle(j*math.tau/8); pygame.draw.line(SCREEN,(170,175,185),(cx+int(d.x*rr*.48),cy+int(d.y*rr*.48)),(cx+int(d.x*rr*.74),cy+int(d.y*rr*.74)),max(2,S(5)))
        elif idx==7: # Domain
            for f,col in ((.72,PURPLE),(.48,CYAN),(.22,WHITE)): pygame.draw.circle(SCREEN,col,(cx,cy),int(rr*f),max(1,S(3)))
        elif idx==8: # Censura
            for j,w in enumerate((1.1,.82,1.0)):
                pygame.draw.rect(SCREEN,WHITE,pygame.Rect(cx-int(rr*.55*w),cy-int(rr*.38)+j*int(rr*.32),int(rr*1.1*w),max(S(8),int(rr*.17))),border_radius=S(3))
        elif idx==9: # Crown
            pts=[(cx-int(rr*.55),cy+int(rr*.35)),(cx-int(rr*.42),cy-int(rr*.30)),(cx-int(rr*.12),cy),(cx,cy-int(rr*.52)),(cx+int(rr*.18),cy),(cx+int(rr*.50),cy-int(rr*.30)),(cx+int(rr*.55),cy+int(rr*.35))]
            pygame.draw.polygon(SCREEN,YELLOW,pts); pygame.draw.polygon(SCREEN,WHITE,pts,max(1,S(2)))
        elif idx==10: # Soul
            pts=[(cx,cy+int(rr*.55)),(cx-int(rr*.52),cy-int(rr*.08)),(cx-int(rr*.40),cy-int(rr*.45)),(cx,cy-int(rr*.24)),(cx+int(rr*.40),cy-int(rr*.45)),(cx+int(rr*.52),cy-int(rr*.08))]
            pygame.draw.polygon(SCREEN,CYAN,pts); pygame.draw.polygon(SCREEN,WHITE,pts,max(1,S(2)))
        else: # Rift
            pts=[(cx-int(rr*.12),cy-int(rr*.67)),(cx+int(rr*.12),cy-int(rr*.20)),(cx-int(rr*.04),cy-int(rr*.05)),(cx+int(rr*.22),cy+int(rr*.64)),(cx-int(rr*.22),cy+int(rr*.14)),(cx-int(rr*.05),cy-int(rr*.02))]
            pygame.draw.polygon(SCREEN,(235,90,185),pts); pygame.draw.line(SCREEN,WHITE,pts[0],pts[-1],max(1,S(2)))
        if selected:
            pygame.draw.circle(SCREEN,accent,(rect.right-S(11),rect.y+S(11)),max(S(5),rect.w//16))

    def _draw_profile_banner(self, rect, key, accent):
        surf=pygame.Surface((rect.w,rect.h),pygame.SRCALPHA); surf.fill((10,12,18,238))
        # Faixas metalicas / caoticas.
        for i in range(7):
            y=int(i*rect.h/7); col=(18+i*2,20+i*2,28+i*2,255); pygame.draw.rect(surf,col,(0,y,rect.w,max(1,rect.h//7-2)))
        pygame.draw.line(surf,accent,(0,S(8)),(rect.w-S(80),S(8)),max(1,S(4)))
        ticks=pygame.time.get_ticks()
        if key=="mahoraga":
            c=(int(rect.w*.78),int(rect.h*.42)); rr=int(min(rect.w,rect.h)*.30); pygame.draw.circle(surf,(218,170,45),c,rr,max(2,S(7)))
            ang=ticks/2800.0
            for i in range(8):
                d=vec_from_angle(ang+i*math.tau/8); pygame.draw.line(surf,(218,170,45),(c[0]+int(d.x*rr*.18),c[1]+int(d.y*rr*.18)),(c[0]+int(d.x*rr),c[1]+int(d.y*rr)),max(2,S(4)))
        elif key=="glonk":
            for i in range(8):
                x=int(((ticks*.08+i*rect.w*.17)%(rect.w+S(120)))-S(60)); y=int(rect.h*(.25+.10*(i%4))); pygame.draw.circle(surf,(45,160,70),(x,y),S(16+(i%2)*4)); pygame.draw.line(surf,(45,160,70),(x-S(34),y+S(8)),(x-S(62),y+S(8)),max(1,S(3)))
        elif key=="domain":
            c=(int(rect.w*.78),int(rect.h*.50));
            for f,col in ((.34,PURPLE),(.25,CYAN),(.16,WHITE)): pygame.draw.circle(surf,col,c,int(min(rect.w,rect.h)*f),max(1,S(4)))
        elif key=="sans":
            for i in range(8):
                x=int((i+.5)*rect.w/8); y=int(rect.h*(.20+.15*(i%3))); pygame.draw.line(surf,WHITE,(x,y-S(32)),(x,y+S(32)),max(2,S(6))); pygame.draw.circle(surf,CYAN if i%3==0 else WHITE,(x,y-S(36)),S(8),max(1,S(3))); pygame.draw.circle(surf,WHITE,(x,y+S(36)),S(8),max(1,S(3)))
        elif key=="bestiary":
            for i in range(9):
                x=int((i+.5)*rect.w/9); y=int(rect.h*.45+math.sin(i)*S(20)); r=S(18+(i%3)*5); pygame.draw.circle(surf,(55,58,67),(x,y),r); pygame.draw.circle(surf,accent,(x,y),r,max(1,S(2)))
        else:
            for i in range(12):
                x=int((i*97)%max(1,rect.w)); y=int((i*53)%max(1,rect.h)); pygame.draw.rect(surf,(*accent,55),(x,y,S(70),S(3)))
        SCREEN.blit(surf,rect.topleft)
        pygame.draw.rect(SCREEN,accent,rect,max(2,S(4)),border_radius=S(12))

    def _draw_profile_character_art(self, rect, character, accent):
        cfg=CHARACTER_CONFIG.get(character,CHARACTER_CONFIG.get("Ycaro",{"color":accent,"weapon_name":"?"}))
        col=cfg.get("color",accent); cx=int(rect.centerx); base=int(rect.bottom-S(30)); body_w=int(rect.w*.34); head_r=max(S(22),int(rect.w*.085))
        # Sombra grande, estilo poster recortado.
        pygame.draw.polygon(SCREEN,(9,10,15),[(cx-body_w,base),(cx-body_w//2,rect.y+int(rect.h*.35)),(cx,rect.y+int(rect.h*.18)),(cx+body_w//2,rect.y+int(rect.h*.35)),(cx+body_w,base)])
        pygame.draw.circle(SCREEN,col,(cx,rect.y+int(rect.h*.25)),head_r,max(3,S(7)))
        pygame.draw.line(SCREEN,col,(cx,rect.y+int(rect.h*.34)),(cx,base-S(80)),max(4,S(10)))
        pygame.draw.line(SCREEN,col,(cx,rect.y+int(rect.h*.45)),(cx-int(rect.w*.20),rect.y+int(rect.h*.63)),max(4,S(8)))
        pygame.draw.line(SCREEN,col,(cx,rect.y+int(rect.h*.45)),(cx+int(rect.w*.20),rect.y+int(rect.h*.63)),max(4,S(8)))
        draw_fitted_text(character.upper(),[self._ui_fonts()["big"],self._ui_fonts()["body"],self._ui_fonts()["tiny"]],WHITE,
                         pygame.Rect(rect.x+S(12),rect.bottom-S(96),rect.w-S(24),S(48)),True)
        draw_fitted_text(str(cfg.get("weapon_name","")),[self._ui_fonts()["body"],self._ui_fonts()["tiny"],SHOP_FONT_TINY],col,
                         pygame.Rect(rect.x+S(12),rect.bottom-S(48),rect.w-S(24),S(34)),True)

    def _draw_profile_badge(self, rect, key, active=True):
        name,col=PROFILE_BADGE_INFO.get(key,("VAZIO",GRAY))
        self._ui_shape(rect,col if key else GRAY,fill=(13,15,21),style=(sum(ord(c) for c in key)%6 if key else 2),width=3,featured=active and bool(key))
        if key:
            # losango central
            cx,cy=rect.center; d=min(rect.w,rect.h)//5; pts=[(cx,cy-d),(cx+d,cy),(cx,cy+d),(cx-d,cy)]; pygame.draw.polygon(SCREEN,col,pts); pygame.draw.polygon(SCREEN,WHITE,pts,max(1,S(2)))
            draw_wrapped_text(name,self._ui_fonts()["tiny"],WHITE,pygame.Rect(rect.x+S(8),rect.bottom-S(42),rect.w-S(16),S(36)),1,True,2)
        else:
            draw_text("—",self._ui_fonts()["big"],GRAY,rect.center,True)

    def _open_profile_picker(self, kind, slot=0):
        self.profile_picker_kind=str(kind)
        self.profile_picker_page=0
        self.profile_picker_slot=int(slot)
        self.profile_name_active=False
        try: pygame.key.stop_text_input()
        except Exception: pass
        AUDIO.play("click",0.45)

    def _profile_picker_options(self):
        kind=getattr(self,"profile_picker_kind",None)
        if kind=="avatar":
            return list(range(len(PROFILE_AVATAR_NAMES)))
        if kind=="favorite":
            return self._profile_favorite_options()
        if kind=="title":
            return profile_title_options()
        if kind=="badge":
            return [""]+profile_unlocked_badges()
        if kind=="banner":
            return self._profile_banner_keys()
        if kind=="color":
            return list(range(len(PROFILE_COLORS)))
        return []

    def _draw_profile_picker(self):
        kind=getattr(self,"profile_picker_kind",None)
        if not kind: return
