    def _apply_profile_picker_choice(self, value):
        kind=getattr(self,"profile_picker_kind",None)
        if kind=="avatar": SAVE["profile_avatar"]=int(value)
        elif kind=="favorite": SAVE["profile_favorite"]=str(value)
        elif kind=="title": SAVE["equipped_title"]=str(value)
        elif kind=="badge":
            saved=list(SAVE.get("profile_badges",[]) or []); saved=(saved+["",""])[:3]; key=str(value); slot=int(getattr(self,"profile_picker_slot",0))
            if key and key in [x for j,x in enumerate(saved) if j!=slot]: return False
            saved[slot]=key; SAVE["profile_badges"]=saved
        elif kind=="banner": SAVE["profile_banner"]=str(value)
        elif kind=="color": SAVE["profile_color"]=int(value)
        else: return False
        save_data(SAVE); AUDIO.play("click",0.55); self.profile_picker_kind=None; self.profile_picker_page=0
        return True

