                can = prof.get("points",0)>0 and alloc<MAX_EVOLUTION_STAT
                self._ui_button(plus, "+" if alloc<MAX_EVOLUTION_STAT else "MAX", GREEN, can, 2, small=True)
                self.character_stat_plus_rects.append((plus, stat, can))
