        entries=[x for x in PASSIVES if x["key"] in discovered or x["key"] in equipped_global] if self.passive_catalog_tab=="known" else list(PASSIVES)
        per=6; pages=max(1,math.ceil(max(1,len(entries))/per)); self.passive_catalog_page=int(clamp(self.passive_catalog_page,0,pages-1))
