    def _items_usable_catalog(self):
        entries=[]
        for key,info in CONSUMABLES.items():
            entries.append({"kind":"boost","key":key,"name":info["name"],"color":info["color"],"desc":info["desc"],"price":info["price"]})
        for key,info in SHOP_RELICS.items():
            entries.append({"kind":"relic","key":key,"name":info["name"],"color":info["color"],"desc":info["desc"],"price":info["price"],"type":"relic"})
        special_keys=("suspicious_box","glonk_lure","calamity_bell","event_luck","observer")
        by_key={x["key"]:x for x in MYSTERY_MARKET_POOL}
        for key in special_keys:
            if key in by_key:
                o=dict(by_key[key]); o["kind"]="special"; entries.append(o)
        return entries

    def _items_special_pending(self,key):
        return {
            "glonk_lure":"pending_glonk_lure",
            "calamity_bell":"pending_calamity_bell",
            "event_luck":"pending_event_luck",
            "observer":"pending_observer",
        }.get(key)

