        y=S(198); crafted=set(SAVE.get("crafted_weapons",[])); eq=SAVE.get("equipped_weapons",{}) if isinstance(SAVE.get("equipped_weapons",{}),dict) else {}
        for i,w in enumerate(entries[self.weapons_page*per:(self.weapons_page+1)*per]):
            rn,color=FORGE_RARITIES[w["rarity"]]; owned=w["key"] in crafted; equipped=eq.get(w["character"])==w["key"]
            r=pygame.Rect(SAFE,y,W-SAFE*2,S(146)); preview=w.get("preview",False); testable=bool(preview and w.get("testable",False))
            self._ui_card(r,color,f"{w['name']}  [{rn}]",desc=w["desc"],badge=("BETA" if preview else "ARSENAL"),style=i,featured=(equipped or w['rarity'] in ('legendary','divine')),title_color=color,desc_color=GRAY,max_lines=3)
            b=pygame.Rect(r.right-S(330),r.y+S(40),S(295),S(66))
            bc=GREEN if (testable and equipped) else (DIVINE_BLUE if preview else (GREEN if equipped else (BLUE if owned else PANEL2)))
            label=("BETA EQUIPADA" if testable and equipped else ("TESTAR BETA" if testable else ("PREVIA BETA" if preview else ("EQUIPADA" if equipped else ("EQUIPAR" if owned else "NAO FABRICADA")))))
            self._ui_button(b,label,bc if bc!=PANEL2 else GRAY,bc!=PANEL2,4)
            if (testable and not equipped) or (owned and not equipped and not preview): self.weapon_equip_rects.append((b,w["key"]))
            y+=S(160)
        prev=pygame.Rect(W/2-S(330),H-CONTROL_SAFE_Y-S(58),S(180),S(52)); nxt=pygame.Rect(W/2+S(150),H-CONTROL_SAFE_Y-S(58),S(180),S(52))
        self._ui_button(prev,"< PAG",ORANGE,True,1); self._ui_button(nxt,"PAG >",ORANGE,True,2)
        draw_text(f"{char} | PAGINA {self.weapons_page+1}/{pages} | {len(entries)} ARMAS",self._ui_fonts()["body"],GRAY,(W/2,H-CONTROL_SAFE_Y-S(30)),True)
