            b=pygame.Rect(r.right-S(345),r.y+S(48),S(310),S(68)); bc=GREEN if (testable and equipped) else (DIVINE_BLUE if preview else (GREEN if equipped else (BLUE if owned else ORANGE)))
            label=("BETA EQUIPADA" if testable and equipped else ("TESTAR BETA" if testable else ("EM BETA" if preview else ("EQUIPADA" if equipped else ("EQUIPAR" if owned else "FABRICAR")))))
