    def draw_run_upgrades(self):
        self._draw_ui_background("UPGRADES DA RUN", "TUDO QUE SUA RUN JA ACUMULOU ATE AGORA", YELLOW)
        card_by_key = {card[3]:(source,card) for source,card in self.all_upgrade_entries()}
        entries = []
        for key, count in self.owned_upgrade_counts.items():
            if key in card_by_key: entries.append((card_by_key[key][0], card_by_key[key][1], count))
        entries.sort(key=lambda item: item[1][1])
        per_page = 8; pages = max(1, math.ceil(max(1,len(entries))/per_page)); self.run_upgrade_page = int(clamp(self.run_upgrade_page, 0, pages-1))
        subset = entries[self.run_upgrade_page*per_page:(self.run_upgrade_page+1)*per_page]
        if not subset:
            draw_text("NENHUM UPGRADE AINDA. SOBREVIVA MAIS UM POUCO, CHEFE.", self._ui_fonts()["big"], GRAY, (W/2,H*0.43), True)
        else:
            cols, gap = 2, S(18); top, card_h = S(125), S(155); card_w = int((W-SAFE*2-gap)/2)
            rarity_color = {"common":GRAY, "rare":BLUE, "epic":PURPLE, "legendary":YELLOW, "divine":DIVINE_BLUE, "cursed":RED}
