    def _play_seuze_voice(self):
        role=f"seuze_voice_{random.randint(1,5)}"
        # Voz do Seu Ze ganha prioridade de verdade sobre a trilha da loja.
        AUDIO.voice_duck_until=pygame.time.get_ticks()+3600
        if not AUDIO.play_external_sfx(role,1.70,0): AUDIO.play("click",0.70,45)

    def _trigger_seuze_phrase(self,kind="enter"):
        if kind=="enter": pool=SEUZE_ENTER_LINES
        elif kind=="buy": pool=SEUZE_BUY_LINES
        elif kind=="click": pool=SEUZE_CLICK_LINES
        else: pool=SEUZE_EMPTY_LINES
        self.seuze_phrase=random.choice(pool) if pool else ""
        self.seuze_phrase_timer=self.seuze_phrase_duration
        self.seuze_phrase_kind=kind
        if self.seuze_phrase: self._play_seuze_voice()

    def _draw_seuze_phrase(self):
        if getattr(self,"seuze_phrase_timer",0.0)<=0 or not getattr(self,"seuze_phrase",""):
            return
        tm=float(self.seuze_phrase_timer); dur=max(0.1,float(getattr(self,"seuze_phrase_duration",7.0)))
        elapsed=max(0.0,dur-tm)
        fade_in=clamp(elapsed/0.18,0.0,1.0)
        fade_out=clamp(tm/0.62,0.0,1.0)
        alpha=clamp(int(255*min(fade_in,fade_out)),0,255)
        if alpha<=0: return
        # Balao fica ao lado esquerdo do personagem, sem cobrir o estoque.
        box_w=min(S(650),max(S(430),int(W*0.29))); box_h=S(176)
        bx=int(W*0.50); by=int(H*0.24)
        bx=min(W-box_w-S(30),max(int(W*0.47),bx))
        surf=pygame.Surface((box_w+S(24),box_h),pygame.SRCALPHA)
        pygame.draw.rect(surf,(7,7,10,int(148*alpha/255)),(0,0,box_w,box_h),border_radius=S(20))
        pygame.draw.rect(surf,(255,255,255,int(72*alpha/255)),(0,0,box_w,box_h),max(1,S(2)),border_radius=S(20))
        pygame.draw.polygon(surf,(7,7,10,int(148*alpha/255)),[(box_w-S(2),S(65)),(box_w+S(22),S(88)),(box_w-S(2),S(110))])
        SCREEN.blit(surf,(bx,by))
        text_rect=pygame.Rect(bx+S(24),by+S(22),box_w-S(48),box_h-S(44))
        phrase_fonts=[FONT_M,FONT_S,SHOP_FONT_XS,SHOP_FONT_TINY]
        draw_responsive_text(self.seuze_phrase,phrase_fonts,(0,0,0),text_rect.move(S(3),S(3)),4,False,4,"center",alpha)
        draw_responsive_text(self.seuze_phrase,phrase_fonts,WHITE,text_rect,4,False,4,"center",alpha)

    def _draw_seuze_shop(self):
        offers=ensure_seuze_shop()
        # V16.3: cena unificada enviada pelo usuario. Nao precisa mais de PNG separado do NPC + fundo.
        scene=seu_ze_shop_scene_surface(W,H)
        if scene is not None:
            SCREEN.blit(scene,(0,0))
        else:
            # Compatibilidade com instalacoes antigas.
            bg=seu_ze_shop_bg_surface(W,H)
            if bg is not None: SCREEN.blit(bg,(0,0))
            else: SCREEN.fill((42,24,15))
            base=SEU_ZE_IMAGE
            if base is not None:
                target_h=int(H*1.03); bw,bh=base.get_size(); target_w=max(S(420),int(target_h*bw/max(1,bh))); img=seu_ze_surface(target_w)
                if img is not None:
                    bottom=int(H+S(115)); x=int(W*0.72-img.get_width()/2); y_img=bottom-img.get_height(); SCREEN.blit(img,(x,y_img))
        # Estoque escuro só na metade esquerda para preservar leitura sem esconder o cenario.
        shade=pygame.Surface((int(W*0.49),H),pygame.SRCALPHA); shade.fill((3,4,7,142)); SCREEN.blit(shade,(0,0))
        left_w=int((W-CONTROL_SAFE_X*2)*0.47)
        self.seuze_viewport=pygame.Rect(CONTROL_SAFE_X,S(190),left_w,H-S(300))
        self.seuze_item_rects=[]
        stock_box=pygame.Rect(self.seuze_viewport.x,self.seuze_viewport.y-S(42),self.seuze_viewport.w,S(36))
        draw_fitted_text(f"ESTOQUE {seuze_shop_time_text()}",[FONT_S,SHOP_FONT_XS,SHOP_FONT_TINY],YELLOW,stock_box,True)
        old_clip=SCREEN.get_clip(); SCREEN.set_clip(self.seuze_viewport)
        widths=[1.00,0.86,0.94,0.78,0.98,0.88]; heights=[230,180,285,205,255,195]; shifts=[0,34,10,54,0,28]
        y=self.seuze_viewport.y+S(8)-int(self.seuze_scroll_y); card_area_w=self.seuze_viewport.w-S(24)
        for i,offer in enumerate(offers):
            ww=int(card_area_w*widths[i%len(widths)]); hh=S(heights[i%len(heights)]); xx=self.seuze_viewport.x+S(10)+S(shifts[i%len(shifts)])
            if xx+ww>self.seuze_viewport.right-S(8): xx=self.seuze_viewport.right-S(8)-ww
            r=pygame.Rect(xx,y,ww,hh)
            if r.bottom>=self.seuze_viewport.y-S(40) and r.y<=self.seuze_viewport.bottom+S(40):
                self._draw_shop_offer_card(r,offer,i,True,featured=(i%5==0)); self.seuze_item_rects.append((pygame.Rect(r),i))
            y+=hh+S(18)
        SCREEN.set_clip(old_clip)
        content_h=max(0,y-(self.seuze_viewport.y+S(8))+int(self.seuze_scroll_y)); self.seuze_max_scroll=max(0.0,float(content_h-self.seuze_viewport.h+S(8))); self.seuze_scroll_y=clamp(float(self.seuze_scroll_y),-self.shop_overscroll,self.seuze_max_scroll+self.shop_overscroll)
        track=pygame.Rect(self.seuze_viewport.x,self.seuze_viewport.bottom+S(12),self.seuze_viewport.w,S(18)); pygame.draw.rect(SCREEN,(25,18,15),track,border_radius=S(9)); pygame.draw.rect(SCREEN,(170,105,42),track,max(1,S(2)),border_radius=S(9))
        content=max(float(self.seuze_viewport.h),float(self.seuze_viewport.h+self.seuze_max_scroll)); ratio=min(1.0,self.seuze_viewport.h/max(1.0,content)); knob_w=max(S(120),int(track.w*ratio)); visual=clamp(float(self.seuze_scroll_y),0.0,self.seuze_max_scroll); knob_x=track.x if self.seuze_max_scroll<=0 else track.x+(track.w-knob_w)*(visual/self.seuze_max_scroll); knob=pygame.Rect(int(knob_x),track.y,knob_w,track.h)
        pygame.draw.rect(SCREEN,YELLOW,knob,border_radius=S(9)); pygame.draw.rect(SCREEN,WHITE,knob,max(1,S(2)),border_radius=S(9)); self.shop_scrollbar_track=track; self.shop_scrollbar_knob=knob
        # Hitbox deliberadamente menor que a arte: só torso/cabeca no canto direito.
        self.seuze_portrait_rect=pygame.Rect(int(W*0.68),int(H*0.18),int(W*0.29),int(H*0.78))

    def _shop_section_offers(self):
        section=getattr(self,"shop_section","daily")
        if section=="daily":
            return ensure_daily_shop()
        if section=="permanent":
            offers=[]
            palette=(ORANGE,CYAN,PURPLE,BLUE,GREEN,YELLOW)
            for i,(key,name,desc,base) in enumerate(PERMANENT_UPGRADES):
                lvl=min(PERMANENT_UPGRADE_CAP,int(SAVE.get(key,0) or 0))
                offers.append({"type":"permanent_upgrade","key":key,"name":name,"desc":desc,"base":base,
                               "price":permanent_upgrade_cost(base,lvl),"original":permanent_upgrade_cost(base,lvl),
                               "color":palette[i%len(palette)],"badge":f"PERMANENTE • LV.{lvl}/{PERMANENT_UPGRADE_CAP}"})
            for item in SHOP_UTILITY_OFFERS:
                o=dict(item); o["type"]="utility"; o.setdefault("original",o["price"]); offers.append(o)
            return offers
        if section=="relics":
            return [{"type":"relic","key":k,**dict(v),"badge":"RELIQUIA • 1 EQUIPADA"} for k,v in SHOP_RELICS.items()]
        if section=="cosmetics":
            out=[]
            for k,v in SHOP_COSMETICS.items():
                badge="TEMA DE MENU" if v.get("kind")=="theme" else "TITULO"
                out.append({"type":"cosmetic","key":k,**dict(v),"badge":badge})
            return out
        if section=="seuze": return ensure_seuze_shop()
        return ensure_daily_shop()

    def _shop_offer_visual(self, offer):
        """Nome/cor/descricao unificados para todas as alas da Central da Loja."""
        typ=offer.get("type")
        if typ=="material":
            info=FORGE_MATERIALS.get(offer.get("key"),{})
            name=info.get("name",offer.get("key","ITEM")); color=FORGE_RARITIES.get(info.get("rarity","common"),("",GRAY))[1]
            qty=max(1,int(offer.get("qty",1)))
            desc=(f"{qty}x fragmento permanente. Use em receitas raras da Forja." if offer.get("key") in SIN_FRAGMENTS
                  else f"{qty}x material permanente para fabricar e evoluir armas.")
        elif typ=="consumable":
            info=CONSUMABLES.get(offer.get("key"),{}); name=info.get("name","BOOST"); color=info.get("color",CYAN); desc=info.get("desc","")
            if int(offer.get("qty",1))>1: name=f"{offer.get('qty')}x {name}"
        elif typ=="weapon":
            w=FORGE_WEAPON_BY_KEY.get(offer.get("key"),{}); name=w.get("name","ARMA"); color=FORGE_RARITIES.get(w.get("rarity","rare"),("",BLUE))[1]; desc=w.get("desc","")
        elif typ=="choose_weapon":
            name="ESCOLHA UMA ARMA"; color=YELLOW; desc="Pague uma vez e escolha 1 entre 3 armas diferentes do estoque de hoje."
        else:
            name=str(offer.get("name",offer.get("key","OFERTA"))).upper(); color=(chromatic_color() if offer.get("chromatic") else offer.get("color",CYAN)); desc=str(offer.get("desc",""))
        return name,color,desc

    def _shop_offer_price(self, offer):
        if offer.get("type")=="permanent_upgrade":
            key=offer.get("key"); base=int(offer.get("base",100)); lvl=min(PERMANENT_UPGRADE_CAP,int(SAVE.get(key,0) or 0))
            raw=permanent_upgrade_cost(base,lvl)
        else:
            raw=max(0,int(offer.get("price",0) or 0))
        return max(0,int(round(raw*SHOP_GLOBAL_PRICE_MULT/50.0))*50) if raw>0 else 0

    def _shop_offer_status(self, offer, index=None):
        typ=offer.get("type"); key=offer.get("key")
        if self.shop_section=="daily" and index is not None and index in set(SAVE.get("daily_shop_purchased",[])): return "COMPRADO"
        if self.shop_section=="mystery" and index is not None and index in set(SAVE.get("mystery_shop_purchased",[])): return "COMPRADO"
        if self.shop_section=="seuze" and index is not None and index in set(SAVE.get("seuze_shop_purchased",[])): return "COMPRADO"
        if typ=="weapon" and key in set(SAVE.get("crafted_weapons",[])): return "JA POSSUI"
        if typ=="permanent_upgrade":
            return "MAXIMO" if int(SAVE.get(key,0) or 0)>=PERMANENT_UPGRADE_CAP else ""
        if typ=="utility":
            if key=="reroll_mastery" and int(SAVE.get("reroll_mastery",0) or 0)>=5: return "MAXIMO"
            if key=="scanner" and SAVE.get("scanner_unlocked",False): return "ADQUIRIDO"
            pending={"mystery_upgrade":"pending_mystery_upgrade","cursed_contract":"pending_cursed_contract"}.get(key)
            if pending and SAVE.get(pending,False): return "ARMADO"
        if typ=="relic":
            if SAVE.get("equipped_relic","")==key: return "EQUIPADA"
            if key in set(SAVE.get("relics_owned",[])): return "EQUIPAR"
        if typ=="cosmetic":
            owned=key in set(SAVE.get("cosmetics_owned",[]))
            if owned:
                if offer.get("kind")=="theme" and SAVE.get("menu_theme","default")==offer.get("value"): return "EQUIPADO"
                if offer.get("kind")=="title" and SAVE.get("equipped_title","")==offer.get("value"): return "EQUIPADO"
                return "EQUIPAR"
        return ""

    def _shop_mosaic_specs(self):
        # Vitrine diaria original aprovada: formatos propositalmente desiguais.
        return [
            (20,18,760,650),(812,18,468,286),(1312,18,646,286),(812,336,704,332),(1548,336,410,332),
            (2002,18,548,418),(2584,18,742,418),(2002,468,382,200),(2418,468,908,200),(3370,18,930,258),
            (3370,308,438,360),(3842,308,458,360),(4344,18,574,650),(4960,18,836,306),(4960,356,894,312),
        ]

    def _shop_dynamic_specs(self, count):
        # V16.9.2: cards médios ganharam altura real para nomes e descrições.
        # O mosaico continua irregular, mas nenhuma descrição disputa 50px com o rodapé.
        pattern=[
            (20,18,610,718),(660,18,430,350),(1120,18,700,350),
            (660,386,720,350),(1410,386,410,350),(1850,18,390,718),
        ]
        chunk_w=2290; specs=[]
        for i in range(max(0,count)):
            chunk=i//len(pattern); x,y,w,h=pattern[i%len(pattern)]; specs.append((x+chunk*chunk_w,y,w,h))
        return specs

    def _shop_layout(self, offers=None):
        offers=offers if offers is not None else self._shop_section_offers()
        viewport=getattr(self,"shop_viewport",pygame.Rect(CONTROL_SAFE_X,S(210),W-CONTROL_SAFE_X*2,H-S(330)))
        specs=self._shop_mosaic_specs() if self.shop_section=="daily" and len(offers)>=15 else self._shop_dynamic_specs(len(offers))
        content_w=S(max((x+w for x,y,w,h in specs),default=max(1,viewport.w//max(SCALE,0.001)))+42)
        self.shop_content_w=max(viewport.w,content_w); self.shop_max_scroll=max(0.0,float(self.shop_content_w-viewport.w))
        self.shop_scroll_x=clamp(float(getattr(self,"shop_scroll_x",0.0)),-self.shop_overscroll,self.shop_max_scroll+self.shop_overscroll)
        return [(pygame.Rect(viewport.x+S(x)-int(self.shop_scroll_x),viewport.y+S(y),S(w),S(h)),i) for i,(x,y,w,h) in enumerate(specs)]

    def _draw_shop_offer_card(self, rect, offer, abs_index, interactive=False, featured=False):
        name,color,desc=self._shop_offer_visual(offer); status=self._shop_offer_status(offer,abs_index)
        style=(abs_index + (0 if self.shop_section=="daily" else len(self.shop_section)))%7
        pulse=0.5+0.5*math.sin(pygame.time.get_ticks()/220.0)
        if offer.get("chromatic"):
            edge=chromatic_color(abs_index*0.07)
            featured=True
        else:
            edge=color if not featured else (255,int(180+75*pulse),45)
        bg=(22+style%3*3,23+style%2*3,30+style%4*2); cut=max(S(10),min(S(32),rect.h//8))
        if style in (0,4):
            pts=[(rect.x+cut,rect.y),(rect.right-cut,rect.y),(rect.right,rect.y+cut),(rect.right,rect.bottom-cut),(rect.right-cut,rect.bottom),(rect.x+cut,rect.bottom),(rect.x,rect.bottom-cut),(rect.x,rect.y+cut)]
            pygame.draw.polygon(SCREEN,bg,pts); pygame.draw.polygon(SCREEN,edge,pts,max(2,S(5 if featured else 3)))
        elif style==1:
            pygame.draw.rect(SCREEN,bg,rect,border_radius=S(4)); pygame.draw.rect(SCREEN,edge,rect,max(2,S(4)),border_radius=S(4)); pygame.draw.line(SCREEN,edge,(rect.x,rect.y+S(46)),(rect.right,rect.y+S(46)),max(1,S(3)))
        elif style==2:
            pygame.draw.rect(SCREEN,bg,rect,border_radius=S(22)); pygame.draw.rect(SCREEN,edge,rect,max(2,S(3)),border_radius=S(22)); pygame.draw.rect(SCREEN,edge,pygame.Rect(rect.x,rect.y,S(14),rect.h),border_radius=S(7))
        elif style==3:
            pygame.draw.rect(SCREEN,bg,rect,border_radius=S(10)); pygame.draw.rect(SCREEN,edge,rect,max(2,S(3)),border_radius=S(10)); pygame.draw.rect(SCREEN,edge,rect.inflate(-S(14),-S(14)),max(1,S(2)),border_radius=S(6))
        elif style==5:
            pygame.draw.rect(SCREEN,bg,rect,border_radius=S(28)); pygame.draw.rect(SCREEN,edge,rect,max(2,S(4)),border_radius=S(28)); pygame.draw.polygon(SCREEN,edge,[(rect.x,rect.y),(rect.right-S(70),rect.y),(rect.right,rect.y+S(70)),(rect.x,rect.y+S(70))])
        else:
            pygame.draw.rect(SCREEN,bg,rect,border_radius=S(14)); pygame.draw.rect(SCREEN,edge,rect,max(2,S(3)),border_radius=S(14)); pygame.draw.line(SCREEN,edge,(rect.x+S(18),rect.bottom-S(16)),(rect.right-S(18),rect.bottom-S(16)),max(1,S(4)))
        if featured: pygame.draw.rect(SCREEN,(120,88,18),rect.inflate(S(10),S(10)),max(1,S(2)),border_radius=S(24))

        badge=str(offer.get("badge","")).upper(); disc=float(offer.get("discount",0) or 0); pad=S(16); top_y=rect.y+S(14)
        if offer.get("type")=="permanent_upgrade":
            lvl=int(SAVE.get(offer.get("key"),0) or 0); badge=f"PERMANENTE • LV.{lvl}/{PERMANENT_UPGRADE_CAP}"
        badge_h=max(S(30),min(S(42),rect.h//6))
        dr=None
        if disc>0:
            disc_text=(f"-{disc:.1f}%" if abs(disc-round(disc))>0.001 else f"-{int(round(disc))}%")
            disc_w=max(S(70),min(S(116),rect.w//3))
            dr=pygame.Rect(rect.right-pad-disc_w,top_y,disc_w,badge_h)
            pygame.draw.rect(SCREEN,(72,24,24),dr,border_radius=S(6))
            pygame.draw.rect(SCREEN,RED,dr,max(1,S(2)),border_radius=S(6))
            draw_fitted_text(disc_text,[FONT_S,SHOP_FONT_XS,SHOP_FONT_TINY],WHITE,dr.inflate(-S(8),-S(3)),True)
        if badge:
            badge_font=SHOP_FONT_XS if rect.w>=S(420) else SHOP_FONT_TINY
            badge_right=(dr.x-S(8)) if dr is not None else rect.right-pad
            badge_available=max(S(54),badge_right-(rect.x+pad))
            desired=max(S(128),badge_font.size(badge)[0]+S(24))
            bw=min(badge_available,desired)
            br=pygame.Rect(rect.x+pad,top_y,bw,badge_h)
            pygame.draw.rect(SCREEN,color,br,border_radius=S(6 if style%2 else 14))
            badge_fg=DARK if color in (YELLOW,CYAN,GREEN,ORANGE,DIVINE_BLUE) else WHITE
            draw_fitted_text(badge,[FONT_S,badge_font,SHOP_FONT_TINY],badge_fg,br.inflate(-S(10),-S(3)),True)

        footer_h=S(98 if rect.h>=S(285) else 78)
        footer=pygame.Rect(rect.x+S(10),rect.bottom-footer_h-S(10),rect.w-S(20),footer_h)
        content_top=top_y+badge_h+S(9) if (badge or dr is not None) else top_y
        content_bottom=footer.y-S(9)
        content_h=max(0,content_bottom-content_top)
        has_desc=bool(str(desc).strip()) and content_h>=S(72)
        if has_desc:
            title_h=max(S(42),min(S(92),int(content_h*(0.30 if rect.h>=S(500) else 0.43))))
        else:
            title_h=content_h
        title_h=min(content_h,title_h)
        title_rect=pygame.Rect(rect.x+pad,content_top,rect.w-pad*2,title_h)
        if rect.w>=S(600) and rect.h>=S(300):
            title_fonts=[FONT_L,FONT_M,FONT_S,SHOP_FONT_XS]
        else:
            title_fonts=[FONT_M,FONT_S,SHOP_FONT_XS,SHOP_FONT_TINY]
        draw_responsive_text(name,title_fonts,WHITE,title_rect,2,False,2,"center" if not has_desc else "top")
        if has_desc:
            desc_y=title_rect.bottom+S(4)
            desc_rect=pygame.Rect(rect.x+pad,desc_y,rect.w-pad*2,max(0,content_bottom-desc_y))
            if rect.h>=S(500):
                desc_fonts=[FONT_M,FONT_S,SHOP_FONT_XS]
                max_desc=8
            elif rect.h>=S(340):
                # Não encolhe até a microfonte para tentar mostrar um livro inteiro.
                # O card exibe uma prévia legível; a confirmação exibe o texto completo.
                desc_fonts=[FONT_S,SHOP_FONT_XS]
                max_desc=5
            else:
                desc_fonts=[SHOP_FONT_XS]
                max_desc=2
            draw_responsive_text(desc,desc_fonts,GRAY,desc_rect,2,False,max_desc,"top")

        pygame.draw.rect(SCREEN,(25,46,34) if status in ("COMPRADO","JA POSSUI","MAXIMO","ADQUIRIDO","ARMADO","EQUIPADA","EQUIPADO") else (31,32,42),footer,border_radius=S(10 if style%3 else 3))
        if status:
            col=GREEN if status not in ("EQUIPAR",) else CYAN
            draw_fitted_text(status,[FONT_M,FONT_S,SHOP_FONT_XS],col,footer.inflate(-S(18),-S(10)),True)
        else:
            price=self._shop_offer_price(offer); _orig_raw=int(offer.get("original",0) or 0); original=(max(0,int(round(_orig_raw*SHOP_GLOBAL_PRICE_MULT/50.0))*50) if _orig_raw>0 else price)
            left=footer.x+S(12); buy_w=min(S(170),max(S(96),footer.w//3))
            buy=pygame.Rect(footer.right-buy_w-S(10),footer.y+S(12),buy_w,footer.h-S(24))
            price_w=max(1,buy.x-left-S(8))
            price_box=pygame.Rect(left,footer.y+S(7),price_w,S(48 if original>price else 62))
            draw_fitted_text(f"{format_big_money(price)} $",[FONT_M,FONT_S,SHOP_FONT_XS,SHOP_FONT_TINY],YELLOW,price_box,False)
            if original>price and footer.h>=S(80):
                old_box=pygame.Rect(left,footer.bottom-S(35),price_w,S(27))
                draw_fitted_text(f"ANTES {format_big_money(original)}",[FONT_S,SHOP_FONT_XS,SHOP_FONT_TINY],GRAY,old_box,False)
            pygame.draw.rect(SCREEN,color,buy,border_radius=S(8))
            draw_fitted_text("VER",[FONT_M,FONT_S,SHOP_FONT_XS],WHITE,buy.inflate(-S(8),-S(6)),True)
        if interactive and getattr(self,"shop_viewport",rect).colliderect(rect): self.shop_offer_rects.append((pygame.Rect(rect),abs_index))

    def _draw_shop_mosaic(self):
        offers=self._shop_section_offers(); layout=self._shop_layout(offers); old_clip=SCREEN.get_clip(); SCREEN.set_clip(self.shop_viewport)
        for i,offer in enumerate(offers[:len(layout)]):
            r,_=layout[i]
            if r.colliderect(self.shop_viewport): self._draw_shop_offer_card(r,offer,i,True,featured=(i==0 or (self.shop_section=="daily" and i in (8,12,14))))
        SCREEN.set_clip(old_clip)

    def _shop_section_subtitle(self):
        if self.shop_section=="daily": return f"OFERTAS 24H • NOVO ESTOQUE {daily_shop_time_text()}"
        if self.shop_section=="permanent": return "MELHORIAS, FERRAMENTAS DE BUILD E PROGRESSAO QUE FICAM NA CONTA"
        if self.shop_section=="relics": return "COMPRE RELIQUIAS E TOQUE NAS QUE JA POSSUI PARA EQUIPAR • 1 POR RUN"
        if self.shop_section=="cosmetics": return "TEMAS E TITULOS • TOQUE NUM ITEM JA COMPRADO PARA EQUIPAR"
        if self.shop_section=="seuze": return ""
        runs=int(SAVE.get("shop_runs_started",0) or 0); left=3-(runs%3); return f"4 ITENS ESTRANHOS • TROCA AUTOMATICAMENTE EM {left} RUN{'S' if left!=1 else ''}"

