            track=pygame.Rect(self.shop_viewport.x+S(80),self.shop_viewport.bottom+S(18),self.shop_viewport.w-S(160),S(22)); pygame.draw.rect(SCREEN,(31,33,43),track,border_radius=S(11)); pygame.draw.rect(SCREEN,(70,74,90),track,max(1,S(2)),border_radius=S(11))
            mx=max(0.0,float(getattr(self,"shop_max_scroll",0.0))); content=max(float(self.shop_viewport.w),float(getattr(self,"shop_content_w",self.shop_viewport.w))); visible_ratio=min(1.0,self.shop_viewport.w/content); knob_w=max(S(140),int(track.w*visible_ratio)); visual=clamp(float(self.shop_scroll_x),0.0,mx); knob_x=track.x if mx<=0 else track.x+(track.w-knob_w)*(visual/mx); knob=pygame.Rect(int(knob_x),track.y,knob_w,track.h)
            pygame.draw.rect(SCREEN,CYAN,knob,border_radius=S(11)); pygame.draw.rect(SCREEN,WHITE,knob,max(1,S(2)),border_radius=S(11)); self.shop_scrollbar_track=track; self.shop_scrollbar_knob=knob
