        info=self.shop_choose_offer if isinstance(self.shop_choose_offer,dict) else {"section":"daily","index":int(self.shop_choose_offer)}
        offers=self._shop_section_offers() if info.get("section")==self.shop_section else (ensure_daily_shop() if info.get("section")=="daily" else ensure_mystery_shop())
