        veil=pygame.Surface((W,H),pygame.SRCALPHA); veil.fill((0,0,0,205)); SCREEN.blit(veil,(0,0)); panel=pygame.Rect(W/2-S(650),H/2-S(285),S(1300),S(570)); pygame.draw.rect(SCREEN,PANEL,panel,border_radius=S(24)); pygame.draw.rect(SCREEN,YELLOW,panel,max(2,S(5)),border_radius=S(24))
