            r=pygame.Rect(panel.x+S(40)+i*(cw+gap),panel.y+S(145),cw,S(320)); w=FORGE_WEAPON_BY_KEY.get(key,{}); color=FORGE_RARITIES.get(w.get("rarity","rare"),("",BLUE))[1]
            pygame.draw.rect(SCREEN,(28,29,37),r,border_radius=S(18)); pygame.draw.rect(SCREEN,color,r,max(2,S(4)),border_radius=S(18))
            draw_responsive_text(w.get("name",key),[FONT_M,FONT_S,SHOP_FONT_XS],WHITE,pygame.Rect(r.x+S(14),r.y+S(16),r.w-S(28),S(74)),2,True,2,"center")
            draw_responsive_text(w.get("desc",""),[FONT_S,SHOP_FONT_XS],GRAY,pygame.Rect(r.x+S(14),r.y+S(96),r.w-S(28),S(150)),2,False,5,"top")
            owned=key in set(SAVE.get("crafted_weapons",[]))
