    def _open_shop_confirm(self, section, index, selected_key=None):
        offers=(ensure_daily_shop() if section=="daily" else ensure_mystery_shop() if section=="mystery" else self._shop_section_offers())
        if section!=self.shop_section and section not in ("daily","mystery"): return False
        if index<0 or index>=len(offers): return False
        offer=dict(offers[index]); self.shop_confirm_offer={"section":section,"index":index,"offer":offer,"selected_key":selected_key}; AUDIO.play("click",.65); return True

    def _grant_shop_offer(self, offer, selected_key=None):
        typ=offer.get("type"); qty=max(1,int(offer.get("qty",1)))
        if typ=="material":
            key=offer.get("key"); mats=SAVE.setdefault("forge_materials",{}); mats[key]=int(mats.get(key,0))+qty; disc=set(SAVE.get("forge_discovered",[])); disc.add(key); SAVE["forge_discovered"]=sorted(disc)
        elif typ=="consumable":
            key=offer.get("key"); inv=SAVE.setdefault("usable_items",{}); inv[key]=int(inv.get(key,0))+qty
        elif typ in ("weapon","choose_weapon"):
            key=selected_key or offer.get("key"); crafted=set(SAVE.get("crafted_weapons",[])); crafted.add(key); SAVE["crafted_weapons"]=sorted(crafted)
        elif typ=="permanent_upgrade":
            key=offer.get("key"); SAVE[key]=min(PERMANENT_UPGRADE_CAP,int(SAVE.get(key,0) or 0)+1)
        elif typ=="utility":
            key=offer.get("key")
            if key=="reroll_mastery": SAVE["reroll_mastery"]=min(5,int(SAVE.get("reroll_mastery",0) or 0)+1)
            elif key=="blocker_token": SAVE["blocker_tokens"]=int(SAVE.get("blocker_tokens",0) or 0)+1
            elif key=="mystery_upgrade": SAVE["pending_mystery_upgrade"]=True
            elif key=="cursed_contract": SAVE["pending_cursed_contract"]=True
            elif key=="domain_fragment": SAVE["domain_fragments"]=int(SAVE.get("domain_fragments",0) or 0)+1
            elif key=="scanner": SAVE["scanner_unlocked"]=True
            else: return False
        elif typ=="relic":
            key=offer.get("key"); owned=set(SAVE.get("relics_owned",[])); owned.add(key); SAVE["relics_owned"]=sorted(owned); SAVE["equipped_relic"]=key
        elif typ=="cosmetic":
            key=offer.get("key"); owned=set(SAVE.get("cosmetics_owned",[])); owned.add(key); SAVE["cosmetics_owned"]=sorted(owned)
            if offer.get("kind")=="theme": SAVE["menu_theme"]=offer.get("value","default")
            elif offer.get("kind")=="title": SAVE["equipped_title"]=offer.get("value","")
        elif typ=="seuze_test": pass
        else: return False
        return True

    def _open_suspicious_box(self):
        roll=random.random()
        if roll<0.08:
            SAVE["coins"]+=1; return "A CAIXA TINHA... 1 MOEDA. PARABENS."
        if roll<0.42:
            gain=random.randint(700,4200); SAVE["coins"]+=gain; return f"CAIXA: +{gain} MOEDAS"
        if roll<0.68:
            qty=random.randint(4,12); mats=SAVE.setdefault("forge_materials",{}); mats["scrap"]=int(mats.get("scrap",0))+qty; return f"CAIXA: +{qty} SUCATA"
        if roll<0.84:
            qty=random.randint(1,3); mats=SAVE.setdefault("forge_materials",{}); mats["core"]=int(mats.get("core",0))+qty; return f"CAIXA: +{qty} NUCLEO"
        if roll<0.95:
            SAVE["domain_fragments"]=int(SAVE.get("domain_fragments",0))+1; return "CAIXA: +1 FRAGMENTO DE DOMINIO"
        owned=set(SAVE.get("cosmetics_owned",[])); owned.add("title_suspeito"); SAVE["cosmetics_owned"]=sorted(owned); SAVE["equipped_title"]="SUSPEITO"; return "CAIXA: TITULO RARO 'SUSPEITO'"

    def _grant_mystery_item(self, offer):
        key=offer.get("key")
        if key=="wheel_fragment": SAVE["wheel_fragments"]=int(SAVE.get("wheel_fragments",0) or 0)+1; return "FRAGMENTO DA RODA ADQUIRIDO"
        if key=="suspicious_box": return self._open_suspicious_box()
        if key=="glonk_lure": SAVE["pending_glonk_lure"]=True; return "ISCA ARMADA PARA A PROXIMA RUN"
        if key=="calamity_bell": SAVE["pending_calamity_bell"]=True; return "SINO ARMADO PARA A PROXIMA RUN"
        if key=="event_luck": SAVE["pending_event_luck"]=True; return "SORTE DE EVENTO ARMADA"
        if key=="observer": SAVE["pending_observer"]=True; return "A KAKUJA ESTA OBSERVANDO A PROXIMA RUN"
        if key=="domain_fragment": SAVE["domain_fragments"]=int(SAVE.get("domain_fragments",0) or 0)+1; return "+1 FRAGMENTO DE DOMINIO"
        if key=="blocker_token": SAVE["blocker_tokens"]=int(SAVE.get("blocker_tokens",0) or 0)+1; return "+1 BLOQUEADOR"
        return "ITEM ADQUIRIDO"

    def _execute_shop_purchase(self, data):
        section=data.get("section"); idx=int(data.get("index",-1)); selected_key=data.get("selected_key")
        if section=="items_direct":
            offer=dict(data.get("offer",{})); direct_kind=data.get("direct_kind","")
            if not offer: return False
            key=offer.get("key")
            if direct_kind=="relic" and key in set(SAVE.get("relics_owned",[])):
                SAVE["equipped_relic"]=key; save_data(SAVE); self.shop_confirm_offer=None; return True
            pending=self._items_special_pending(key) if direct_kind=="special" else None
            if pending and SAVE.get(pending,False): self.shop_confirm_offer=None; return False
            price=self._shop_offer_price(offer)
            if SAVE.get("coins",0)<price:
                self.unlock_notice="MOEDAS INSUFICIENTES"; self.unlock_notice_timer=2.0; AUDIO.play("hurt",.45,90); return False
            SAVE["coins"]-=price
            if direct_kind=="relic": ok=self._grant_shop_offer(offer); msg="RELIQUIA ADQUIRIDA E EQUIPADA"
            elif direct_kind=="special": msg=self._grant_mystery_item(offer); ok=True
            else: ok=False; msg="ITEM INVALIDO"
            if not ok: SAVE["coins"]+=price; return False
            save_data(SAVE); AUDIO.play("upgrade",.85); self.unlock_notice=msg; self.unlock_notice_timer=3.0; self.shop_confirm_offer=None; return True
        offers=ensure_daily_shop() if section=="daily" else ensure_mystery_shop() if section=="mystery" else self._shop_section_offers()
        if idx<0 or idx>=len(offers): return False
        offer=offers[idx]; status=self._shop_offer_status(offer,idx)
        if status in ("COMPRADO","JA POSSUI","MAXIMO","ADQUIRIDO","ARMADO","EQUIPADA","EQUIPADO"): return False
        if offer.get("type")=="weapon" and offer.get("key") in set(SAVE.get("crafted_weapons",[])): return False
        if offer.get("type")=="choose_weapon" and selected_key in set(SAVE.get("crafted_weapons",[])): return False
        price=self._shop_offer_price(offer)
        if SAVE.get("coins",0)<price:
            self.unlock_notice="MOEDAS INSUFICIENTES"; self.unlock_notice_timer=2.0; AUDIO.play("hurt",.45,90); return False
        SAVE["coins"]-=price; msg="COMPRA CONFIRMADA!"
        if section=="seuze" and offer.get("type")=="seuze_special":
            msg=self._grant_mystery_item(offer)
            purchased=set(SAVE.get("seuze_shop_purchased",[])); purchased.add(idx); SAVE["seuze_shop_purchased"]=sorted(purchased)
        else:
            if not self._grant_shop_offer(offer,selected_key): SAVE["coins"]+=price; return False
            if section=="daily":
                purchased=set(SAVE.get("daily_shop_purchased",[])); purchased.add(idx); SAVE["daily_shop_purchased"]=sorted(purchased)
            elif section=="seuze":
                purchased=set(SAVE.get("seuze_shop_purchased",[])); purchased.add(idx); SAVE["seuze_shop_purchased"]=sorted(purchased)
        save_data(SAVE); AUDIO.play("upgrade",.85); self.unlock_notice=msg; self.unlock_notice_timer=3.0; self.shop_confirm_offer=None; self.shop_choose_offer=None
        if section=="seuze":
            if len(set(SAVE.get("seuze_shop_purchased",[])))>=len(ensure_seuze_shop()): self._trigger_seuze_phrase("empty")
            else: self._trigger_seuze_phrase("buy")
        return True

    def _equip_owned_shop_offer(self, offer):
        typ=offer.get("type"); key=offer.get("key")
        if typ=="relic" and key in set(SAVE.get("relics_owned",[])):
            SAVE["equipped_relic"]=key; save_data(SAVE); self.unlock_notice="RELIQUIA EQUIPADA: "+offer.get("name",key); self.unlock_notice_timer=2.0; AUDIO.play("click",.65); return True
        if typ=="cosmetic" and key in set(SAVE.get("cosmetics_owned",[])):
            if offer.get("kind")=="theme": SAVE["menu_theme"]=offer.get("value","default")
            else: SAVE["equipped_title"]=offer.get("value","")
            save_data(SAVE); self.unlock_notice="COSMETICO EQUIPADO"; self.unlock_notice_timer=2.0; AUDIO.play("click",.65); return True
        return False

    def shop_click(self,pos):
        if self.shop_confirm_offer is not None:
            if self.shop_confirm_no_rect.collidepoint(pos): self.shop_confirm_offer=None; AUDIO.play("click",.45); return
            if self.shop_confirm_yes_rect.collidepoint(pos): self._execute_shop_purchase(self.shop_confirm_offer); return
            return
        if self.shop_choose_offer is not None:
            if hasattr(self,"shop_choose_cancel_rect") and self.shop_choose_cancel_rect.collidepoint(pos): self.shop_choose_offer=None; return
            for r,key,owned in getattr(self,"shop_choose_rects",[]):
                if r.collidepoint(pos) and not owned:
                    info=self.shop_choose_offer if isinstance(self.shop_choose_offer,dict) else {"section":"daily","index":int(self.shop_choose_offer)}
                    self._open_shop_confirm(info.get("section","daily"),int(info.get("index",-1)),key); self.shop_choose_offer=None; return
            return
        if self.shop_back_rect.collidepoint(pos): self.state="menu"; return
        # Abas sempre tem prioridade sobre a arte do Seu Ze.
        for r,key in getattr(self,"shop_tab_rects",[]):
            if r.collidepoint(pos):
                if key!=self.shop_section:
                    self.shop_section=key; self.shop_scroll_x=0.0; self.shop_scroll_start=0.0; self.shop_scrollbar_drag=False; self.seuze_scroll_y=0.0; AUDIO.play("click",.6)
                    if key=="seuze":
                        AUDIO.force_external_music("seuze_shop", max(0.05,AUDIO.music_volume*0.90))
                return
        if self.shop_section=="seuze" and getattr(self,"seuze_portrait_rect",pygame.Rect(0,0,0,0)).collidepoint(pos):
            self._trigger_seuze_phrase("click"); return
        offers=self._shop_section_offers(); rects=getattr(self,"seuze_item_rects",[]) if self.shop_section=="seuze" else getattr(self,"shop_offer_rects",[])
        for r,idx in rects:
            if r.collidepoint(pos) and 0<=idx<len(offers):
                offer=offers[idx]; status=self._shop_offer_status(offer,idx)
                if status=="EQUIPAR": self._equip_owned_shop_offer(offer); return
                if status: AUDIO.play("click",.3); return
                if offer.get("type")=="choose_weapon": self.shop_choose_offer={"section":self.shop_section,"index":idx}; return
                self._open_shop_confirm(self.shop_section,idx); return

    def _shop_scrollbar_set_from_x(self, x):
        track=getattr(self,"shop_scrollbar_track",pygame.Rect(0,0,0,0)); knob=getattr(self,"shop_scrollbar_knob",pygame.Rect(0,0,0,0))
        if self.shop_section=="seuze":
            mx=max(0.0,float(getattr(self,"seuze_max_scroll",0.0))); travel=max(1,track.w-knob.w)
            if mx<=0: self.seuze_scroll_y=0.0; return
            knob_left=clamp(float(x)-float(getattr(self,"shop_scrollbar_grab_offset",knob.w/2)),track.x,track.right-knob.w); self.seuze_scroll_y=mx*((knob_left-track.x)/travel); return
        mx=max(0.0,float(getattr(self,"shop_max_scroll",0.0))); travel=max(1,track.w-knob.w)
        if mx<=0: self.shop_scroll_x=0.0; return
        knob_left=clamp(float(x)-float(getattr(self,"shop_scrollbar_grab_offset",knob.w/2)),track.x,track.right-knob.w); self.shop_scroll_x=mx*((knob_left-track.x)/travel)

    def shop_down(self,pos,finger_id=None):
        if self.shop_confirm_offer is not None or self.shop_choose_offer is not None:
            self.shop_swipe_start=None; self.shop_swipe_finger=finger_id; return
        if hasattr(self,"shop_scrollbar_track") and self.shop_scrollbar_track.collidepoint(pos):
            self.shop_scrollbar_drag=True; self.shop_swipe_start=None; self.shop_swipe_finger=finger_id
            if self.shop_scrollbar_knob.collidepoint(pos): self.shop_scrollbar_grab_offset=pos[0]-self.shop_scrollbar_knob.x
            else: self.shop_scrollbar_grab_offset=self.shop_scrollbar_knob.w/2; self._shop_scrollbar_set_from_x(pos[0])
            return
        viewport=self.seuze_viewport if self.shop_section=="seuze" else getattr(self,"shop_viewport",pygame.Rect(0,0,0,0))
        if not viewport.collidepoint(pos): self.shop_swipe_start=None; self.shop_swipe_finger=finger_id; return
        self.shop_swipe_start=pygame.Vector2(pos); self.shop_swipe_current=pygame.Vector2(pos); self.shop_swipe_finger=finger_id; self.shop_scroll_start=float(getattr(self,"seuze_scroll_y",0.0) if self.shop_section=="seuze" else getattr(self,"shop_scroll_x",0.0)); self.shop_dragged=False

    def shop_motion(self,pos,finger_id=None):
        if self.shop_swipe_finger is not None and finger_id!=self.shop_swipe_finger: return
        if getattr(self,"shop_scrollbar_drag",False): self._shop_scrollbar_set_from_x(pos[0]); return
        if self.shop_swipe_start is None or self.shop_confirm_offer is not None or self.shop_choose_offer is not None: return
        self.shop_swipe_current=pygame.Vector2(pos); dx=self.shop_swipe_current.x-self.shop_swipe_start.x; dy=self.shop_swipe_current.y-self.shop_swipe_start.y
        if abs(dx)>S(10) or abs(dy)>S(16): self.shop_dragged=True
        if self.shop_section=="seuze":
            raw=self.shop_scroll_start-dy; mx=max(0.0,float(getattr(self,"seuze_max_scroll",0.0)))
            if raw<0: raw*=0.34
            elif raw>mx: raw=mx+(raw-mx)*0.34
            self.seuze_scroll_y=clamp(raw,-self.shop_overscroll,mx+self.shop_overscroll); return
        raw=self.shop_scroll_start-dx; mx=max(0.0,float(getattr(self,"shop_max_scroll",0.0)))
        if raw<0: raw*=0.34
        elif raw>mx: raw=mx+(raw-mx)*0.34
        self.shop_scroll_x=clamp(raw,-self.shop_overscroll,mx+self.shop_overscroll)

    def shop_up(self,pos,finger_id=None):
        if self.shop_swipe_finger is not None and finger_id!=self.shop_swipe_finger: return
        if getattr(self,"shop_scrollbar_drag",False):
            self.shop_scrollbar_drag=False; self.shop_swipe_finger=None; AUDIO.play("click",.18); return
        if self.shop_swipe_start is None:
            self.shop_swipe_finger=None; self.shop_click(pos); return
        start=self.shop_swipe_start; dx=float(pos[0]-start.x); dy=float(pos[1]-start.y); moved=self.shop_dragged or abs(dx)>S(16) or abs(dy)>S(18); self.shop_swipe_start=None; self.shop_swipe_current=None; self.shop_swipe_finger=None; self.shop_dragged=False
        if moved: AUDIO.play("click",.22)
        else: self.shop_click(pos)

    def update_shop_scroll(self,dt):
        if getattr(self,"seuze_phrase_timer",0.0)>0: self.seuze_phrase_timer=max(0.0,self.seuze_phrase_timer-dt)
        if self.shop_swipe_start is not None or getattr(self,"shop_scrollbar_drag",False): return
        if self.shop_section=="seuze":
            mx=max(0.0,float(getattr(self,"seuze_max_scroll",0.0))); target=clamp(float(getattr(self,"seuze_scroll_y",0.0)),0.0,mx)
            if abs(self.seuze_scroll_y-target)<0.35: self.seuze_scroll_y=target; return
            self.seuze_scroll_y+=(target-self.seuze_scroll_y)*min(1.0,12.0*dt); return
        mx=max(0.0,float(getattr(self,"shop_max_scroll",0.0))); target=clamp(float(getattr(self,"shop_scroll_x",0.0)),0.0,mx)
        if abs(self.shop_scroll_x-target)<0.35: self.shop_scroll_x=target; return
        self.shop_scroll_x += (target-self.shop_scroll_x)*min(1.0,12.0*dt)

    def draw_upgrade(self):
        self._draw_ui_background("ONDA CONCLUIDA", "ESCOLHA SEU PROXIMO POWER UP", GREEN)
        if self.unlock_notice_timer > 0: draw_text(self.unlock_notice, self._ui_fonts()["body"], PURPLE, (W-S(320), S(82)), True)
        if self.evolution_notice_timer > 0 and self.evolution_notice: draw_text(self.evolution_notice, self._ui_fonts()["body"], YELLOW, (W/2, S(158)), True)
        rarity_color = {"common": GRAY, "rare": BLUE, "epic": PURPLE, "legendary": YELLOW, "divine": DIVINE_BLUE, "cursed": RED}
        rarity_name = {"common": "COMUM", "rare": "RARO", "epic": "EPICO", "legendary": "LENDARIO", "divine":"DIVINO", "cursed": "AMALDICOADO"}
        self.upgrade_rects = []
        cols, gap = 3, S(18); card_w = int((W-SAFE*2-gap*2)/3); card_h = S(450); y = S(195) if self.evolution_notice_timer > 0 else S(180)
        for i, card in enumerate(self.upgrade_cards):
            rarity, name, desc, key = card; r = pygame.Rect(SAFE+i*(card_w+gap), y, card_w, card_h); selected = self.selected_upgrade_card == card
            edge = WHITE if selected else rarity_color[rarity]
            self._ui_card(r,edge,name,desc=desc,badge=rarity_name[rarity],style=i,featured=selected,title_color=WHITE,desc_color=GRAY,max_lines=4)
            draw_text("SELECIONADO" if selected else "TOQUE PARA MARCAR", self._ui_fonts()["body"], GREEN if selected else rarity_color[rarity], (r.centerx, r.bottom-S(44)), True)
            self.upgrade_rects.append((r, card))
        by=H-CONTROL_SAFE_Y-S(92); reroll=pygame.Rect(CONTROL_SAFE_X,by,S(330),S(82)); confirm=pygame.Rect(W/2-S(250),by,S(500),S(82)); blocker=pygame.Rect(W-CONTROL_SAFE_X-S(330),by,S(330),S(82))
        ready=self.selected_upgrade_card is not None; rr=int(getattr(self,"upgrade_rerolls_left",0)); locked=getattr(self,"upgrade_locked_card",None); tokens=int(SAVE.get("blocker_tokens",0) or 0)
        self._ui_button(reroll,f"REROLL  x{rr}",CYAN,rr>0,1); self._ui_button(confirm,("CONFIRMAR BUFF" if ready else "ESCOLHA UM BUFF"),GREEN,ready,2)
        block_enabled=(ready and locked is None and (tokens>0 or SAVE.get("cheat_items_infinite",False)))
        self._ui_button(blocker,("BLOQUEADO" if locked is not None else f"BLOQUEAR x{tokens}"),YELLOW,block_enabled or locked is not None,3)
        self.upgrade_reroll_rect=reroll; self.upgrade_confirm_rect=confirm; self.upgrade_blocker_rect=blocker

    def draw_death(self):
        title="A GULA" if self.devoured_by_gula else "VOCE MORREU"
        subtitle=("A Gula nao te matou, ela devorou sua experiencia." if self.devoured_by_gula else "SEU HP CHEGOU A ZERO.")
        self._draw_ui_background(title,subtitle,RED)
        button_h=S(72)
        button_y=H-CONTROL_SAFE_Y-button_h
        panel=pygame.Rect(CONTROL_SAFE_X,S(132),W-CONTROL_SAFE_X*2,max(S(300),button_y-S(18)-S(132)))
        self._ui_shape(panel,RED,fill=(14,16,22),style=0,width=3,featured=True)
        stats=[
            ("PERSONAGEM",self.selected_character,RED),("ONDA",str(self.wave),ORANGE),("KOs",str(self.kills),YELLOW),("TEMPO",f"{self.final_time}s",CYAN),
            ("PARRIES",str(self.parries),PURPLE),("PERFECT DODGES",str(self.perfect_dodges),DIVINE_BLUE),("PONTUACAO",str(self.score),GREEN),("MOEDAS",str(self.run_coins),YELLOW),
        ]
        cols=4; gap=S(14); pad=S(18); top=panel.y+pad
        hunger_space=S(34) if self.devoured_by_gula else 0
        card_w=int((panel.w-pad*2-gap*(cols-1))/cols)
        card_h=int((panel.h-pad*2-gap-hunger_space)/2)
        for i,(lab,val,col) in enumerate(stats):
            cx=i%cols; cy=i//cols; rr=pygame.Rect(panel.x+pad+cx*(card_w+gap),top+cy*(card_h+gap),card_w,card_h)
            self._ui_shape(rr,col,fill=(20,22,29),style=i,width=2,featured=(lab=="ONDA"))
            label_box=pygame.Rect(rr.x+S(12),rr.y+S(12),rr.w-S(24),S(48))
            value_box=pygame.Rect(rr.x+S(14),label_box.bottom+S(4),rr.w-S(28),max(1,rr.bottom-label_box.bottom-S(18)))
            draw_fitted_text(lab,[FONT_M,FONT_S,SHOP_FONT_XS,SHOP_FONT_TINY],GRAY,label_box,True)
            draw_responsive_text(str(val),[FONT_XL,FONT_L,FONT_M,FONT_S,SHOP_FONT_XS],col,value_box,2,True,2,"center")
        if self.devoured_by_gula:
            hunger_box=pygame.Rect(panel.x+S(25),panel.bottom-S(37),panel.w-S(50),S(30))
            draw_fitted_text(f"FOME NA PROXIMA VEZ: {self.gula_death_hunger}",[FONT_S,SHOP_FONT_XS,SHOP_FONT_TINY],RED,hunger_box,True)
        retry=pygame.Rect(W/2-S(440),button_y,S(400),button_h); menu=pygame.Rect(W/2+S(40),button_y,S(400),button_h)
        self._ui_button(retry,"TENTAR DE NOVO",RED,True,0); self._ui_button(menu,"MENU",CYAN,True,3)
        self.death_retry_rect=retry; self.death_menu_rect=menu

    def pause_game(self):
        if self.state != "playing":
            return
        self.state = "paused"
        bw, bh = S(520), S(92)
        self.pause_resume_rect = pygame.Rect(W/2-bw/2, H*0.43, bw, bh)
        self.pause_menu_rect = pygame.Rect(W/2-bw/2, H*0.55, bw, bh)
        AUDIO.play("pause", 0.70)
        self.attack_held = False; self.parry_held=False; self.domain_held=False; self.dash_held=False
        for key in self.move_touch:
            self.move_touch[key] = False
        self.active_fingers.clear()
        self.joystick_finger = None
        self.joystick_mouse_active = False
        self.joystick_vector.update(0, 0)

