        overlay=pygame.Surface((W,H),pygame.SRCALPHA); overlay.fill((0,0,0,205)); SCREEN.blit(overlay,(0,0))
        draw_text("PAUSADO",self._ui_fonts()["title"],WHITE,(W*0.27,H*0.16),True)
        bw,bh=S(500),S(82); x=W*0.27-bw/2
        resume=pygame.Rect(x,H*0.28,bw,bh); upgrades=pygame.Rect(x+S(35),H*0.40,bw-S(70),bh); settings_btn=pygame.Rect(x-S(15),H*0.52,bw+S(30),S(68)); menu=pygame.Rect(x+S(55),H*0.63,bw-S(110),S(72))
        self._ui_button(resume,"CONTINUAR",CYAN,True,0); self._ui_button(upgrades,"UPGRADES DA RUN",PURPLE,True,3); self._ui_button(settings_btn,"CONFIGURACOES",BLUE,True,1); self._ui_button(menu,"VOLTAR AO MENU",RED,True,5)
