            draw_responsive_text(desc,[FONT_S,SHOP_FONT_XS],GRAY,pygame.Rect(content.x,content.y+S(53),content.w,S(52)),2,False,2,"center")
            progress=("CONCLUIDA" if ok else f"PROGRESSO {current}/{goal}")+f"   |   RECOMPENSA {reward} MOEDAS"
